export default [{"id":29,"question":"ذهبنا مع بعض الأصدقاء إلى رحلة خارج الرياض، وبالضبط في الثمامة، فخرجنا يوم الأربعاء في الليل، فحينما جاء وقت النوم نمنا، فلما أصبحنا على يوم الخميس، وجدتُ نفسي قد احتلمتُ، وأصبحت علي جنابة، ونحن عددنا أربعة، ولا يوجد معنا غير جالون ماء للشرب والأكل، فأخبرتُ أحد الأصدقاء بما حدث لي، فقال لي: تعفَّر، وصلِّ معنا الفجر، يجوز لك ذلك، فعملتُ ما أمرني به، ولما جاء، وقت صلاة الظهر شككتُ في الأمر، ولم أصلِّ معهم جميع الأوقات من فجر يوم الخميس إلى عشاء ليلة السبت في نهار الجمعة، فلما ذهبنا إلى الرياض صليتها بعد أن اغتسلتُ، وبدون أن أقْصُر في جميع الأوقات فيما فاتني، فماذا عليَّ في ذلك؟","title":"حكم من احتلم في صحراء ولم يجد ماءً للغسل","answer":"الجواب: الواجب عليك إذا وقع مثل هذا أن تنظر، إن وجدتَ ماءً قريبًا منك تستطيع الغسل به فعلتَ، ووجب عليك ذلك، فإن لم تجد تيممت كما قال لك صاحبك، تعفَّرت بالتراب وكفى؛ لأن الله  يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [النساء:43]، ويقول النبي ﷺ: وجُعِلَت لي الأرض مسجدًا وطهورًا فأيما رجل من أمتي أدركته الصلاة فعنده مسجده وطهوره، ويقول ﷺ: وجُعِلَ التراب لي طهورًا إذا لم نجد الماء، فمن لم يجد الماء فالصعيد، وضوءه.\nفعليك إذا فقدتَ الماء في أي مكان أن تتيمم، وتضرب التراب بيديك، وتمسح به وجهك، وكفيك كما أمر الله  وتصلي، وليس عليك إعادة، تجزئ، وإذا كنتَ في محل فيه ماء وجب عليك الغسل، وإذا كان الوقت باردًا سخَّنته بالنار، وإذا لم تجد نارًا وخشيت على نفسك بسبب شدة البرد؛ تيممتَ وصليت، وأجزأك، والحمد لله.\nوأما تركك لصلاة معهم المدة الطويلة يوم الخميس والجمعة، فهذا غلط وخطأ منك، فعليك التوبة إلى الله من ذلك، والندم على ما مضى منك، وعدم العودة إلى ذلك، وقد أحسنتَ في قضاء الصلاة لَمَّا تمكنت من الماء؛ ولكنك أخطأت في تركها، وفي التأخير.\nفالواجب التوبة من ذلك، وألا تؤخرها عن وقتها، إن وجدتَ ماءً فاغتسل، وإلا فتيمم وصلِّ، ولا تؤخرها عن وقتها أبدًا.","link":"https://binbaz.org.sa/fatwas/2809/حكم-من-احتلم-في-صحراء-ولم-يجد-ماء-للغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0002.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":44,"question":"أنا أعمل موظفًا في الهاتف السعودي، والمراقب المسئول يمنعني من تأدية الصلاة في وقت العمل، مع العلم أن المسجد مقابل مبنى الهاتف، فما هو رأي سماحتكم في ذلك؟","title":"حكم تأخير الصلاة للموكّل بأمانة أو حراسة","answer":"الجواب: الواجب عليك أن تصلي في محلك؛ لأنك تشبه الحارس، الحارس إذا كان حارسًا على مال، أو على مزرعة، أو غيرها، يصلي في محله، ولا يلزمه جماعة، إذا كان ذهابه إلى الجماعة يفوِّت الحراسة، وربما جاء في الهاتف ما يدعو إلى الحذر، والحاصل أن من وُكل إليه الهاتف المهم للمسلمين يكون بمثابة الحارس الذي يصلي عند محل الحراسة.\nأما أن يضيع الوقت، لا، يجب أن يصلي في الوقت، ولو قدِّر أن الهاتف تكلم؛ فإن مدة الصلاة مدة قليلة، خمس دقائق أو أقل من ذلك.\nفالواجب أن تصلي الصلاة في الوقت، ولا يجوز أن تُهمل من أجل الحراسة، ولا من أجل الهاتف.\nفإذا كان هناك ضرورة وجب التناوب، فيُجعل هذا الحارس ينوب بعض الوقت، ثم يذهب ويصلي، ويأتي الحارس الآخر وقد صلى، فينوب عنه.\nأما أن يوكَل إليه حراسة تمنعه من الصلاة؛ فهذا ظلم، ولا يجوز.","link":"https://binbaz.org.sa/fatwas/2824/حكم-تاخير-الصلاة-للموكل-بامانة-او-حراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0017.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":70,"question":"تقول في سؤالها الأخير: هل تتلاقى الأرواح بعد الموت؟","title":"هل تتلاقى الأرواح بعد الموت في القبور؟","answer":"الجواب: الله أعلم، جاء فيها مراءٍ كثيرة في التلاقي، والله أعلم ، جاء أشياء تدل على أنها قد تتلاقى روح المؤمن مع روح المؤمن الحي في النوم، وقد وجد في هذا أمثلة كثيرة تدل على وجود ذلك، ولكن ليس في هذا أحاديث صحيحة عن النبي ﷺ تدل على ذلك فيما نعلم، ولكن وُجد منامات تدل على هذا وعلى وقوعه.","link":"https://binbaz.org.sa/fatwas/2988/هل-تتلاقى-الارواح-بعد-الموت-في-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0047.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":76,"question":"الادِّعاء أن ستة مليارات من الناس المنتشرين على سطح البسيطة سيكون مصيرهم النار، هكذا بموجب فتوى لا تستند إلى الحقِّ والعدل، ويقول: إن أتباع جميع الدِّيانات السَّماوية باستثناء المُحَرِّفين لكتاب الله سيذهبون إلى الجنة فيما إذا عملوا صالحًا؛ تحقيقًا لقوله تعالى: إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَادُوا وَالنَّصَارَى وَالصَّابِئِينَ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَالِحًا فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ [البقرة:62] إلى آخر ما قال.فما توجيهكم؟","title":"ما مصير أتباع الرسل قبل الإسلام؟","answer":"الجواب: مَن آمن بالله واليوم الآخر من جميع الأمم واتَّبع الرسلَ لا شكَّ أنه إلى الجنة: إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَادُوا وَالنَّصَارَى وَالصَّابِئِينَ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَالِحًا فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ، فمَن آمن بالله ورسله من هذه الأمة، ومن بني إسرائيل، ومن اليهود، والنَّصارى، ومن غيرهم من الأمم؛ كلهم إلى الجنة، وكل مَن تابع الرسلَ من أولهم إلى آخرهم فهو إلى الجنة، ومَن عصاهم وخالفهم فهو إلى النار.\nولا شكَّ أنَّ أكثر الخلق إلى النار، وأقلَّهم إلى الجنة، كما قال جلَّ وعلا: وَمَا أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ [يوسف:103]، وقال جلَّ وعلا: وَإِنْ تُطِعْ أَكْثَرَ مَنْ فِي الْأَرْضِ يُضِلُّوكَ عَنْ سَبِيلِ اللَّهِ [الأنعام:116]، وقال سبحانه: وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ فَاتَّبَعُوهُ إِلَّا فَرِيقًا مِنَ الْمُؤْمِنِينَ [سبأ:20].\nلكن في آخر الزمان: إذا رفع اللهُ القرآنَ، وأرسل الريحَ التي تقبض أرواح المؤمنين والمؤمنات لا يبقى إلَّا الأشرار، فعليهم تقوم الساعة، وهم من أهل النار؛ لأنهم بقوا على الشرك بالله وعبادة غيره، فعليهم تقوم الساعة -نسأل الله العافية: لا تقوم الساعةُ حتى لا يُقال في الأرض: الله، الله، وفي روايةٍ: حتى لا يُقال في الأرض: لا إله إلَّا الله -نسأل الله السلامة.\nوأما القول بأنَّ جميع أهل الأرض في النار، فهذا كلامٌ باطلٌ، بل مَن آمن بالله واليوم الآخر فهو من أهل الجنَّة، وإنما يكون من أهل النار مَن كفر بالله وخالف أمره، لكن في آخر الزمان بعد رفع الكتاب العزيز، وبعد موت المؤمنين والمؤمنات؛ يبقى الأشرار، وعليهم تقوم الساعة، وهم من أهل النار -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/3042/ما-مصير-اتباع-الرسل-قبل-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0053.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":124,"question":"سائل يقول: ما الأمور التي يستطيع العبدُ بها الخلاص من المعاصي؟","title":"ما أسباب تجنب المعاصي؟","answer":"الجواب: مثلما تقدم: لزوم التقوى، أن يلزم طاعة الله، ويتذكر الوقوف بين يدي الله، ويعلم أنه خُلق ليعبد الله ويُطيعه، فيُحاسِب نفسه، فبهذا يُعينه الله، ويقيه شرَّ المعاصي، بالتَّذكر، ومُراقبة الله، وكونه يعلم أنه مسؤولٌ وأنه موقوفٌ بين يدي الله، وأنَّ هذه الدار دار العمل، وليست دار اللَّهو والغفلة، فإذا تذكَّر هذه الأمور وراقب الله؛ أعانه الله على ترك المعاصي، وعلى الاستقامة على طاعة الله.","link":"https://binbaz.org.sa/fatwas/3622/ما-اسباب-تجنب-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0109.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":132,"question":"إذا تاب العبدُ من معصيةٍ ارتكبها، وبعد فترةٍ عاد إليها، ثم تاب، لكن أيضًا بعد التوبة بفترةٍ يعود إلى المعصية، فما حكم ذلك؟ وبماذا تنصحونه؟","title":"حكم من يتوب من المعصية ثم يعود إليها","answer":"الجواب: إذا تاب من المعصية محا الله عنه المعصية، إذا تاب صادقًا مُحيت المعصية بالتوبة، فالتوبة تَجُبُّ ما قبلها، وإذا عاد إليها من جديدٍ صار الإثمُ من جديدٍ على المعصية الجديدة، وأما الأولى التي تاب منها توبةً صادقةً فقد مُحيت عنه، فكل توبةٍ تمحو ما قبلها، ويبقى عليه الجديد.\nفعليه أن يُلاحظ التوبة، ويلزمها، ويجتهد في سلامته من الذنوب، وأما التوبة فتجُبُّ ما قبلها، فلا يؤخذ بالذنب الأول إذا تاب منه توبةً صادقةً.","link":"https://binbaz.org.sa/fatwas/3659/حكم-من-يتوب-من-المعصية-ثم-يعود-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0121.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":161,"question":"رجلٌ أسرف على نفسه، ولكنه تاب إلى ربِّه، ومع هذا فهو خائفٌ من الذنوب السَّابقة، مما سبب له الخوف الذي يُؤدي به إلى الوساوس، أرجو إرشاد هذا ليتخلص من الوساوس؟","title":"بم يُنصح من تاب ويخاف الذنوب السابقة؟","answer":"الجواب: إذا أسرف الإنسانُ على نفسه، ثم هداه الله ومَنَّ عليه بالتوبة فليحمد الله، وليعلم أنَّ الله جلَّ وعلا إنما مَنَّ عليه بالتوبة رحمةً منه سبحانه وفضلًا منه؛ ليُطهره وليغسله من المعايب، فليحمد الله، وليُبْشِر بالخير، وليحذر الشيطان ونزغاته، فإن الشيطان قد يُوقعه في وساوس وفي ظنونٍ سيئةٍ فليحذر ذلك، ولا يُطع عدوَّ الله، فالله جلَّ وعلا أخبر أنَّ العبد إذا تاب وآمن وعمل صالحًا تاب الله عليه، وبدَّل سيئاته حسنات، قال سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]، وفي الحديث الصحيح: التَّائِب من الذنب كمَن لا ذنبَ له، فالتائب يغفر الله له سيئاته، ويمحو عنه أخطاءه.\nفعليك يا أخي بالتوبة ولزومها، واحذر الوساوس والظنون السَّيئة التي حرَّمها الله عليك.","link":"https://binbaz.org.sa/fatwas/3699/بم-ينصح-من-تاب-ويخاف-الذنوب-السابقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0155.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":198,"question":"سائلٌ يقول: احتلم وجاءت صلاةُ الفجر، ولعدم وجود الملابس وشدَّة البرد ما استطاع أن يغتسل، فترك حتى جاء الظهرُ، حيث تمكَّن من وجود الملبس والطّهور، فما الحكم؟","title":"حكم من أخّر الغُسْل والصلاة لشدة البرد","answer":"الجواب: الواجب عليه إذا لم يتيسر له الماء الدَّافئ ولا اللباس أن يتيمم بالتراب: يضرب الترابَ بيديه بنية الجنابة ونية الحدث الأصغر –الوضوء- ويمسح وجهه وكفَّيه ناويًا الجنابة والوضوء جميعًا، ويُصلي على حسب حاله، ولا يُؤخِّر الصلاة أبدًا، وإذا أخَّرها أثم، وعليه الغسل، ويقضي الصلاة التي عليه، لكن يلزمه أن يُصلي في الوقت ولو بالتيمم، وإذا أمكنه أن يُسخن الماء وأن يجد الملبس الذي يُعينه على الدفء وجب عليه ذلك، وإلا صلَّى بالتيمم ولا يُؤخِّر الصلاة عن وقتها.","link":"https://binbaz.org.sa/fatwas/3796/حكم-من-اخر-الغسل-والصلاة-لشدة-البرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0205.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":232,"question":"لي نفسٌ تُحبّ الخير، ولكنها ضعيفةٌ لا تثبت أمام المعصية، فكلما رأيتُ معصيةً ضعفت أمامها، فهل هناك دواء أو شفاء لذلك تدلونا عليه؟","title":"ما دواء الضعف أمام المعاصي؟","answer":"الجواب: نعم، قال الله تعالى: وَخُلِقَ الْإِنْسَانُ ضَعِيفًا [النساء:28]، لكن الله أعطاك أسلحةً حتى تقوى، أعطاك الأسلحة التي بها يقوى قلبُك، وهي طاعة الله، والإكثار من ذكره، والتفكر في عظمته وما له من الحقِّ عليك، وأنك صائرٌ إليه، وأنك مسؤولٌ: فَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ ۝ عَمَّا كَانُوا يَعْمَلُونَ [الحجر:92- 93]، وأنك مستحقٌّ للعقاب على سيئاتك، وللثواب على طاعتك، ففكِّر ولا تتبع الهوى فيُضلك عن سبيل الله.\nومعلوم أنَّ النفس أمارةٌ بالسوء إلا ما رحم الله، فلا تُجبها إلى هواها، قال تعالى: وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَى ۝ فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَى [النازعات:40- 41]، فمتى دعتك إلى المعصية فذكّرها بأنَّ الخطر عظيم، وأنها منهية عن معصية الله، وأنها متوعدة بغضب الله وعقابه، إلا أن يعفو الله، وأنت لا تدري هل تموت على ذلك؟ هل يُعفى عنك أو تُعذب؟\nفجاهدها وذكّرها، واحذر مغبة التَّساهل، فإذا وُفِّقْتَ لهذا؛ أعانك الله عليها، وسلمتَ من شرِّ هذه النفس.","link":"https://binbaz.org.sa/fatwas/4090/ما-دواء-الضعف-امام-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0242.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":235,"question":"يقول أنه شابٌّ، وتمر عليه فترات في اليوم يحسّ فيها بزيادةٍ في الإيمان، وفترات أخرى يحسّ فيها بأنَّ الإيمان ينقص، فيسأل ويقول: ما الأسباب التي تُؤدي إلى زيادة الإيمان وإلى نقصانه؟","title":"ما الأسباب التي تؤدي لزيادة الإيمان ونقصه؟","answer":"الجواب: هذه الدنيا هي دار الابتلاء والامتحان، فهي مختبرٌ، يُبتلى فيها الإنسانُ بما يزيد إيمانه، وبما ينقص إيمانه، فتارةً يتلو القرآن، ويتدبر القرآن، ويُكثر من ذكر الله؛ فيزيد إيمانه، وتارةً يصحب الأخيار، ويستفيد من علمهم وصحبتهم الطيبة؛ فيزداد إيمانه، ويُجاهد في سبيل الله، ويأمر بالمعروف، وينهى عن المنكر، ويدعو الناس إلى الخير؛ فيزداد إيمانه، وتارةً يُبتلى بجُلساء سوءٍ، بالغفلة عن الله، بالإقبال على زهرة العاجلة؛ فيضعف الإيمان، وينقص إيمانه.\nفالإنسان في هذه الدار بين مدٍّ وجزرٍ، فكلما شُغل بآخرته وبالأعمال الصَّالحة زاد إيمانه، وكلما شُغل بضدِّ ذلك نقص إيمانه.\nوالإيمان عند أهل السنة والجماعة يزيد وينقص، خلاف ما تقوله الخوارج والمعتزلة، فأهل السنة والجماعة عندهم الإيمان قولٌ وعملٌ وعقيدةٌ، يزداد بالطاعات، وينقص بالمعاصي، فكلما اجتهد في الطاعات، وذكر الله، وصُحبة الأخيار، وأنواع الخير؛ زاد إيمانه وقوي، وكلما شُغل بأمورٍ أخرى: من الغفلة، والإعراض عن المذاكرة، وعن صحبة الأخيار، والإقبال على شهوات الدنيا وزينتها؛ ضعف إيمانُه، ورقَّ إيمانه، وهو بين مدٍّ وجزرٍ، وعلى خطرٍ إذا مال إلى ما يُضعف الإيمان، وعلى خيرٍ عظيمٍ إذا التزم بما يُقوي إيمانه.\nفعلى المؤمن أن يحذر أسبابَ النقص، وليجتهد في أسباب الزيادة، وذلك بالإقبال على القرآن الكريم والسنة المُطهرة، والاستكثار من الطاعات، وأنواع الذكر، والاستغفار، والتوبة، وصحبة الأخيار، والحذر من قرب الأشرار وصحبة الأشرار، والحذر من الغفلة، وطاعة النفس الأمَّارة بالسوء، والإقبال على الملذَّات والشهوات، مُتناسيًا أمر الآخرة، وأمر الجنة والنار، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/4093/ما-الاسباب-التي-تودي-لزيادة-الايمان-ونقصه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0245.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":236,"question":"كيف نُرشد الشباب إلى أن يستغلوا كلَّ الوقت فيما يُرضي الله من قولٍ وعملٍ، علمًا بأنَّ هناك مَن يُعارض هذا؛ حيث يقول: ليس كل شيء دينًا، أو: ليست الحياة كلها يجب فيها أن نلتزم فيها بهذا الشيء، فهو يفصل بين الدِّين والدنيا؟ فما رأي فضيلتكم؟","title":"ما النصيحة للشَّباب في قضاء الأوقات؟","answer":"الجواب: النَّصيحة للشباب وغير الشباب مطلوبة؛ لأنَّ النصيحة متى أُهملت غلب على النفوس الهوى وحبُّ العاجلة وحبُّ الراحة وحبُّ الشهوات، فالنَّصائح كالسياط التي يُجاهد بها الإنسان، ويُقاد بها إلى الخير؛ تُرقق قلبه، وتُذكره بالآخرة، فلا بدّ من النَّصيحة والتَّوجيه والدَّعوة، وإلا ضاعت الحياةُ بالغفلات والشَّهوات.\nولهذا شرع الله التَّذكير ودعا إليه فقال سبحانه: وَذَكِّرْ فَإِنَّ الذِّكْرَى تَنْفَعُ الْمُؤْمِنِينَ [الذاريات:55]، وقال: فَذَكِّرْ إِنَّمَا أَنْتَ مُذَكِّرٌ [الغاشية:21]، فَذَكِّرْ إِنْ نَفَعَتِ الذِّكْرَى [الأعلى:9]، وَلَوْ أَنَّهُمْ فَعَلُوا مَا يُوعَظُونَ بِهِ لَكَانَ خَيْرًا لَهُمْ وَأَشَدَّ تَثْبِيتًا ۝ وَإِذًا لَآتَيْنَاهُمْ مِنْ لَدُنَّا أَجْرًا عَظِيمًا  ۝  وَلَهَدَيْنَاهُمْ صِرَاطًا مُسْتَقِيمًا [النساء:66- 68].\nفالعبرة والتذكير فيها الخير العظيم، والمصلحة العظيمة، والنبي عليه السلام يقول: الدِّين النَّصيحة، هكذا يقول النبيُّ ﷺ: الدين النصيحة، الدين النصيحة يُكررها ثلاثًا، قيل: لمَن يا رسول الله؟ قال: لله، ولكتابه، ولرسوله، ولأئمة المسلمين، وعامَّتهم رواه مسلمٌ بدون تكرار، ولكن جاء مُكرَّرًا في روايةٍ أخرى عند أبي دواد وغيره؛ لتدل على الأهمية.\nفالنصيحة مطلوبة لا بدّ منها، ولكن مع النَّصيحة لا بدّ من الغفلة بعض الشيء، في حديث حنظلة لما دخل على النبيِّ ﷺ قال: يا رسول الله، نافق حنظلة، قال: لم ذاك؟! قال: نكون عندك فتُذكرنا الجنة -أو قال: الآخرة- كأنا نراها رأي العين؛ فترقّ قلوبُنا، فإذا خرجنا عافسنا النساء والأولاد والضّيعات ونسينا كثيرًا، فقال عليه الصلاة والسلام: لو أنَّكم تدومون على ما تكونون عندي لصافحتكم الملائكةُ في طرقاتكم، وعلى فُرشكم، ولكن يا حنظلة ساعة وساعة، فلا بدّ من وجود شيءٍ من مشاغل الدنيا: من طلب الرزق، من التحدث مع الأهل والأولاد، من البيع والشراء، إلى غير ذلك.\nفالساعات التي فيها طلب الرزق والجلوس مع الأهل تُعتبر خوضًا لا تضرُّ العبد، ما لم يأثم فيها، ما لم يخلطها بالحرام: من الغيبة، والنميمة، والكذب، وشهادة الزور، وغير هذا مما حرَّم الله.\nأما الدَّعوة إلى الله، والتذكير، والنصيحة، والحرص على حفظ الوقت، فهذا أمرٌ مطلوبٌ، ومع هذا كله لا بدّ من شيءٍ، لا بدّ من ساعاتٍ لحاجات الإنسان، لا تضرُّه، وقد تُعينه على الخير.\nولهذا قال ﷺ: ولكن ساعة وساعة يعني: ساعة للدين والعمل والجد، وساعة للدنيا وأعمالها: من تجارةٍ، وزراعةٍ، وغير هذا مما يكون مع الأهل والأولاد، والله المُستعان.","link":"https://binbaz.org.sa/fatwas/4106/ما-النصيحة-للشباب-في-قضاء-الاوقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0246.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":281,"question":"يوجد كثيرٌ من الشباب يُصلِّي، ولكنه لا يحضر قلبه في الصلاة، فهو يسهو عن صلاته، فما نصيحتكم إلى هؤلاء الشباب حتى تتم صلاتهم؟","title":"ما النصيحة لتحقيق الخشوع في الصلاة؟","answer":"الجواب: الواجب على المؤمن الإقبال على صلاته، وأن يتذكر أنه بين يدي الله، وأنه يُناجي الله، كما قال النبيُّ ﷺ: إذا قام أحدُكم في الصلاة فإنه يُناجي الله، فأنت يا عبدالله تُناجي ربَّك في الصلاة، وقائم بين يديه، فجديرٌ بك أن تُقبل على صلاتك، وأن تطرح بصرك إلى مواضع سجودك، وأن تستشعر في قلبك أنك بين يدي الله العظيم الجليل، حتى تخشع له، وتطمئن إليه، وتُعظّم كتابه وعبادته. وتحذر عدوك الشيطان، وإذا غلبك هذا العدو فانفُثْ عن يسارك ثلاث مرات وقل: \"أعوذ بالله من الشيطان الرجيم\"، ثلاث مرات، فقد اشتكى عثمان بن أبي العاص الثَّقفي إلى النبي ﷺ وقال: إنَّ الشيطان لبَّس عليَّ صلاتي، فقال له: انفث عن يسارك ثلاث مرات وقل: أعوذ بالله من الشيطان الرجيم، ففعل ذلك فعافاه الله.\nفإذا غلب هذا العدو عليك وأنت في الصلاة فانفث عن يسارك ثلاث مرات وقل: \"أعوذ بالله من الشيطان الرجيم\"، ولا يضرُّك، وهذا من العلاج العظيم النبوي، وهو حديثٌ ثابتٌ عن النبيِّ ﷺ، رواه الإمام أحمد وغيره.\nس: هل هذا النَّفث عند كل صلاةٍ؟\nالشيخ: إذا غلب عليه الوسواس، إذا أحس بالوساوس وكثرت عليه؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/4279/ما-النصيحة-لتحقيق-الخشوع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0328.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":282,"question":"أنا شابٌّ أحاول إذا كنتُ أقرأ القرآن أو أُصلي أو أتذكر حال المسلمين أن أبكي، ولكن لا أستطيع، فما أسباب ذلك؟ وما العلاج؟","title":"ما أسباب عدم الخشوع والبكاء؟ وما العلاج؟","answer":"الجواب: لهذا أسبابٌ كثيرةٌ، عدم البكاء له أسبابٌ، منها: قسوة القلوب بسبب المعاصي والذنوب، فإنَّ القلوب إذا قست قلَّت دمعةُ العين، وإذا حاسب نفسَه واتَّقى الله وترك معصيته واستقام على أمره خشع قلبه، ودمعت عينه.\nومن ذلك: الغفلة بالوساوس التي تعرض على قلبه هاهنا وهاهنا حتى تشغله عن الخشوع ودمع العين، فقد يكون في نفسه تقيًّا، ولكن تغلب عليه الوساوس حتى تشغله عن ذكر الله، وعن تعظيمه، وعن الخشوع بين يديه، وقد يُبتلى بأفكارٍ ترد عليه تشغله أيضًا.\nفينبغي أن يجمع قلبَه على صلاته، وعلى قراءته، وعلى ذكره لله؛ وعند هذا يخشع القلب، وتدمع العين.","link":"https://binbaz.org.sa/fatwas/4280/ما-اسباب-عدم-الخشوع-والبكاء-وما-العلاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0329.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":293,"question":"هل إفرازات المرأة -سواء كانت متزوجةً أم لا- طاهرةٌ أم لا، على اللباس؟","title":"حكم الإفرازات التي تخرج من المرأة","answer":"الجواب: هذا محل نظرٍ، ما يخرج منها من السَّائلات فالأصل فيه أنه كالبول، هذا هو الأصل، أما الرطوبة العادية التي تكون رطوبةً بدون سائلٍ فهذه أمرها سهل، لكن الشيء الذي يخرج ويسيل من الفرج فهذا حكمه حكم البول، الذي يظهر لنا أنه نجسٌ يتحرز منه، كالقطرة ونحوها.\nوهذا إذا كان مستمرًّا معها، تتحرز منه، أما إذا كان يعرض ويزول فهذا يكفي فيه الاستنجاء، والحمد لله.","link":"https://binbaz.org.sa/fatwas/4295/حكم-الافرازات-التي-تخرج-من-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0342.mp3","categories":["قضايا المرأة","النجاسات وإزالتها","التيمم"]},{"id":295,"question":"إذا تاب العبدُ من معصيةٍ ارتكبها، وبعد فترةٍ عاد إليها، ثم تاب، لكن أيضًا بعد التوبة بفترةٍ يعود إلى المعصية، فما حكم ذلك؟ وبماذا تنصحونه؟","title":"حكم من يتوب من المعصية ثم يعود إليها","answer":"الجواب: إذا تاب من المعصية محا الله عنه المعصية، إذا تاب صادقًا مُحيت المعصية بالتوبة، فالتوبة تَجُبُّ ما قبلها، وإذا عاد إليها من جديدٍ صار الإثمُ من جديدٍ على المعصية الجديدة، وأما الأولى التي تاب منها توبةً صادقةً فقد مُحيت عنه، فكل توبةٍ تمحو ما قبلها، ويبقى عليه الجديد.\nفعليه أن يُلاحظ التوبة، ويلزمها، ويجتهد في سلامته من الذنوب، وأما التوبة فتجُبُّ ما قبلها، فلا يؤخذ بالذنب الأول إذا تاب منه توبةً صادقةً.","link":"https://binbaz.org.sa/fatwas/4297/حكم-من-يتوب-من-المعصية-ثم-يعود-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0344.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":411,"question":"عرَّفت أن المعصية هي من مرض القلب، فأرجو أن تدلني على كتابٍ يُبين علاج المعصية، وجزاكم الله خيرًا.","title":"ما علاج القلب للتغلب على المعاصي؟","answer":"الجواب: لا ريب أنَّ أصل المعاصي من مرض القلوب: إما بالانحراف والهوى، وإما بالتَّكبر، وإما بالجهل والغفلة، وأعظم دواء وأحسن كتابٍ لعلاج أمراض القلوب كتاب الله سبحانه وتعالى القرآن الكريم، هو أحسن كتابٍ، وأصدق كتابٍ، وأنفع كتابٍ، وأوضح كتابٍ، فليس بعده كتابٌ، بل هو أعظم الكتب وأشرفها وأحسنها دواءً وبيانًا للدواء.\nفعليك يا أخي، وعلينا جميعًا رجالًا ونساءً، علينا جميعًا أن نُعالج أمراضنا بتدبر القرآن، والإكثار من تلاوته، والمذاكرة فيه بين الزميل وزميله، والمرأة وزميلتها؛ للتفاهم بمعاني كلام الله، ومراجعة التفاسير الطيبة: كتفسير ابن كثير، وابن جرير، وهكذا المختصرات؛ لأن التفاسير تُعين على فهم كتاب الله، هذا أحسن كتابٍ، وأعظم كتابٍ، وأشرف كتابٍ، يقول الله سبحانه في كتابه العظيم: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، ويقول سبحانه: يَا أَيُّهَا النَّاسُ قَدْ جَاءَتْكُمْ مَوْعِظَةٌ مِنْ رَبِّكُمْ وَشِفَاءٌ لِمَا فِي الصُّدُورِ وَهُدًى وَرَحْمَةٌ لِلْمُؤْمِنِينَ [يونس:57].\nفعليك يا أخي بكتاب الله، وعلينا جميعًا بكتاب الله: تلاوةً، وتدبُّرًا، وتعقُّلًا؛ وبذلك تحصل الفائدة العظيمة، ويحصل الدواء، ويحصل الشفاء بتوفيق الله.\nثم سنة الرسول ﷺ وأحاديثه فيها أيضًا من الدواء ما فيها، فهي الوحي الثاني، والأصل الثاني، ومن أحسن الكتب في ذلك الصحيحان: \"صحيح البخاري\" و\"مسلم\"، ثم بعدهما بقية الكتب الستة، ولكن بالنسبة إلى عامَّة الناس المختصر من هذه الكتب: كـ\"رياض الصالحين\" و\"بلوغ المرام\" و\"عمدة الحديث\"، هذه كتب مفيدة، \"منتقى الأخبار\" لابن تيمية، هذه كتب في الحديث مفيدة ومختصرة، ومن أخصرها وأبينها \"رياض الصالحين\"، فصاحبه قد اختار الأحاديث الجيدة في الغالب، واعتنى بذلك، وهو كتابٌ جيدٌ مفيدٌ، وهكذا \"بلوغ المرام\" كتابٌ محررٌ مفيدٌ، و\"عمدة الحديث\" للشيخ عبدالغني المقدسي كتابٌ عظيمٌ، وهكذا \"الترغيب والترهيب\" إذا قرأه طالبُ العلم واختار منه الأحاديث الأولى منه، وهي الأحاديث الصَّحيحة التي يبدأ بها، وهو كتابٌ عظيمٌ، ثم بعد ذلك بعض كتب أهل العلم المؤلفة في هذا، مثل: \"الجواب الكافي\" لابن القيم، ذكر فيه الذنوب: شرَّها ودواءها، سماها \"الدَّاء والدواء\"، وهو كتابٌ جيدٌ لابن القيم رحمه الله، وكتاب \"الفوائد\" لابن القيم أيضًا كتابٌ مفيدٌ ونافع، فهذان الكتابان من خير الكتب فيما أعلم.\nونسأل الله للجميع التوفيق.","link":"https://binbaz.org.sa/fatwas/4828/ما-علاج-القلب-للتغلب-على-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0469.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":422,"question":"أنا شابٌّ تبتُ إلى الله ، ثم استمررتُ في التوبة، وأحسستُ بحلاوة الإيمان، ثم عصيتُ الله، ثم رجعتُ إلى التوبة، فهل أستمر في ذلك؟","title":"ما حكم من تاب من المعصية ثم عاد إليها؟","answer":"الجواب: عليك أن تحمد الله وتشكره على ما مَنَّ عليك من التوبة، وما جرى من المعصية التي عقبتها التوبة؛ يمحوها الله ، وقد سمعت في البحث: إِلَّا مَنْ تَابَ وَآمَنَ [الفرقان:70] من كلام الله ، والله يقول: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، ويقول النبي ﷺ: التائب من الذنب كمَن لا ذنبَ له، فالزم التوبةَ واستقم عليها، واحذر أن يستزلك الشيطانُ مرةً أخرى.\nفعليك بلزوم التوبة، ومُجالسة الأخيار، والحذر من الأشرار، فإنه قد يجرّك الشيطان إلى المعصية، ثم تموت عليها قبل توبتك، احذر أن يجرّك الشيطان إلى المعاصي فتنزل بك المنية وأنت على المعصية: من صدم، أو انقلاب سيارة، أو سكتة، أو غير ذلك. الزم التوبةَ، الزمها قبل أن يهجم عليك الأجلُ، واحذر غرور الشيطان وطاعته، الشيطان يقول: افعل، افعل، وتب، مَن يقول لك أنَّك تتوب؟! قد يُطبع على قلبك، ويقسو قلبك؛ فلا تتوب، قد يهجم الأجلُ عليك وأنت على المعصية ما تبتَ، فتلقى الله بالمعصية.\nفعليك بلزوم التوبة والحذر، وسَلْ ربَّك التوفيق والهداية، فالأمور بيده ، والقلوب بيده جلَّ وعلا، فاضرع إليه دائمًا أن يهديك، وأن يُثبتك، وأن يُعيذك من الشيطان ونزغاته، ومن جُلساء السوء.","link":"https://binbaz.org.sa/fatwas/4846/ما-حكم-من-تاب-من-المعصية-ثم-عاد-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0480.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":423,"question":"ما أكبر الذنوب؟ وما أصغرها؟","title":"ما أكبر الذنوب؟ وما أصغرها؟","answer":"الجواب: أكبر الذنوب: الشرك بالله، هو أعظم ذنبٍ، ثم يلي ذلك: قتل النفس بغير حقٍّ، ثم يلي ذلك: الزنا بزوجة الجار، ثم عقوق الوالدين -نسأل الله العافية- ثم شهادة الزور التي هي من أقبح المحرمات -نعوذ بالله- ثم الأيمان الغموس، الأيمان الفاجرة التي يُقتطع بها حقّ المسلم. ثم بقية كبائر الذنوب: كالربا، وأكل مال اليتيم، والتولي يوم الزحف، وقذف المحصنات الغافلات، وشرب المسكرات، وغير هذا من كبائر الذنوب، وهي كثيرة.\nأما صغائر الذنوب: فهي الذنب الذي نهى الله عنه، لكن لم يرد فيه وعيدٌ بلعنٍ ولا بنارٍ ولا بغضبٍ ولا بحدٍّ في الدنيا، هذه يُقال لها: الصغائر، التي نهي عنها ولكن لم يرد فيها وعيدٌ بنارٍ ولا بغضبٍ ولا بحدٍّ يُقام على صاحبها، فهذه يُقال لها: من الذنوب الصغيرة، وهي معصية ومحرَّمة.","link":"https://binbaz.org.sa/fatwas/4847/ما-اكبر-الذنوب-وما-اصغرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0481.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":424,"question":"رجل يرتكب الذنوبَ من سرقةٍ وزنا وغيره، وقد يسرق ولا يُعيد ما سرقه، وقد يستلف مالًا ولا يُعيده، وقد تراكمت عليه الذنوب، فماذا يجب عليه أن يفعل من ناحية التوبة؟","title":"ماذا يفعل من أراد أن يتوب من ذنوبه؟","answer":"الجواب: عفو الله أوسع، وباب التوبة مفتوح حتى تطلع الشمسُ من مغربها، أو حتى يموت، فعليه البدار بالتوبة والندم والإقلاع الصَّادق من هذه الذنوب، وعليه بذل الوسع في ردِّ الحق إلى أهله، رد الأموال إلى أهلها بكل طريقٍ، فإن جهله ولم يستطع الوصول إليهم تصدَّق بها عنهم للفقراء والمحاويج بالنية عنهم، والله يؤدي عنه سبحانه وتعالى.\nفدواء الذنوب التوبة إلى الله، هذا دواؤها: التوبة الصَّادقة النَّصوح، الصادقة بالندم على الماضي، والإقلاع عن الذنوب، والحذر منها، واتباع التوبة بالعمل الصالح، هكذا يكون الصَّادقون، كما قال : إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُولَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ [الفرقان:70]، وقال سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، وقال تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8]، فالتوبة الصاَّدقة يمحو الله بها الذنوب.\nوعلى العبد إذا صدق أن يرد الحقَّ إلى أهله: من سرقةٍ، وخيانةٍ، وغير هذا من الأموال التي أخذها، أو قتلٍ؛ يُسلّم نفسه حتى يُقتل قصاصًا، أو يرضى بالدية منه، حتى يؤدي الحقوقَ التي عليه صادقًا، وإذا جهل أهلَ الحقوق تصدَّق عنهم بالمال الذي سرقه، أو أخذه منهم، أو استلفه منهم وضيَّعه عليهم، إذا لم يعرفهم ونسي محلهم، أو نسي بلادهم، يتصدَّق به عنهم، وإذا علم يرد إليهم حقَّهم بالطريق التي تُوصلها إليهم، ولو ما سمَّى نفسه، يرد إليهم أموالهم بالطريقة التي تمكنه، من غير أن يُسمِّي نفسه، لا حاجة إلى تسمية نفسه.","link":"https://binbaz.org.sa/fatwas/4848/ماذا-يفعل-من-اراد-ان-يتوب-من-ذنوبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0482.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":426,"question":"ما علاج قسوة القلوب الذي كثر في هذا الزمان، فالقرآن يُقرأ والقليل يبكي؟","title":"ما كيفية علاج قسوة القلوب؟","answer":"الجواب: علاجها: التوبة إلى الله، علاج قسوة القلوب التوبة إلى الله، والإكثار من قراءة القرآن، والإكثار من ذكر الله ، والحذر من الذنوب والمعاصي، والتوبة إلى الله منها، ومجالسة الأخيار، والحذر من الأشرار، كل هذا علاج: الإقبال على كتاب الله بتدبُّرٍ، والإكثار من ذكر الله. والإكثار من الصلاة والعبادة. والتوبة إلى الله من الذنوب. والحرص على الكسب الحلال، والبعد عن الحرام. ومجالسة الطيبين الأخيار، فإن لم تجدهم فالزم بيتك، إلا في وقت الصلاة، وإذا ما وجدتَ الأخيار فمن بيتك إلى المسجد، ومن المسجد إلى بيتك، إلا للحاجة الضَّرورية التي تأخذها من السوق. وإذا وجدت الأخيار فالزمهم وجالسهم، وهم الذين يذكرون الله، ويُعينون على طاعته، ويُذكِّرون بحقِّه، ويبتعدون عن المعاصي والشُّرور.","link":"https://binbaz.org.sa/fatwas/4850/ما-كيفية-علاج-قسوة-القلوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0484.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":434,"question":"أُشهد الله  أنني أُحبُّك فيه، وأريد منك أن تُجيب لي على هذا السؤال، وهو أنني شابٌّ ولله الحمد من الشباب الصَّالحين، ولكنني أتحول إلى أن أكون من أتباع الشياطين، حيث إنني أُصاحب بعض الأشرار، فأكون معهم في جميع أعمالهم أو أغلبها، ولكنني عندما أحضر مجالس الصَّالحين أتحول إلى شابٍّ صالحٍ، فما نصيحتكم لي ولأمثالي من الشباب؟ جزاكم الله خيرًا.","title":"بِمَ يُنصح من يتأثر بالصحبة صالحةً أو فاسدة؟","answer":"الجواب:\n\nأما المحبَّة فقد سبق الجواب عن ذلك، نقول: أحبَّك الله الذي أحببتنا له.\nوهنا ملاحظة: قول الإنسان: أنا من الصَّالحين، أو من المؤمنين، ينبغي أن يقول: \"إن شاء الله\"، فأهل السنة والجماعة يستثنون؛ لأن كونه صالحًا أو كونه مؤمنًا والشهادة من نفسه له بذلك محل نظرٍ، قد يكون قصَّر في ذلك وهو لا يدري، ولا يدري ماذا يُختم له به؟ فليقل: أنا من الصالحين إن شاء الله، أو من المؤمنين إن شاء الله؛ تحرزًا مما قد يقع من التقصير: بترك واجبٍ، أو فعل محظورٍ، والصلاح إنما يكمل بأداء حقِّ الله وحقِّ عباده، ومَن الذي يستطيع أن يقول: إني أديتُ حقَّ الله وحقَّ عباده، وهكذا الإيمان مما يتم بأداء حقِّ الله وحقِّ عباده.\nأما ما ذكرتَ: فالواجب عليك يا أخي أن تحذر صحبة الشياطين، وأن تبتعد عنهم، وعليك بصحبة الأخيار حتى تسلم من شرِّ الأشرار، وقد جاء في الحديث عنه عليه الصلاة والسلام -وهو الحديث الصحيح- أنَّ مثل الجليس الصالح ومثل الجليس السُّوء كصاحب المسك ونافخ الكير، فاختر لنفسك أن تكون مع أهل المسك الذي إمَّا أن يُعطيك، وإما أن تبتاع منه، وإما أن تجد منه ريحًا طيبةً، واحذر أن تكون مع أهل الكير: إما أن يحرق ثيابك، وإما أن تجد منه ريحًا خبيثةً.\nوفي الحديث الآخر يقول ﷺ: المرء على دين خليله، فلينظر أحدُكم مَن يُخالل. والشاعر يقول:\n\n\n\t\n\t\t\n\t\t\tعن المرء لا تسأل وسَلْ عن قرينه\n\t\t\tفكل قرينٍ بالمقارن يقتدي\n\t\t\n\t\n\nوجُلساء السُّوء كانوا سبب ضلال أبي طالب عم النبي ﷺ، جلسوا عنده عند موته ولقَّنوه التَّعصب لدين قومه حتى قال للنبي ﷺ: \"أنا على ملة عبدالمطلب\"، وأبى أن يقول: لا إله إلا الله، بأسباب جلساء السوء.\nفالواجب على المؤمن وعلى طالب العلم وعلى كل مسلمٍ أن يحذر جُلساء السوء، وأن يبتعد عنهم، وألا يُصاحبهم، وأن يختار لنفسه أصحاب الخير، فإن لم يجد فليلزم بيته، ولا يخرج إلا لحاجةٍ أو للصلاة أو لما شرع الله من الأمور الأخرى، ولا يتَّخذ أصحابًا يُضلونه ويصدُّونه عن الحقِّ.","link":"https://binbaz.org.sa/fatwas/4858/بم-ينصح-من-يتاثر-بالصحبة-صالحة-او-فاسدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0492.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":439,"question":"يعيش الشابُّ فترات من عمره محافظًا على الطاعات، وبعيدًا عن المعاصي، ولكنه لا يلبث أن يتكاسل ويضعف، فما الأسباب المُساعدة على الثبات على الخير، على شكل نقاطٍ حتى لا أنساها؟","title":"ما الأسباب المعينة في الثبات على الخير؟","answer":"الجواب: هذا يقع من كثيرٍ من الناس، وله أسباب، منها: فتوره عن التعلم والتفقه في الدين والمزيد من العلم، فبسبب ذلك يضعف عن الصبر والثبات؛ لقلة علمه، وقلة اجتهاده في التحصيل.\nومنها: أن يُبتلى بصاحبٍ أو أكثر من الأشرار، فيقوده إلى الشر، ويُثبطه عن الخير، فإنَّ الجليس السَّيئ ضرره عظيم، وخطره كبير، كما قال النبيُّ ﷺ: مثل الجليس الصالح والجليس السُّوء كحامل المسك ونافخ الكير، فحامل المسك إمَّا أن يُحذيك –يعني: يُعطيك شيئًا منه- وإما أن تبتاع منه، وإما أن تجد منه ريحًا طيبةً، ونافخ الكير إمَّا أن يحرق ثيابك، وإما أن تجد منه ريحًا خبيثةً، وهكذا الحديث الآخر: المرء على دين خليله، فلينظر أحدُكم مَن يُخالل، فمن المُهِمَّات: صحبة الأخيار، والزملاء الطيبين.\nومنها: أن يُبتلى بالأسفار إلى البلاد الخبيثة -إلى الخارج- يكون مستقيمًا ثم يُبتلى بالسفر إلى بلاد الكفر: إنجلترا أو فرنسا أو أمريكا أو غير ذلك، فيقع في حبائل الشيطان ودعاة الباطل، فيترك ما كان عليه سابقًا، ويقع في الفواحش والخمور والزنا؛ فيهلك، ولا حول ولا قوة إلا بالله!\nأما مَن صبر على حاله الأولى، واستقام عليها، واجتهد في صحبة الأخيار، واستمر في طلب العلم والتفقه في الدين؛ فإنه في الغالب يبقى على حاله، ويسلم من مكائد الشيطان، ومكائد الأعداء.\nفنصيحتي لطالب العلم ولنفسي ولكل مسلم: أن يلزم الحقَّ، وأن يستقيم عليه، وأن يستمر في طلب العلم والتفقه في الدين وصحبة الأخيار، والحذر من السفر إلى بلاد الكفرة. فهذه النقاط الثلاث من أهم المهمات:\nالاستمرار في العلم، والحرص على المزيد من العلم، والصبر على ما هو عليه من الدين.\nمع الحرص على صحبة الأخيار، والاستقامة على ما هم عليه.\nمع الحذر من السفر إلى البلاد الخارجية التي فيها الشر المنتشر، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/4864/ما-الاسباب-المعينة-في-الثبات-على-الخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0497.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":472,"question":"عفا الله عنك، هل يُشرع عند التيمم النفخ في اليدين؟","title":"هل يُشرع النفخ في اليدين عند التيمم؟","answer":"الجواب: إذا كان هناك تراب زائد ينفخ كما نفخ النبي ﷺ.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6197/هل-يشرع-النفخ-في-اليدين-عند-التيمم","audio":"https://files.zadapps.info/binbaz.org.sa/nf7'032.mp3","categories":["التيمم"]},{"id":473,"question":"التيمم على الأرض الرطبة، أحسن الله إليك؟","title":"كيف يكون التميم على الأرض الرطبة؟","answer":"الجواب: يزيل الرطوبة ويتيمم بعدها.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6198/كيف-يكون-التميم-على-الارض-الرطبة","audio":"https://files.zadapps.info/binbaz.org.sa/ard033.mp3","categories":["التيمم"]},{"id":474,"question":"الآية: فَامْسَحُواْ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ [المائدة:6] أي من الغبار؟","title":"ما معنى {فَامْسَحُواْ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ}؟","answer":"الجواب: من التراب الصعيد يعني فَتَيَمَّمُواْ صَعِيداً طَيِّباً[المائدة:6]، إذا تيسر فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]","link":"https://binbaz.org.sa/fatwas/6199/ما-معنى-فامسحوا-بوجوهكم-وايديكم-منه","audio":"https://files.zadapps.info/binbaz.org.sa/AYA034.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":475,"question":"الغسل ورد عن رسول الله ﷺ صفتين في صفة الغُسْل، أحسن الله إليك؟","title":"ما صفة الغُسْل الوادرة عن النبي ﷺ؟","answer":"الجواب: المعروف عن عائشة وعن ميمونة هو الوضوء ثم إفاضة الماء، وجاء عن  ميمونة: أنه يغسل قدميه في مكان آخر.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6200/ما-صفة-الغسل-الوادرة-عن-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/3osl035.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":715,"question":"ما حكم مَن يتيمم مع وجود الماء؟ وما حكم صلاته وهو على هذه الحال وقتًا طويلًا؟ وهل يكون بهذا العمل كافرًا؟","title":"ما حكم التيمم مع وجود الماء؟","answer":"الجواب: مَن يتيمم والماء موجود لا يجوز له هذا، صلاته باطلة، الله يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [المائدة:6]، إذا كان يتيمم وهو صحيحٌ -ليس بمريضٍ- يستطيع استعمال الماء، والماء موجود، فإنه تكون صلاته باطلة، وحكمه حكم مَن ترك الصلاة، إذا كان عالمًا عارفًا لا جاهلًا كفر -نسأل الله العافية- أما إذا كان جاهلًا يُعلَّم؛ لأنَّ هذا قد يجهله بعض الناس.\nفالحاصل أنه ليس له أن يتيمم مع وجود الماء، ومع القدرة على استعماله. أما إن كان مريضًا يضرُّه الماء، أو الماء غير موجودٍ، فإنه يتيمم، كما قال الله سبحانه: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [المائدة:6]، والمريض الذي يضرُّه الماء من جنس العادم.\nفإذا كان صلَّى بغير الماء وهو جاهلٌ: إن كانت قليلةً صلَّاها وأعادها، وإن كانت كثيرةً نرجو أنها تسقط عنه لجهله؛ لأن الرسول ﷺ لما علَّم المسيء في صلاته -وكان ينقرها نقرًا- أمره أن يُعيدها، ولم يأمره أن يُعيد ما مضى من صلواته، التي يظهر من حاله أنه فعلها كذلك، وإنما أراد أن يُعيد الحاضرة؛ لجهله وعدم بصيرته.","link":"https://binbaz.org.sa/fatwas/20569/ما-حكم-التيمم-مع-وجود-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0524فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["التيمم"]},{"id":825,"question":"شخصٌ رأى في ثوبه أثرَ احتلامٍ، وتذكر أنه رأى في منامه ما سبب هذا منذ أربعة أو خمسة أيام، لا يدري أنه احتلم، ولم يدرِ عن ذلك، وصلَّى صلوات، فلما رأى هذا الأثر اغتسل، فماذا عليه؟ هل يُعيد صلاته التي صلَّاها هذه الفترة وهو لا يدري؟","title":"حكم مَن رأى أثر احتلام مضت عليه أيام","answer":"الجواب: إذا علم أنها مني فعليه أن يُعيد بعد آخر نومةٍ نامها؛ لأن هذا هو المتيقن، فإذا كان مثلًا رآها العصر، وآخر نومةٍ الضُّحى –الصبح- فهو يُعيد الظهر والعصر، وإذا كانت آخر نومةٍ الظهر، وما رآها إلا بعد العصر، يُعيد العصر، وهكذا، يعني: من آخر نومةٍ نامها ثم رأى المني يُعيد الصلاة التي بعد النومة؛ لأن الظاهر أنها من النومة الأخيرة، ولا يعمّم على النومات السَّابقات.","link":"https://binbaz.org.sa/fatwas/20866/حكم-من-راى-اثر-احتلام-مضت-عليه-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0661شخص رأي في ثوبه أثر احتلام وتذكر أنه رأى في منامه ماسبب هذا فما الحكم؟ابن باز.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":835,"question":"ما حكم الرجل يموت على التوحيد وقد خلط عملًا صالحًا وآخر سيئًا؟ هل يُعذَّب في قبره إلى يوم قيام الساعة أم إلى وقتٍ معلومٍ ويُرفع عنه العذاب؟","title":"حكم من مات مُوَحِّدا قد خلط صالحًا وسيئًا","answer":"الجواب: هذا أمره إلى الله، يقول الله سبحانه: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]، فأمره إلى الله، تحت مشيئته: إن شاء غفر له وعفا عنه، وإن شاء عذَّبه بعض العذاب في القبر، وبعض العذاب في النار، وإن شاء عذَّبه شيئًا دون شيءٍ ، فأمره إلى الله، هو الذي يعلم أحوال عباده ، لكنه على خطرٍ، مَن مات على السيئات غير تائبٍ هو على خطرٍ في القبر ويوم القيامة -نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/20876/حكم-من-مات-موحدا-قد-خلط-صالحا-وسيىا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0671ما حكم الرجل يموت على التوحيد وقد خلط عملاً صالحاً وآخر سيئاً يعذب في قبره إلى قيام الساعة؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":851,"question":"في حديث الإسراء والمعراج الذي رُوي عنه ﷺ ورد أنه ﷺ رأى أناسًا يُعذَّبون.و هل هناك عذاب قبل يوم القيامة غير عذاب القبر؟ أفيدونا جزاكم الله خيرًا.","title":"هل هناك عذاب قبل القيامة غير عذاب القبر؟","answer":"الجواب: هذا يُفسَّر بأنَّ هؤلاء صُوّروا له يُعذَّبون بسبب أعمالهم الخبيثة المنكرة، ويحتمل أن هذا العذاب لهم في الدنيا، ويحتمل أنه مثال لعذابهم الذي يكون يوم القيامة، فإنه ﷺ رأى في نومه ملكين أخذا بيده وأرياه جماعةً من المعذَّبين: من آكل الربا، ومن الزُّناة والزَّواني، ومن الذي ينام عن الصلاة حتى تطلع الشمس ولا يُصلي، ويحفظ القرآنَ ولا يعمل به، فهو يحتمل أمرين: أحدهما: أن هذا العذاب يحصل لهم في القبر في أرواحهم في البرزخ، وأنه عذابٌ عُجِّل لهم. ويحتمل أن المراد بذلك أنَّ هذا هو جنس العذاب الذي يحصل لهم يوم القيامة، وأن هذا مما يُعذَّبون به يوم القيامة في النار -نسأل الله العافية والسلامة.\nوبكل حالٍ فهو وعيدٌ عظيمٌ يُفيد الحذر من هذه الأعمال الخبيثة، سواء كان ذلك في البرزخ، أو في الآخرة، والأظهر والأقرب -والله أعلم- أنه في البرزخ -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/20878/هل-هناك-عذاب-قبل-القيامة-غير-عذاب-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0673هل هناك عذاب قبل يوم القيامة غير عذاب القبر؟ ابن باز فتاوى المحاضرات.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":888,"question":"ما السلوك السَّليم الذي يجب أن يسلكه المرءُ ليكون مسلمًا مؤمنًا حقًّا؟","title":"ما الذي يجب على المرءُ ليلزم طريق الحق؟","answer":"الجواب: كما تقدَّم: السلوك السليم هو أن تستقيم على شريعة الله كما دلَّ عليه كتابُ الله، وكما جاءت سنةُ رسول الله ﷺ؛ أن تبحث وتعرف طريق الصَّحابة، وما سلكوا مع نبيهم ﷺ، فتتبع منهجه ﷺ: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، وقال تعالى: وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالْأَنْصَارِ وَالَّذِينَ اتَّبَعُوهُمْ بِإِحْسَانٍ رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ [التوبة:100]، عليك بهذا الطريق، طريق النبي ﷺ، وطريق أصحابه، ومَن سلك سبيلَهم، وهم أهل السنة والجماعة: في أقوالك وأعمالك، في كل شيءٍ، واحذر البدع كلها.","link":"https://binbaz.org.sa/fatwas/20911/ما-الذي-يجب-على-المرء-ليلزم-طريق-الحق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0706ما هو السلوك السليم الذي يجب أن يسلكه المرء ليكون مسلماً مؤمناً حقاً؟ابن باز فتاوى المحاضرات.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":925,"question":"إذا كان على إحدى يدي أو كلتيهما جبس أو بهما جروح، فكيف التيمم؟ وهل حدّ الوجه في التيمم مثله في الوضوء؟","title":"كيف يتيمم من بيده جِبْس؟ وما حد الوجه؟","answer":"الجواب: نعم، حدّ الوجه بالتيمم كالوضوء: يمسح وجهه من أعلى الجبهة إلى اللحية وما يلي الأذنين، الخدين، باليدين، وإذا كان على رجله جبس أو على يديه يكفي المسح على الظاهر، يمسح بالماء، ما يحتاج ترابًا؛ لأنَّ الجبس ما يضرُّه الماء، فيمسح على اليدين بالماء، والوجه بالتراب إذا كان يضرُّه الماء، وأما اليد المستورة بالجبيرة أو بالجبس أو الرِّجْل كذلك يمسح عليها بالماء؛ لأنها مثل الجبيرة.\nوإذا كانت الرِّجْل بعضها مستور وبعضها ظاهر: فالمستور يمسح عليه، وطرفها الظاهر يُغسل إذا أمكن الغسل، وإذا كان يضرُّه الماء تيمم..... ما يحتاج المسح في التيمم، ما في إلا الوجه والكفّين.\nالمقصود أنه إذا كان في الرِّجْل جبسٌ وهو يتوضأ يمسح على الجبس ويكفي، أما إذا كان يضرُّه الماء فالتيمم يكون للوجه والكفّين خاصةً.","link":"https://binbaz.org.sa/fatwas/20959/كيف-يتيمم-من-بيده-جبس-وما-حد-الوجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0755إذا كان على أحدى يديه أو كلتاهما جبس فكيف التيمم وهل حد الوجه في التيمم مثله في الضوء؟ ابن باز.mp3","categories":["التيمم"]},{"id":926,"question":"لا أستطيع الوضوء بنفسي، وليس عندي مَن يُساعدني، فهل أتيمم، علمًا بأنَّ المُستشفى يُنظف يوميًّا الجدران والأرض والفرش؟ فكيف أتيمم والحال ما ذكرت؟","title":"حكم تيمم من لا يستطيع الوضوء ولا معين له","answer":"الجواب: إذا كان المريضُ ليس عنده مَن يُوضئه، ولا يستطيع أن يتوضأ بنفسه فإنه يتيمم، وقد كتبنا لمعالي الوزير الصحة العام الماضي والذي قبله: إيجاد تراب تحت أسِرَّة المرضى، حتى يتيمَّموا إذا لم يستطيعوا الوضوء، وجاء الجواب منه بأنه عمَّم على المستشفيات ذلك؛ لإحضار ما يتيمم به المريض في المستشفيات، وهذا واردٌ، فإنه إذا كان ما عنده قدرة على الماء، وليس عنده مَن يُوضئه، أو ما يستطيع الوضوء، فإنه يتيمم بوجود ترابٍ نظيفٍ تحت السرير في إناءٍ، أو في أي وعاءٍ، يتيمم منه المريض ويكفي ذلك عن الوضوء.\nولا يجوز ترك المريض هكذا، بل إما ماء، وإما شيئًا يتيمم به، وإذا كانت الفرشُ نظيفةً، والجدارُ نظيفًا ما فيه غبار؛ لابدّ من إيجاد شيءٍ فيه غبار، التراب في صحنٍ، أو في كيسٍ يتيمم منه عند الحاجة، كلما وُجدت الحاجةُ ضرب بيديه التراب على الكيس، أو على البساط الذي فيه التراب، أو الصحن الذي فيه التراب، بالطيب النظيف، شيء خفيف، ثم يتيمم للوجه والكفَّين، الرجل والمرأة جميعًا، ويكفي ذلك عن الماء إذا عجز عن الماء.\nأما الدُّبر والقُبُل فهذا يكفي فيه المناديل، يستعمل المناديل أو يستعملها الممرض أو الممرضة، إذا كان الرجلُ لا يستطيع، والمرأة لا تستطيع؛ يمسح الدبر والفرج بالمناديل ثلاث مرات أو أكثر، لا بدّ من ثلاثٍ أو أكثر حتى يتنقى المحل، ويكفي عن الماء، فإذا مسح المريضُ دبره وقبله بالمناديل الطيبة الطاهرة الخشنة حتى يُزيل الأذى، والمرأة كذلك من أثر البول والغائط ثلاث مرات فأكثر، النبي نهى أن يُستنجى بأقل من ثلاثٍ، ثلاث فأكثر، سواء لبن، أو حجر، أو مناديل، يستنجي بها الإنسانُ، والمناديل كافية إذا كانت نظيفةً وطاهرةً وخشنةً، يستنجي بها من البول والغائط ثلاث مرات أو أكثر حتى يتنقّى المحل، إذا كفت الثلاثُ فالحمد لله، وإلا زاد رابعة وخامسة حتى يتيقن","link":"https://binbaz.org.sa/fatwas/20958/حكم-تيمم-من-لا-يستطيع-الوضوء-ولا-معين-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0754لا استطيع الوضوء نفسي وليس عندي من يساعدني فهل أتيمم؟ ابن باز فتاوى المحاضرات.mp3","categories":["التيمم"]},{"id":1015,"question":"ما علامات المؤمن عند الموت، وكذلك الكافر؟","title":"ما علامات المؤمن والكافر عند الموت؟","answer":"الجواب: علامات المؤمن عند الموت: الإكثار من ذكر الله، والخوف والخشية منه ، والبدار بالتوبة، ويُروى عنه عليه الصلاة والسلام أنه قال: المؤمن يموت بعرق الجبين، قال بعضُهم: معناه: يعرق جبينه عند الموت، وقال بعضُهم: معناه: أنه يموت وهو كافلٌ كادحٌ، يكسب ويطلب الرزقَ الحلال، يعمل حتى يموت.\nفالعلامات الواضحة: توبته إلى الله، وإقلاعه من الذنوب، وإكثاره من ذكر الله وطاعته، وإظهار الخير، والندم على ما مضى منه من الشر، هذه علامات الخير، وعلامات الإيمان. والضدُّ بالضدِّ: الغفلة عن الله، وعن ذكره، هذه من علامات الشرِّ، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21061/ما-علامات-المومن-والكافر-عند-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0857ما هي علامات المؤمن عند الموت وكذلك الكافر؟ ابن باز فتاوى المحاضرات.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1031,"question":"أرجو من سماحتكم أن تُبيِّنوا لنا طريقة التَّيمم الصَّحيحة؟","title":"ما الطريقة الصحيحة في التيمم؟","answer":"الجواب: التَّيمم بالصعيد مثلما قال الله : فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ [النساء:43]، مسحة واحدة لليد والوجه، يضرب التراب، يعني: يضع يديه في التراب ضربًا، التراب الطيب الطاهر في الأرض، أو في الإناء الذي فيه التراب، أو الخرقة التي فيها التراب، أو الفراش الذي فيه التراب، ثم يمسح وجهه وكفّيه، يمسح وجهه هكذا، وكفَّيه هكذا...، ثم كفّيه هكذا... التراب يمسح به وجهه، ثم يمسح بالبقية كفّيه ظاهرهما وباطنهما، هذا هو التيمم. وليس هناك حاجة إلى مسح الذراعين أو الرأس، لا، من فضل الله وتيسيره أنه سبحانه جعل الوجه واليدين كافيين، في الوضوء يغسل وجهه ويديه، ويمسح رأسه وأذنيه، ويغسل رجليه، لكن في التيمم ربنا جلَّ وعلا يسَّر وسهَّل، وجعل الوجه والكفَّين كافيين، يمسح المريضُ وجهَه وكفَّيه ويكفي، والحمد لله.\nويقوم التيمم مقام الماء على الصحيح، إذا تيمم صلَّى بالتيمم النافلة والفريضة، والحاضرة والمستقبلة، ما دام على طهارةٍ، حتى يُحدِث أو يجد الماء إن كان عادمًا له، أو حتى يستطيع استعماله إذا كان عاجزًا عن استعماله؛ لأن التيمم طهورٌ يقوم مقام الماء، كما سمَّاه النبيُّ: طهورًا.","link":"https://binbaz.org.sa/fatwas/21097/ما-الطريقة-الصحيحة-في-التيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0893ما هي الطريقة الصحيحة في التيمم؟ ابن باز فتاوى المحاضرات.mp3","categories":["التيمم"]},{"id":1064,"question":"هذا يقول بأنه أحسَّ أنه ارتكب ذنبًا عظيمًا، يقول: حتى أحسّ أنني منافقٌ، وأني لم أسلم من عذاب الله، فصرتُ أخاف الله، وأخاف ذنوبي، وأخاف من سُوء الخاتمة، وأن أموت على النفاق، فبِمَ تنصحني فضيلة الشيخ؟","title":"بم يُنصح مَن أحس بالنفاق بعد ذنب عظيم؟","answer":"الجواب:\nأنصحك بالحذر من الوساوس هذه، وحُسن الظن بالله، يقول الربُّ جل وعلا: أنا عند ظن عبدي بي، وأنا معه إذا دعاني، فعليك بحُسن الظن بالله، وإياك وسُوء الظن بالله، ويقول ﷺ: لا يموتَنَّ أحدٌ منكم إلا وهو يُحْسِن ظنَّه بالله، فالمؤمن يُحسن ظنَّه بربه، ويجتهد في طاعة ربِّه، والتوبة إليه، فإذا أحسستَ بذنبٍ فبادر بالتوبة والرجوع إلى الله والنَّدم، وعليك بحُسن الظن بالله، وأنه جوادٌ كريمٌ، يغفر الذنوبَ، ويتوب على التَّائبين، ولكن لا تأمن، لا تتساهل، كن بين الرجاء والخوف كما تقدَّم، تُبادر بطاعة الله، وتحذر معاصي الله، وتكون حَسَنَ الظنِّ بالله، راجيًا له، خائفًا منه سبحانه وتعالى، وإياك وسُوء الظن بالله، فإنَّ هذا يُفضي إلى القنوط واليأس، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/21119/بم-ينصح-من-احس-بالنفاق-بعد-ذنب-عظيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0915يقول السائل بأنه أحس أنه أرتكب ذنباً عظيماً حتى أحسب أني منافق وأموت على النفاق فما نصيحتكم؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1070,"question":"هل يُجزئ الغُسل عن الوضوء لأداء الصَّلاة؟","title":"هل يُجزئ الغُسل عن الوضوء لأداء الصَّلاة؟","answer":"الجواب:\nإذا كان الغسلُ للجنابة ونويتَ الحدثين؛ أجزأ. ولكن كونك تتوضأ كما توضأ النبيُّ ﷺ، ثم تغتسل، هذا هو الأكمل والأفضل. أما الغسل المستحبّ: كالجمعة، أو للتَّبرد، أو لإزالة الوسخ؛ فلا، لا بدّ من الوضوء، توضأ قبله أو بعده.","link":"https://binbaz.org.sa/fatwas/21112/هل-يجزى-الغسل-عن-الوضوء-لاداء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0908هل يجزء الغسل عن الوضوء لأداء الصلاة ؟ ابن باز فتاوى المحاضرات.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":1071,"question":"بماذا تنصحونني؟ فقد ابتُليتُ بالنظر إلى بعض المُحرَّمات، مثل: مُسارقة النظر إلى المرأة، سواء على الطبيعة، أو على طريق مجلة، أو تلفاز. أفيدونا جزاكم الله خيرًا وأبقاكم.","title":"ما النصيحة لمن ابتُلي بالنظر إلى النساء؟","answer":"الجواب:\nقد بيَّن الله  حكمه في ذلك فقال سبحانه: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30]، فأنت احتسب نفسك من هؤلاء، جاهدها، إذا كنتَ ترجو أن تكون من المؤمنين فجاهدها ولا تنظر إلى النساء والمردان، لا في التلفاز، ولا في المجلات، ولا في الأسواق، ولا في أي شيءٍ نظرة شهوةٍ. أما النظر العابر الذي لا تقصد به الشَّهوة، أو صدفة، مثلما قال النبيُّ ﷺ لما سُئل عن نظر الفجأة قال: اصرف بصرك، وقال: إنَّ لك الأولى، وليست لك الأخرى، فالشيء الذي كان صدفةً ما قصدتَه لا حرج عليك. أما أن تقصد وتُتابع النظر فلا، وهكذا مع المردان الذين قد تتحرك الشهوةُ بالنظر إليهم، تحذر ذلك.","link":"https://binbaz.org.sa/fatwas/21111/ما-النصيحة-لمن-ابتلي-بالنظر-الى-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0907ما نصيحتكم بمن ابتلي بالنظر إلى النساء؟ فتاوى المحاضرات ابن باز.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1091,"question":"لقد علمنا أهمية طلب العلم، فحرصنا على ذلك، غير أننا صُدمنا بالواقع؛ إذ تعجّ الحياة بالمُتناقضات، فما يُبنى في سنةٍ تهدمه الوسائلُ الأخرى في ليلةٍ، فتنشأ النَّاشئة في المُجتمعات الإسلامية نشأةً مُتناقضةً، يقرؤون آيةَ الحجاب في الصباح فيرون ما يُناقضها في المساء، فما الواجب تجاه ذلك؟","title":"كيف يواجه المسلم غُربة الدين آخر الزمان؟","answer":"الجواب:\nهذا هو الابتلاء والامتحان، ولا سيما في آخر الزمان، مثل زماننا هذا، نحن في آخر الزمان، وفي غُرْبَةٍ من الدين، فلا بدّ من الصبر، كما أخبر النبيُّ ﷺ: يأتي على الناس زمانٌ الصابر على دينه كالقابض على الجمر، ويقول ﷺ: بدأ الإسلامُ غريبًا، وسيعود غريبًا كما بدأ، فطُوبى للغُرباء خرجه مسلمٌ في \"الصحيح\"، زاد غيره في لفظٍ: مَن الغرباء؟ قال: الذين يصلحون إذا فسد الناسُ، وفي لفظٍ آخر: يُصلحون ما أفسد الناسُ من سنتي، وفي حديث أبي ثعلبة: للعامل منهم أجر خمسين، قيل: يا رسول الله، منا أو منهم؟ قال: بل منكم.\nوأسباب ذلك قلَّة الأنصار والأعوان، وكثرة المهالك والشُّبَه، وكثرة طرق الضَّلالة والدُّعاة إليها، فلهذا الصابر في آخر الزمان على العلم والعمل له أجر خمسين من الصحابة، مثل أجر خمسين؛ لأنهم يجدون أعوانًا، وفي أول مجيء الإسلام، وفي نشاط الإسلام، ونشاط المسلمين، وقوة الإسلام، وقوة المسلمين، وكثرة الأعوان، واندحار الأعداء.\nأما في آخر الزمان فالعكس؛ كثرة الأعداء، وكثرة دُعاة الضَّلالة، وقلَّة الأنصار، وقلة المعين على الحقِّ، مع كثرة الشُّبَه، فهذا صراعٌ بين الحقِّ والباطل في آخر الزمان شديد، فلا بد من صبرٍ على ما تعلمه، فإذا عرف مما تعلم الحقّ ثم رأى ما يُضاده؛ حمد الله على بصيرةٍ، وحمد الله أن جعله ممن عرف هذا الحقَّ، ثم يعمل بما يستطيع من إنكار المنكر، والدعوة إلى الخير، حتى يُحقق ما علم.\nوهذا يشمل ما يتعلق بالعقائد، وما يتعلق بفروعه، وهذا مما يُسبب عظيم الأجور، وكثرة الحسنات، لمن صبر واحتسب، ويُبصره أيضًا بالعلم، يزيده علمًا، فإنَّ وجود المتناقضات مما يُعين على التوسع في العلم، والتَّبصر، ومعرفة الشُّبَه لإزالتها والقضاء عليها، ومعرفة السُّبل التي تُعين على الحقِّ وتهدي إليه، حتى ينشرها بين الناس، ويدعو إليها.","link":"https://binbaz.org.sa/fatwas/21125/كيف-يواجه-المسلم-غربة-الدين-اخر-الزمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0921تعج الحياة بالمتناقضات فما يبنى في سنة تهدمه الوسائل الأخرى في ليلة فما هو الواجب تجاه ذلك؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1107,"question":"إذا مات الرجلُ الصالحُ: هل يُنَعَّم في القبر أم يدخل الجنة؟ وكذلك الفاسق الكافر: هل يُعذَّب في القبر أم يدخل النار؟ أرجو التوضيح جزاكم الله خيرًا.","title":"ما كيفية عذاب القبر ونعيمه للميّت؟","answer":"الجواب:\nالقبر إمَّا روضة من رياض الجنة، أو حفرة من حفر النار، وهو أول منازل الآخرة، وأخبر النبي ﷺ أنَّ المؤمن إذا وُضع في قبره يُفتح له بابٌ إلى الجنة، ويرى مقعده من الجنة، ويأتيه من روحها ونعيمها، فضلًا من الله جلَّ وعلا، ويُفتح له بابٌ إلى النار، ويُقال: هذا مقعدك لو كفرتَ، فالآن هذا مقعدك من الجنة، فيراهما جميعًا حتى يتم سروره ويغتبط بفضل الله عليه: أن أجاره من النار، وأدخله الجنة، وفتح له بابًا إليها.\nوبعد البعث والنُّشور والموقف يوم القيامة بعد ذلك ينتقل المؤمنون إلى دورهم في الجنة، أما في الدنيا في القبور فيأتيه من نعيمها وروحها وطيبها وهو في قبره، وينال جسده نصيبه من ذلك، والروح تُنعَّم في الجنة، أرواح المؤمنين تنقل إلى الجنة كما في الحديث الصحيح: أنها طائر يعلق بشجر الجنة، حتى يردَّها الله إلى جسدها، وترد إلى الجسد متى شاء الله ذلك جلَّ وعلا.\nأما أرواح الشُّهداء -أرواح المقتولين في سبيل الله- فهؤلاء أرواحهم في أجواف طيرٍ خُضْرٍ تسرح في الجنة حيث شاءت، ثم تأوي إلى قناديل مُعلَّقة تحت العرش، كما جاء به الخبر عن رسول الله عليه الصلاة والسلام.\nوالكافر بضدِّ ذلك: إذا وُضع في قبره يُعذَّب في قبره، ويناله من العذاب ما شاء الله من ذلك، وروحه تُعذَّب في النار، ومع الجسد، لكن نعيم الروح وعذاب الروح أكمل، ويوم القيامة يُدخل الكافرُ النار، روحه وجسده يدخلان النار، والمؤمن بروحه وجسده إلى الجنة، أما في الدنيا فينال الجسد نصيبه من النعيم -جسد المؤمن- وينال جسد الكافر نصيبه من العذاب، وروحه نعيمها أكمل، وعذابها أكمل في الدنيا، روح المؤمن تُنَعَّم في الجنة، وروح الكافر تُعذَّب في النار، قال تعالى في آل فرعون: النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ [غافر:46]، فدلَّ على أنَّ أرواحهم في الدنيا يُصيبها نصيبها من العذاب في القبر، وفي خارج القبر، وهكذا المؤمن يحصل لروحه من النعيم في القبر، وفي خارج القبر، وتنقل إلى الجنة كما تقدم، وتكون طائرًا يسرح في الجنة حيث شاء، ويردّها الله إلى جسدها متى شاء .","link":"https://binbaz.org.sa/fatwas/21172/ما-كيفية-عذاب-القبر-ونعيمه-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0968إذا مات الرجل الصالح هل ينعم في القبر أم يدخل الجنة؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1112,"question":"أنا إنسانٌ أكثرتُ في المعاصي، ومن المعاصي والذنوب، ولكن الحمد لله ربّ العالمين الذي مَنَّ عليَّ بالهداية، فلقد تغيرت حياتي، ولكن أحسّ في قلبي أنَّ الله  لن يغفر لي ذنوبي التي ارتكبتُ من قبل، فبماذا تنصحني؟وبهذه المناسبة المباركة أسألك بالله الذي لا إله غيره أن تدعو لي ولكلِّ واحدٍ مثلي في هذا المكان المُبارك الطيب دعوةً بالمغفرة والقبول، لعلَّ الله سبحانه وتعالى أن يتجاوز عنَّا، ويجزيكم عنا.","title":"ما حكم من تاب ويخشى أنه لا يُغفر له؟","answer":"الجواب:\nأسأل الله  أن يقبل توبتك، وأن يُصلح قلبك وعملك وسائر المسلمين، أسأل الله أن يُصلح قلوبنا وأعمالنا جميعًا، وأن يمُنَّ علينا بالتوبة النَّصوح، وأن يهدينا صراطه المستقيم، وأن يُعيذنا من شرور أنفسنا، ومن سيئات أعمالنا.\nوننصحك بحُسن الظن بالله، عليك بحُسن الظنِّ بالله، وإياك والوساوس وسُوء الظنِّ بالله، ما دمت تبتَ من سيئاتك فاحمد الله، واسأله أن يتقبَّل منك، واحذر العودة إلى الشرِّ والمعاصي، واحذر العودة إلى صُحبة الأشرار، لا تصحب الأشرار، وعليك بصُحبة الأخيار، وأحسن ظنّك بربك، يقول النبيُّ ﷺ: يقول الله : أنا عند ظنّ عبدي بي، وأنا معه إذا دعاني، فمَن أحسن ظنَّه بالله ربح غاية الربح.\nفعليك أن تُحسن ظنك بالله، وأن تدعوه أن يُثبتك على الحقِّ، وأن يهديك صراطه المستقيم، وأن يُحسن لك الختام، واحذر وساوس الشيطان، وسوء الظن بالله ، ويقول عليه الصلاة والسلام: لا يموتنَّ أحدٌ منكم إلا وهو يُحسن ظنّه بالله، فالشيطان حريصٌ على إضلال بني آدم، وإفساد أعمالهم، وإذا تابوا وسوس لهم بأنَّ توبتكم غير مقبولةٍ، وأن معاصيكم الماضية عظيمة، وأنَّكم لا تسلمون من شرِّها، وهذا كله من خداعه، وكله من ظلمه وعدوانه، فعليك بالحذر من وساوس الشيطان، واذكر قوله تعالى: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا عَسَى رَبُّكُمْ أَنْ يُكَفِّرَ عَنْكُمْ سَيِّئَاتِكُمْ وَيُدْخِلَكُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ [التحريم:8]، وعسى من الله واجبة.\nويقول النبيُّ ﷺ: التَّائب من الذنب كمَن لا ذنبَ له، ويقول عليه الصلاة والسلام: التوبة تهدم ما كان قبلها، والإسلام يهدم ما كان قبله، فمَن تاب توبةً صادقةً بالندم على الماضي، والإقلاع منه، والعزم الصادق ألا يعود فيه؛ تاب الله عليه، وعفا عنه ، وإن كانت التوبةُ من حقِّ المخلوق فلا بد من أمرٍ رابعٍ، وهو: ردّ الحقِّ إلى أهله، كالسرقة والغصب ونحو ذلك، لا بد من ردِّ الحقِّ إلى صاحبه، أو استسماحه واستحلاله حتى تتم التوبةُ.\nفالشروط ثلاثة، التوبة لها شروط ثلاثة: النَّدم على الماضي. والإقلاع من المعصية وتركها خوفًا من الله، وتعظيمًا له. والأمر الثالث: العزم الصادق ألا تعود في ذلك. وهناك أمرٌ رابعٌ إذا كانت المعصيةُ تتعلق بالمخلوق: أنه لا بد من استسماحه، أو ردّ حقّه إليه، كالقاتل والسارق والغاصب، لا بد من ردِّ الحقِّ إلى أهله، أو يستسمحهم، وإلا فالتوبة تكون غير تامَّةٍ.","link":"https://binbaz.org.sa/fatwas/21167/ما-حكم-من-تاب-ويخشى-انه-لا-يغفر-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0963أنا تبت ولله الحمد من المعاصي ولكن أحسًّ في قلبي أن الله لم يغفر لي فما تنصحوني؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1116,"question":"إنني شابٌّ اهتديتُ إن شاء الله إلى طريق الصواب، وفي البداية وجدتُ حلاوة الإيمان، وشدَّني إنكار المُنكر، ولكنني الآن تقهقرتُ حتى إني أخاف أن أنتكس، أرجو من فضيلتكم النُّصح لي ولإخواني في مثل هذا الموضوع؟","title":"بِمَ يُنصح من استقام على الخير ثم تأخر؟","answer":"الجواب:\nالواجب على المؤمن والمؤمنة إذا مَنَّ الله عليه بالاستقامة أن يُحافظ عليها، وألا يُشدد على نفسه، وأن يصحب الأخيار، ويبتعد عن الأشرار، فالمؤمن مأمورٌ بالثبات على الحقِّ، والحذر من الغلو والجفاء، فلا يغلُ ويبتدع ويُشدد، ولا يجفُ ويقصر ويرتكب المعاصي، ولكن بين ذلك، لا غلو، ولا جفاء، يتحدث مع إخوانه، ويُجالس إخوانه في الله، ويتعاون معهم على البر والتَّقوى، وينصح لهم، ويقبل النَّصيحة، ولا يبتدع في الدين ما لم يأذن به الله، ولا يرضى بالفاحشة، ولا يميل إليها.\nهكذا المؤمن: يتوسط في أموره، فلا غلو، ولا جفاء، لا عنف وشدَّة، ولا تساهل في أمر الله، ولكن وسط، يرفق بإخوانه، ويُحب لهم الخير، ويُخاطبهم بالتي هي أحسن، ولا يبتدع في دين الله ما لم يأذن به الله، ولا يقصر ويرتكب ما حرَّم الله.","link":"https://binbaz.org.sa/fatwas/21163/بم-ينصح-من-استقام-على-الخير-ثم-تاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0959نصيحة في المحافظة على الاستقامة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1161,"question":"يعيش الشبابُ في مرحلة المُراهقة مرحلةً حرجةً من الصراع مع شهواته، ويرى أنه إن أطلق العنانَ لهذه الشَّهوات أهلكته في الدنيا والآخرة، ما السلاح الذي يعتصم به الشبابُ في مُواجهة هذه الشَّهوات؟","title":"ما العوامل التي تعين الشباب أمام الشهوات؟","answer":"الجواب:\nلا شكَّ أن التيار عظيم وخطير مع الشباب وغير الشباب، حتى الشيوخ على خطرٍ، حتى الكبار على خطر، فالأمر عظيم، وأسباب الفتنة كبيرة ومتنوعة: في الأسواق، وفي البيوت، وفي كل مكانٍ، حتى على الشيوخ، حتى على الكبار، فكيف بالشباب؟!\nوطريق النَّجاة هو الحذر من أسباب الفتنة: غضّ البصر، عدم الخلوة بالنساء -بالمرأة الأجنبية-، عدم صحبة الأشرار، الحرص على صحبة الأخيار، هذه من أسباب السلامة؛ كون المؤمن يحرص على صُحبة الأخيار، ويكون معهم، أو يلزم بيته، إلا لخروجه للصلاة وما لا بد منه، فيحذر التَّجول في الأسواق؛ فإنها سبب فتنةٍ، لا يخرج إلا لحاجةٍ، مع غضِّ البصر، ومع الحذر، أو يخرج للصلاة.\nفبيتُه إذا لزمه هو أسلم له، إلا من حاجةٍ، مع غضِّ البصر، ومع تدبُّر القرآن، والإكثار من تلاوة القرآن؛ لأنه يُربي الإيمانَ في القلوب، والخوف من الله، والحذر منه، وهو كتاب الله، فيه الهدى والنور، فيه الهداية لكل خيرٍ: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، شفاء لأمراض القلوب أعظم، وشفاء لبعض أمراض البدن أيضًا، ولكنه شفاء لما في الصدور، شفاؤه للقلوب أعظم وأكبر، كما قال تعالى: يَا أَيُّهَا النَّاسُ قَدْ جَاءَتْكُمْ مَوْعِظَةٌ مِنْ رَبِّكُمْ وَشِفَاءٌ لِمَا فِي الصُّدُورِ وَهُدًى وَرَحْمَةٌ لِلْمُؤْمِنِينَ [يونس:57]، فبالإكثار من تلاوته وتدبُّر معانيه يقوى الإيمان، ويقوى الخوف من الله، والرجاء له، والحذر من معاصيه، ومن أسباب غضبه.\nوصُحبة الأخيار تُعين على ذلك، والحذر من اتباع الهوى، الهوى يهوي بصاحبه إلى الشر، فاحذر هواك ونفسك الأمَّارة بالسُّوء، الله يقول: وَلَا تَتَّبِعِ الْهَوَى فَيُضِلَّكَ عَنْ سَبِيلِ اللَّهِ [ص:26]، ويقول سبحانه: وَمَنْ أَضَلُّ مِمَّنِ اتَّبَعَ هَوَاهُ بِغَيْرِ هُدًى مِنَ اللَّهِ [القصص:50]، ويقول سبحانه: وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَى  ۝  فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَى [النازعات:40- 41]، وقال في الكفار: إِنْ يَتَّبِعُونَ إِلَّا الظَّنَّ وَمَا تَهْوَى الْأَنْفُسُ [النجم:23]، فاحذر مُشابهتهم، فما تميل إليه نفسُك وهواك احذره حتى تعلم أنه صوابٌ، وأنه خيرٌ، وإلا فالهوى يقودك إلى البلاء.\nومن أعظم أسباب النَّجاة: صحبة الأخيار، والحرص عليهم، واتخاذهم أصحابًا، ولزوم البيت عند فقدهم، إلا من حاجةٍ: كالخروج للصلاة، ودرس العلم، والحاجات التي لا بد منها، وإذا بُليتَ بالأسواق فغضّ بصرك، واحذر مُتابعة الهوى، وصُحبة الأشرار، لا في الأسواق، ولا في غيرها.","link":"https://binbaz.org.sa/fatwas/21222/ما-العوامل-التي-تعين-الشباب-امام-الشهوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1018ما هو السلاح الذي يعصم به الشباب أمام الشهوات؟ابن باز.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1176,"question":"أجد في نفسي إذا خلوتُ هوًى وشهوةً، فما تنصحني حفظك الله؟","title":"ما النصيحة لمن يجد في نفسه ميلًا للشهوات؟","answer":"الجواب:\nأنصحك بأن تتذكر المقام بين يدي الله، وأنت مسؤولٌ عن جوارحك كلها: هل صُنتها وحفظتها؟ ومنها عينك وأذنك ولسانك ويدك ورجلك، وأعظمها قلبك، فعليك أن تصونه عن الهوى المحرم.  إذا شغلت قلبك بذكر الله والتَّفكير فيما أوجب الله عليك وبتدبُّر القرآن وفيما يلزمك من طاعة الله ورسوله؛ فهذا شغلٌ شاغلٌ عن الميل إلى ما حرَّم الله.","link":"https://binbaz.org.sa/fatwas/21256/ما-النصيحة-لمن-يجد-في-نفسه-ميلا-للشهوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1138ما نصيحتكم من يجد في نفسه ميل للشهوات؟ ابن باز فتاوى.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1181,"question":"إني أجد وقتًا كبيرًا، ولا أدري ماذا أفعل؟ وأجلس مع إخوةٍ لي في الله ونمزح ونحو ذلك.","title":"كيف يستفيد المسلم من وقته وفراغه؟","answer":"الجواب:\nتذكر أنَّ الوقت من ذهبٍ، بل أعز من الذهب، الوقت أعزّ من الذهب، فاحرص على حفظه، ولا تشغله بالسَّوالف الباطلة، والأحاديث التي لا فائدةَ فيها، لا مع زملائك، ولا مع غيرهم، احفظه، ولا تصرف الوقتَ إلا فيما ينفعك.  فالوقت له شأنٌ عظيمٌ، فاحفظه في قراءة القرآن، والاستكثار من تلاوته، وقراءة الأحاديث، قراءة متونك وتكرارها، المتون التي عندك: كتاب \"التوحيد\" و\"بلوغ المرام\" و\"عمدة الحديث\" الألفية، المتون الفقهية التي عندك، المتون التي عندك احرص عليها، كررها واحفظها، طالع ما أشكل عليك من المسائل، راجع كلام أهل العلم، راجع الأحاديث التي تحتاج إلى حفظها، أو تنسى بعضها حتى تحفظها، راجع الشروح فيما أشكل عليك.  ذاكر مع الزملاء الطيبين الحريصين، واحرص على صحبتهم؛ حتى تكون أوقاتك محفوظةً، أما إذا تساهلت ضاعت الأوقاتُ! ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/21251/كيف-يستفيد-المسلم-من-وقته-وفراغه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1143كيف أستفد من وقتي؟ ابن باز فتاوى.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1321,"question":"إذا إنسان نَوَى نيةً سيئة ثم رجع إلى الله عز وجل وغَيَّر نيته إلى طَيِّبَة؛ في هذه الحال هل تلزم التوبة؟","title":"كيف تكون توبةُ مَن نَوَى سيئة ولم يفعل؟","answer":"الجواب:\nإذا غَيَّر النية قبل أن يعمل؛ ما في شيء، أو إذا غَيَّرها قبل أن يعمل؛ قبل أن يَصَدَّق، قبل أن يجاهد، قبل أن يصلي، وأصلح نيته؛ فعلى نيته الأخيرة الطيِّبة.","link":"https://binbaz.org.sa/fatwas/21412/كيف-تكون-توبة-من-نوى-سيىة-ولم-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تلزم التوبة على من نوى نية سيئة ولم يفعل.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1323,"question":"إذا إنسان هَمَّ بفعلٍ ولم يستطع أن يفعله؛ فهل يُكتب عليه إذا كان قد جَزَم بالإرادة جَزْمًا على فِعْله؟","title":"ما أنواع الهَمُّ بالسيئة؟ وماذا يترتب عليها؟","answer":"الجواب:\nالهَمُّ بالفعل له أحوال ثلاث:\nإذا هَمَّ وعمل فله ما عمل، هم بالحسنة وعملها؛ له أجرها إلى سبعمائة ضعف إلى أضعاف كثيرة.\nالثاني: هَمَّ ولكن تساهل وترك تهاونًا وكسلاً، وهَمَّ بالسيئة؛ فهذا ليس عليه شيء.\nالثالث: هَمَّ بالسيئة وتركها من أجل الله؛ فهذا له أجر، له حسنة؛ لأنه تركها من أجل الله، تركها مثل ما جاء في الحديث: تركها من جَرَّائي فإذا هم بها ثم تركها من أجل الله؛ صار له أجر، فإنْ عملها صار عليه وزرها.\nوهكذا الحسنة: إنْ هَمَّ بها فله حسنة، وإن لم يفعلها، فإذا فعلها صارت له عشر حسنات إلى سبعمائة ضعف إلى أضعاف كثيرة.","link":"https://binbaz.org.sa/fatwas/21414/ما-انواع-الهم-بالسيىة-وماذا-يترتب-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أنواع الهم بالسيئة وما يترتب على كل نوع.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1324,"question":"بالنسبة الآن في الوقت الحاضر أغلب البلدان  المنتمية للإسلام تكون هناك باسم الجهاد ناس يتقاتلون فيما بينهم، وفي الغالب القاتل والمقتول عقيدتهم غير سليمة، ماذا يكون في مثل هذا؟","title":"حكم قتلى الحرب بين بلاد تنتمي للإسلام","answer":"الجواب:\nعلى حسب أحوالهم هذا إلى الله جل وعلا، الكافر على حاله، والعاصي على حاله، وأمرهم إلى الله، الله يعلم أحوالهم.","link":"https://binbaz.org.sa/fatwas/21415/حكم-قتلى-الحرب-بين-بلاد-تنتمي-للاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم القاتل والمقتول باسم الجهاد.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1333,"question":"إذا تاب عن معصية ولم يتب عن معصية أخرى هل تُقبل توبته؟","title":"حكم التوبة من بعض الذنوب دون بعض","answer":"الجواب:\nتقبل، مُبَعّض، الذنوب.....، لو تاب من الزنا ولم يتب من الخمر قُبلت توبته إذا كانت توبته استوفت الشروط، وهكذا إذا تاب من العقوق للوالدين تُقبل توبته وإن كان عنده ذنوب أخرى.  لكن الواجب عليه أن يتوب منها كلها، الواجب عليه أن يتوب من جميع الذنوب، قال الله جل وعلا: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ.. [النور:31].","link":"https://binbaz.org.sa/fatwas/21424/حكم-التوبة-من-بعض-الذنوب-دون-بعض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من تاب من ذنب ولم يتب من آخر.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1336,"question":"بالنسبة الذي يربط التوبة أنه إذا تزوج، أو إذا حج، أو إذا كَبُر َبالسن؛ يعني يقول أنا في سن الشباب؟","title":"حكم تعليق التوبة بحدث مُعَيَّن","answer":"الجواب:\nلا ما يجوز هذا، من قال له؟! سوف يهجم عليه الأجل، الأجل مُغَطَّى، قد يهجم عليه الأجل وهو في أول الشباب، الواجب البِدَار بالتوبة، وعدم التعليق.","link":"https://binbaz.org.sa/fatwas/21427/حكم-تعليق-التوبة-بحدث-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعليق التوبة بحدث معين.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1355,"question":"الملائكة الحَفَظَة هل يطلعون على النيَّات، أم يكتبون الأعمال والأفعال فقط؟","title":"هل تَطَّلِع الملائكة على أعمال القلوب؟","answer":"الجواب:\nيكتبون أعمال القلوب وأعمال الجوارح كلها، الله يطلعهم على أعمال القلوب من خوف ورجاء ومحبة، كل شيء.","link":"https://binbaz.org.sa/fatwas/21448/هل-تطلع-الملاىكة-على-اعمال-القلوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تطلع الملائكة على أعمال القلوب.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1367,"question":"في بعض الناس إذا التزم انتكس، ثم إذا انتكس يصعب أنه يرجع إلى الله ، يعني ييأسون منه يقولون أنه يطلع أشد من أول، أول قبل ما يهتدي؟","title":"حكم اليأس مِن عودة من ارتدَّ عن الإسلام","answer":"الجواب:\nلا، يُنصح حتى يتوب ويرجع؛ فكثير من الناس ارتد ورجع  وحَسُن إسلامه، مثل عبدالله بن سعد بن أبي سرح وغيره. الإنسان إذا وُجد منه شيء يُنصح حتى يرجع إلى الصواب، لا ييأسوا ولا ينبغي وَلا تَيْئَسُوا مِنْ رَوْحِ اللَّهِ [يوسف:87].  بعد موت النبي ﷺ ارتد كثير من الناس ثم هداهم الله وأسلموا ورجعوا إلى الحق.","link":"https://binbaz.org.sa/fatwas/21460/حكم-الياس-من-عودة-من-ارتد-عن-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من يرتد ويرجع هل يثاب على أعماله قبل أن يرتد.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1380,"question":"ذكر قصص سُوء الخاتمة للعبرة؟","title":"حكم ذِكْر قصص سُوء الخاتمة للعبرة","answer":"الجواب:\nعلى كل حال الواجب الحذر من سُوء الخاتمة، نسأل الله العافية والمعاصي والتساهل من أسباب سُوء الخاتمة، والحسنات والاستكثار من الخير من أسباب حُسن الخاتمة، والغفلة واتباع الهوى من أسباب سوء الخاتمة، نعوذ بالله، والاستقامة على طاعة الله ورسوله  ﷺ والمسارعة إلى الخيرات من أسباب حسن الخاتمة.","link":"https://binbaz.org.sa/fatwas/21473/حكم-ذكر-قصص-سوء-الخاتمة-للعبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ذكر قصص سوء الخاتمة للعبرة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1388,"question":"هل تشترط الموالاة في الغسل أم يجوز تفريقه؟","title":"هل تُشترط الموالاة في الغُسْل؟","answer":"الجواب:\nالسنة الموالاة كما كان النبي ﷺ يوالي، لكن لو أخل بشيء وغسله بعد ذلك لا بأس، لو أخل بشيء من جسمه من رأسه أو من صدره أو كذا وغسله فالحمد لله.\nس: لو فرق تفريقًا طويلاً يعني غسل بعض أجزائه؟\nج: السنة الموالاة، المشروع الموالاة، لا يتعمد الترك، لكن لو وجد شيء أخل به ثم تَنَبَّه غسله، مثلًا نسي المضمضة، نسي الاستنشاق، ثم تنبه؛ يتمضمض ويستنشق بنية الغسل، والحمد لله.","link":"https://binbaz.org.sa/fatwas/21481/هل-تشترط-الموالاة-في-الغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الموالاة في الغسل.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":1393,"question":"الكثير من العلماء المعروفين خاصة علماء السلف والزهاد كانوا لا يأكلون إلا الخبز مع الماء؟","title":"ما الهَدْيُ النبوي الصحيح في الزهد؟","answer":"الجواب:\nكل عالم يخطئ ويصيب، من خالف السنة ولو أنه من الصحابة ما يُقتدى به، السنة هي القدوة لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] ومن تبعه بإحسان كذلك.\nس: ماذا لو قالوا: أَذْهَبْتُمْ طَيِّبَاتِكُمْ [الأحقاف:20]؟\nج: هذا في الإسراف والزيادات والاشتغال بملاذ الدنيا عن طاعة الله، لا هذا ولا هذا، لا إسراف وركون إلى الدعة والنعمة، ولا تكلف وغلو، ولكن بين ذلك.","link":"https://binbaz.org.sa/fatwas/21486/ما-الهدي-النبوي-الصحيح-في-الزهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الزهد.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1399,"question":"كيف يجمع بين الأمر بمجاهدة النفس والأمر بالاقتصاد بالعبادة والطاعة؟","title":"كيف يكون جهاد النفس مع القصد في العبادة؟","answer":"الجواب:\nلا منافاة، يجاهدها في أداء فرائض الله، ويجاهدها في ترك محارم الله، ويجاهدها فيما تيسر من العبادة، ولا يشقّ عليها.","link":"https://binbaz.org.sa/fatwas/21492/كيف-يكون-جهاد-النفس-مع-القصد-في-العبادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين الأمر بمجاهدة النفس والأمر بالاقتصاد بالعبادة والطاعة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1436,"question":"مَن سَنَّ سنةً سيئةً وتَبِعَه ناسٌ، ثم تاب وأتباعه لا زالوا يتبعونه، فهل عليه وزر؟","title":"حكم مَن سَنَّ سنة سيئة وتَبِعَه أناسٌ ثم تاب","answer":"الجواب:\nالظاهر أنه إذا تاب توبةً صادقةً ما عليه شيء، إلا إذا كانوا هم قريبين ويستطيع أن يُبلِّغهم؛ فعليه أن يُبَلِّغهم حتى لا يقتدوا به. أما إذا ما استطاع أن يُبَلِّغهم فنرجو أن توبته تكفيه، والشرك أعظم من ذلك. لكن إذا كان يمكنه الحصول على عناوينهم، أو كانوا قريبين منه فعليه أن يُبَلِّغهم: \"أني أخطأتُ في هذا الشيء وقد رجعتُ عن خطئي\"؛ حتى لا يتأسّوا به.","link":"https://binbaz.org.sa/fatwas/21531/حكم-من-سن-سنة-سيىة-وتبعه-اناس-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من سن سنة سيئة وتعبه أناس ثم تاب هل عليه وزر.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1462,"question":"لو أنَّ الشخص سرق وتاب فهل تكفي التوبة؟","title":"ما حكم التوبة لمن عليه حقوق للناس؟","answer":"الجواب:\nالتوبة تجُبُّ ما قبلها، لكن يرضي أصحاب الحقوق، فإذا تاب توبة صادقة يرضي الله  أصحاب الحقوق، ولا تضيع حقوقهم، فحقوقهم تبقى ويُرضيهم الله عنها إذا صحَّت التوبة.","link":"https://binbaz.org.sa/fatwas/21559/ما-حكم-التوبة-لمن-عليه-حقوق-للناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أذنب ثم تاب فهل تكفي التوبة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1509,"question":"الفقر هل يدخل في أنواع الابتلاء من الله؟","title":"هل يدخل الفقر في أنواع الابتلاء من الله؟","answer":"الجواب:\nكلها ابتلاء، الغنى والفقر، هذا يُبتلى بالسراء، وهذا يُبتلى بالضراء، هذا يُبتلى بالصحة، وهذا يُبتلى بالمرض، هذا يبتلى بالغنى، وهذا يبتلى بالفقر، هذا يبتلى بالوظيفة، وهذا يبتلى بحرمانها، كلها ابتلاء وامتحان.","link":"https://binbaz.org.sa/fatwas/21608/هل-يدخل-الفقر-في-انواع-الابتلاء-من-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعدد ابتلاء الله للعباد.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1512,"question":"رجل ترك الصلاة عشر سنين، وترك الصوم والزكاة، وسرق، وتَسَلَّف ولم يرجع الأموال، وتاب؟","title":"حكم مَنْ ترك الفرائض وسرق ثم تاب","answer":"الجواب:\nإذا تاب يمحو الله ما سلف، إذا أسلم محا الله عنه ما مضى، يقول الله جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنْتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]، ويقول النبيُّ ﷺ للمسلم: أسلمتَ على ما أسلفتَ من خيرٍ. والمال الذي سرقه يرده إلى أصحابه، والحمد لله، وإذا عجز فالله يرده عنه يوم القيامة، لكن إذا استطاع يرد المال على أهله.  ولا يقضي الصوم ولا الصلاة ما دام تاب وأسلم، الحمد لله.","link":"https://binbaz.org.sa/fatwas/21611/حكم-من-ترك-الفراىض-وسرق-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ترك الصلاة والصوم والزكاة وسرق ثم تاب فما الحكم.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1539,"question":"رجل عند بوله يخرج قبل بوله بقليلٍ مَنِيّ؛ لشدة قوة مَنِيِّه وكثرته، كما قال الأطباء، فهل يغتسل لكل...؟","title":"حكم خروج المَنِيّ بغير شهوة","answer":"الجواب:\nلا، هذا إذا كان عنده شهوة، وأما العادي هذا الذي مع البول أو بعد البول ما يضر، هذا مرض.\nس: لونه لون المَنِيّ؟\nج: لا بدّ عن شهوة: إذا فَضَخْتَ مَنِيَّكَ فاغتسل، لا بدّ أن يكون عن شهوةٍ: إما مجامعة، وإلا ملامسة، وإلا تقبيل، وإلا تفكير.\nس: يترك الاغتسال الآن؟\nج: لا، ما عليه اغتسال، ما عليه إلا الاستنجاء.","link":"https://binbaz.org.sa/fatwas/21639/حكم-خروج-المني-بغير-شهوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم خروج المني عند الوضوء.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":1636,"question":"هل يُشترط الترتيب في التيمم؟","title":"هل يُشترط الترتيب في التيمم؟","answer":"الجواب:\nمثل الوضوء: الوجه والكفين: فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ [النساء:43]، ابدؤوا بما بدأ الله به.\nس: طريقة المسح؟\nج: يمسح وجهه بكفيه.\nس: مسح اليدين هل يكون بالأكُفِّ.....؟\nج: يمسح وجهه بباطن كفيه.","link":"https://binbaz.org.sa/fatwas/21741/هل-يشترط-الترتيب-في-التيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الترتيب في التيمم.mp3","categories":["التيمم"]},{"id":1687,"question":"إذا كان الرجلُ عنده معاصٍ ولا يصلي، وقبل وفاته بقليلٍ أعلن الشَّهادة: \"لا إله إلا الله، وأنَّ محمدًا رسول الله\"، هل يُحكم عليه بمثل الحكم هنا؟","title":"هل تكفِّر شهادةُ التوحيد الشرك والمعاصي؟","answer":"الجواب:\nالمعاصي لا يُكفِّرها قول: \"لا إله إلا الله\"، لا بدّ من التوبة، \"لا إله إلا الله\" تُكَفِّر الشركَ إذا صدق فيها، أما إذا أتى بالمعاصي فلا بدّ من توبته من المعاصي خاصَّةً، وإذا أتى ما يُوجب الحدَّ يُقام عليه الحدُّ، ولو قال:\"لا إله إلا الله\"، فالنبي ﷺ أقام الحدودَ على المسلمين وهم يقولون: \"لا إله إلا الله\".","link":"https://binbaz.org.sa/fatwas/21793/هل-تكفر-شهادة-التوحيد-الشرك-والمعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المعاصي والشرك هل تكفرها قول لا إله إلا الله أم لا بد من التوبة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1696,"question":"بالنسبة لمَن يُلْجِمه العرقُ يوم القيامة: يكون ذلك لعامَّة الناس أم لمَن كانت له معصية؟","title":"مَن الذين يُلْجِمُهم العَرَقُ يوم القيامة؟","answer":"الجواب:\nظاهر الحديث العموم، لكن المراد الكفرة وأهل المعاصي، أما المؤمنون فلهم النَّجاة والسعادة في موقف القيامة، وفي القبر، وفي الجنة، لكن الإنسان يحذر أن يُصيبه ما أصاب الناس بسبب موته على بعض المعاصي –نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21802/من-الذين-يلجمهم-العرق-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من يلجمه العرق يوم القيامة الناس عامة أم لمن كان له معاصي.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":1796,"question":"هل هذه الدَّرجات متساوية من ناحية الثواب، التي هي: القرآن والقراءة والقتال والصَّدقات؟","title":"هل تتفاوت درجات الثواب للأعمال الصالحة؟","answer":"الجواب:\nلا، الثواب يختلف على حسب نية العبد وإخلاصه وصدقه واستكماله العمل، يختلف، هذا يُصلي وهذا يُصلي، وبين صلاتيهما أعظم مما بين المشرق والمغرب، هذا صلاته قد أقبل عليها، واعتنى بها، وخشع فيها لله، وكمَّلها، وهذا عنده نقصٌ فيها، فبينهما فرقٌ، وهكذا صيامهم، وهكذا حجهم، يختلفون.","link":"https://binbaz.org.sa/fatwas/21903/هل-تتفاوت-درجات-الثواب-للاعمال-الصالحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تتساوى درجات الأعمال من ناحية الثواب.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2052,"question":"الزهد أخصُّ من الورع؟","title":"هل الزهد أخَصُّ من الوَرَع؟","answer":"الجواب:\nالورع غيره، فالزهد معناه: عدم الاستكثار، فكونه يزهد فيها يعني: لا تشغله عن الآخرة، والورع: ترك المشتبهات.","link":"https://binbaz.org.sa/fatwas/22170/هل-الزهد-اخص-من-الورع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الزهد أخص من الورع.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2055,"question":"ما الفرق بين زهده ﷺ وورعه في الدنيا؟","title":"الفرق بين زهده عليه الصلاة والسلام وورعه في الدنيا","answer":"الزهد في الشيء الذي لا حاجةَ إليه، ولا أهميةَ له. والورع: ترك المشتبهات.","link":"https://binbaz.org.sa/fatwas/22173/الفرق-بين-زهده-عليه-الصلاة-والسلام-وورعه-في-الدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين زهده عليه الصلاة والسلام وورعه في الدنيا.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2062,"question":"أيّهما أفضل: طلب التَّقلُّل من الدنيا أم التَّزود من الأموال؟","title":"هل طلب التزود من المال أفضل أم التقلّل؟","answer":"الجواب:\nإذا كان يريد العملَ بطاعة الله ونفع المسلمين فعليه أن يعمل بالأسباب، إذا لم تشغله عن الآخرة، فيعمل وينفع الناس، مثلما فعل الصَّحابةُ: أبو بكر الصديق، وعمر، وعبدالرحمن بن عوف، وغيرهم، فقد أنفقوا في سبيل الله، وأحسنوا، ولم تشغلهم الدنيا عن الآخرة.","link":"https://binbaz.org.sa/fatwas/22180/هل-طلب-التزود-من-المال-افضل-ام-التقلل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل التقلل من الدنيا أفضل أم التزود من الأموال.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2065,"question":"الأصل في الزهد في اللغة؟","title":"ما معنى الزهد وحقيقته؟","answer":"الجواب:\nالزهد في الشيء: عدم التَّعلق به، وعدم المبالاة به.\nعرفتم معنى الزهد، وأنَّ معناه: عدم التَّعلق بالدنيا، وعدم إيثارها على الآخرة، وليس معناه: تركها وعدم التَّسبُّب، لاـ يتسبب ويعمل ويستغني عن الناس، كما قال ﷺ: احرص على ما ينفعك، واستعن بالله رواه مسلم في \"الصحيح\"، ولما سُئل: أيُّ الكسب أطيب؟ قال: عمل الرجل بيده، وكل بيعٍ مبرور، وقال في حديث الزبير: لأن يأخذ أحدُكم حَبْلَه فيأتي بحزمةٍ من حطبٍ على ظهره، فيبيعها، فيكفّ بها وجهه؛ خيرٌ له من سؤال الناس، أعطوه أو منعوه.\nفعليه أن يطلب الرزق ويعمل لأولاده وأبويه، فيتعاون معهم بالحكمة والكلام الطيب، ويتعاون بالأسباب الشَّرعية: من البيع والشِّراء، والزراعة، والنِّجارة، والحدادة، وما يقدر عليه، فيعمل حتى يساعدهم، ولكن تكون الآخرةُ أكبر همِّه، فيُؤدِّي فرائضَ الله، ويترك محارمَ الله، ويحرص على عمل الآخرة، لا تشغله الدنيا عن الآخرة، فقد شغلت أكثرَ الخلق عن الآخرة.","link":"https://binbaz.org.sa/fatwas/22183/ما-معنى-الزهد-وحقيقته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الزهد وحقيقته.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2072,"question":"لو كان العبدُ يستطيع أن يشتري من المتاع لبيته شيئًا ما وتقلَّل من ذلك كما روي عن بعض الصحابة أنه فعل ذلك، يعني: يكون المتاع الصالح ينتظره في الآخرة؟","title":"حكم الزيادة والتقلُّل من متاع الدنيا","answer":"الجواب:\nالمهم أن يبتعد الإنسان عمَّا يشغله عن الآخرة، أمَّا إذا كان لا يشغله، بل ينفع به الناس؛ من بيع، أو شراء، أو عقار، أو غير ذلك؛ فهو ينفع الناس، ولما سُئل ﷺ: أي الكسب أطيب؟ قال: عمل الرجل بيده، وكل بيع مبرور، وقال ﷺ: احرص على ما ينفعك، واستعن بالله، فإذا كان عمله ينفع -سواء بيع، أو شراء، أو مُزارعة، أو بيع دوابّ، أو بيع متاع آخر، أو غير ذلك- فيفعله ما دامت فيه مصلحةٌ ومنفعةٌ للمسلمين، يرجو به ثوابَ الله، فهو على خيرٍ عظيمٍ، والمؤمن على خيرٍ في أعماله كلها إذا نوى بها وجهَ الله والدار الآخرة.","link":"https://binbaz.org.sa/fatwas/22190/حكم-الزيادة-والتقلل-من-متاع-الدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل التقلل من المتاع في الدنيا ليكون المتاع الصالح ينتظر العبد الصالح في الآخرة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2080,"question":"لو ماتت امرأةٌ وليس لها زوجٌ، وكانت من أهل الجنة، هل ستتزوج من المؤمنين؟","title":"هل مَن ماتت دون زوج تُزَوَّج في الجنة؟","answer":"الجواب:\nهذا إلى الله، فكلٌّ يقع مطلوبه في الجنة، لهم فيها ما يدَّعون، النساء والرجال، أي: لهم ما يطلبون، فالرجل يُعْطَى ما يطلب، والمرأة تُعْطَى ما تطلب، كلهم في نعيم.","link":"https://binbaz.org.sa/fatwas/22198/هل-من-ماتت-دون-زوج-تزوج-في-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماتت وليس لها زوج هل ستتزوج من المؤمنين في الجنة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2084,"question":"هل يُؤخذ في وقتنا هذا أنَّ النوم على الحصير من السُّنة؟","title":"هل النوم على الحصير من السُّنة؟","answer":"الجواب:\nلا، ما هو من السنة، إنما يكون حسب الحاجة.\nس: ومَن كان مُقتدرًا لكنَّه يجعل له أيامًا ينام فيها على الحصير؟\nج: إذا أراد أن يتَّعِظَ ويُحاسِب نفسه ويُجاهدها لا بأس، من باب محاسبة النفس وتذكيرها بحال الفقراء، وإلا فلو رزقه الله الطيبات فالحمد لله، فالله قال: كُلُوا مِنَ الطَّيِّبَاتِ [المؤمنون:51].","link":"https://binbaz.org.sa/fatwas/22202/هل-النوم-على-الحصير-من-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النوم على الحصير.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2093,"question":"ترجم المؤلفُ بـ\"فضل الجوع\" للباب، هل للجوع فضلٌ في ذاته؟","title":"هل للجوع فضل؟ وما صلته بالزهد؟","answer":"الجواب:\nنعم، الزهد في الزيادة التي تشغله عن الآخرة، والزهد في الحرام والمكروهات، والزهد فيما يصدّ عن الآخرة، مثلما قال ﷺ: ازهد في الدنيا يُحِبُّك الله، وازهد فيما عند الناس يُحبُّك الناس.\nس: والحديث الذي ورد فيه تعوّذ النبي ﷺ من الجوع، قال: اللهم إني أعوذ بك من الجوع؟\nج: هذا ما يُنافيه، فالزهد لا يستدعي الجوع.","link":"https://binbaz.org.sa/fatwas/22211/هل-للجوع-فضل-وما-صلته-بالزهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للجوع فضل في ذاته.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2146,"question":"إذا كان العبدُ قد اغتسل في هذا اليوم اغتسالًا لأجل التَّطهر لا لأجل الجمعة، ثم صلَّى الجمعة، فهل الصّواب أن الطهارة تعمّ الأمرين؟","title":"حكم مَن اغتسل للتطهر فقط يوم الجمعة","answer":"الجواب:\nلا، بسالغُسل، إذا كان ما توضأ ما يصح، فلا بد أن يتوضأ الوضوء الشرعي، أما الجنابة –عند جمعٍ من أهل العلم- إذا نواهما جميعًا انتقل إلى الصنف الأكبر، إذا كان جنابةً.\nس: يعني: يُعيد الصلاةَ التي صلَّاها بهذا الغُسل؟\nج: نعم، يُعيدها ظهرًا.","link":"https://binbaz.org.sa/fatwas/22265/حكم-من-اغتسل-للتطهر-فقط-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الاغتسال لرفع الحدث يعم اغتسال الجمعة.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":2180,"question":"التَّسَتُّر حال الاغتسال عريانًا يكون أفضل أو ..؟","title":"هل يُشرع التَّسَتُّر حال الاغتسال؟","answer":"الجواب:\nالاغتسال عُريانًا لا بأس به، فالنبي ﷺ كان يغتسل عريانًا، واغتسل موسى عريانًا، واغتسل أيوب عريانًا.\nس: ومَن قال أن الاغتسال عريانًا جائز، ولكن التَّستر أفضل؟\nج: لا، لا بأس بالاغتسال عريانًا، أما التَّسَتُّر فقد يشقّ عليه؛ لأنَّ التَّسَتُّر  قد يطبع ثيابه أو يملؤها بالماء.\nس: لكن لا بأس؟\nج: الأمر واسع إذا كان في حجرةٍ ولا يراه أحدٌ.","link":"https://binbaz.org.sa/fatwas/22301/هل-يشرع-التستر-حال-الاغتسال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الاغتسال عريانا.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":2230,"question":"ما أكبر سببٍ في الحثِّ على الإخلاص لله؟","title":"ما أكبر سبب في الحث على الإخلاص؟","answer":"الجواب:\nالعمل لا يُقبل إلا إذا كان خالصًا لله، أما إذا كان لغيره فلا يُقبل.\nس: قال: ما السّبب؟\nج: لأنَّ العبد يتقرب به إلى الله، فالعبادات قربة إلى الله، ما تنفع ولا تُقبل ولا تصحّ إلا إذا كانت لله، فلا يُقبل منه إذا صلَّى لغير الله، أو صام لغير الله، أو ما صام ولا صلَّى ولا أدَّى العبادة: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ [البينة:5]، وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، فلا بد أن ينوي بقلبه أنَّ هذه الصلاة لله، أو هذا الصوم لله، أو هذه الصدقة لله، أو التَّسبيح، أو ما أشبه ذلك، يرجو ثواب الله.\nس: والتقوى؟\nج: طاعة الله، وترك معصيته، فالمتَّقي هو الذي أطاع الله وترك المعاصي.","link":"https://binbaz.org.sa/fatwas/22353/ما-اكبر-سبب-في-الحث-على-الاخلاص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أكبر سبب في الحث على الإخلاص.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2604,"question":"الجنة فيها تكليف..... التسبيح والتكبير من باب التكليف؟","title":"هل في الجنة تكليف مثل التسبيح والتكبير؟","answer":"الجواب: نعيم، يسبّحون الله، نعيم يتنعّمون به، لكل واحد زوجتان من الحور العين غير زوجاته من الدنيا، كل واحد من أهل الجنة له زوجتان من الحور العين غير ما يُعطى من الزوجات والحور العين الأخرى، يعني لا ينقص واحد عن زوجتين مع زوجات الدنيا مع ما يعطيهم الله من الزوجات الأخرى.\nس: هل يقال أن في الجنة تكليف؟\nالشيخ: ما في تكليف، هي دار نعيم، التسبيح نعيم يتلذّذون به.","link":"https://binbaz.org.sa/fatwas/22738/هل-في-الجنة-تكليف-مثل-التسبيح-والتكبير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل في الجنة تكليف.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2605,"question":"إذا رأى بعض الناس رجلًا صالحًا وقال: إن شاء الله أنك من أهل الجنة، هل فيها شيء؟","title":"هل يجوز الحكم للرجل الصالح بالجنة؟","answer":"الجواب: أحسن أن يقول: أرجو أن تكون من أهل الجنة، وإلا ما فيها شيء إن شاء الله، لكن: أرجو أن تكون من أهل الجنة؛ كلام طيب.","link":"https://binbaz.org.sa/fatwas/22740/هل-يجوز-الحكم-للرجل-الصالح-بالجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم للرجل الصالح بالجنة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2609,"question":"بالنسبة لللرجل يكون له زوجتان من الحور العين.. وبالنسبة مثلًا إذا كانت الزوجة زوجها غير صالح...؟","title":"كيف تكون أحوال الأزواج في الجنة؟","answer":"الجواب: زوجاته في الجنة الله جلا وعلا أعلم، فيها ما تشتهي الأنفس وتلذ الأعين، وأزواجهم مختلفة، أحد عندهم مئات الزوجات، وأحد عنده آلاف الزوجات، وأحد عنده أقل من ذلك، لكن كل واحد لا يَنْقُص من زوجتن من الحور العين غير ما يُعطى من الزيادة.\nس:هل أهل الدرجة الأقل يرون الدرجة العليا؟\nالشيخ: الله أعلم، ما يُعطى مِثْل مَلِك من ملوك الدنيا وخمسة أمثاله، وفي اللفظ الآخر: وعشرة أمثاله، وله ما اشتهت نفسه ولذّت عينه.\nس: الزوجة في الدنيا إنْ كانت صالحة وزوجها صالح هل يُجمع بينهما في الجنة؟\nالشيخ: يُرجى ذلك، في بعض الأحاديث أنها تخيرّ، إذا كان لها أزواج تختار أحسنهم خلقًا، ولكن الأحاديث في هذا فيها بعض النظر، والله أعلم به ، والأقرب والله أعلم أنها لزوجها إن كان ما لها إلا زوج واحد ومات وهي راضية عنه وهو راض عنها؛ فالأقرب والله أعلم أنها تكون له، مثل ما أن أزواج النبي ﷺ في الجنة هم أزواجه في الآخرة، غير ما يعطيه الله من الزيادة، أما إن كان لها أزواج فالله أعلم، جاء في بعض الروايات أنها تخيّر، تختار أحسنهم خلقًا؛ فإن صح فهو واضح، ولكن في سنده بعض المقال.","link":"https://binbaz.org.sa/fatwas/22744/كيف-تكون-احوال-الازواج-في-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأزواج في الجنة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2613,"question":"هل الرؤيا تختص لبعض أهل الجنة أكثر من بعض؟","title":"هل يتفاوت المؤمنون في رؤية ربهم بالجنة؟","answer":"الجواب: كل أهل الجنة يرونه، لكن يتفاوتون فيها، بعضهم أعلى وأكثر.\nس: عدد المرات؟\nالشيخ: أقول بعضهم أكثر، على حسب تقواهم وإيمانهم ومنازلهم في الجنة، منهم من يراه بُكْرة وعَشِيًّا، بمنزلة البُكْرة والعَشِي.","link":"https://binbaz.org.sa/fatwas/22748/هل-يتفاوت-المومنون-في-روية-ربهم-بالجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفاوت المؤمنين في رؤية ربهم عز وجل في الجنة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2614,"question":"بالنسبة ليوم الجمعة؟","title":"ما يوم المزيد في الجنة؟","answer":"الجواب: يسمونه يوم المزيد، هذا يوم يزور ربهم فيه جل وعلا على منابر وعلى مجالس متفاوتة، ومع هذا كل أحد يرى أنه قد أعطي ما لم يعط الآخر، ما أحد يرى فضل ولا نقص ولا حزن، كلهم في نعيم، وكلهم في مجالسهم وفي زيارتهم، لا يرون أن هناك شيئًا من النقص عليهم أو الضيم لهم، كل راض بما هو فيه، مرتاح بالنعيم الذي هو فيه، يرى أنه قد أعطي ما لم يعط غيره. لأنها دار نعيم وليست دار حزن ولا دار مفاخرة ولا دار هضم، بل هي دار نعيم دائم.","link":"https://binbaz.org.sa/fatwas/22749/ما-يوم-المزيد-في-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يوم المزيد في الجنة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2619,"question":"هل لتارك الصلاة توبة؟ وكيف تكون؟","title":"هل لتارك الصلاة توبة؟ وكيف تكون؟","answer":"الجواب: كل عاصٍ له توبة، وكل كافر له توبة، ولا يوجد مَن لا توبةَ له، فعليه أن يتوب إلى الله، ويندم، ويحافظ على الصلوات، يندم على ما مضى، ويعزم ألا يعود، ويستغفر ربَّه، ويسأل ربَّه العفو، ويُصلي، والحمد لله.","link":"https://binbaz.org.sa/fatwas/22754/هل-لتارك-الصلاة-توبة-وكيف-تكون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل لتارك الصلاة توبة، وكيف تكون.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2676,"question":"هل المُحْتَلِم لا تَقْرَبُه الملائكة؟","title":"ما صحة أن المُحْتَلِم لا تَقْرَبُه الملائكة؟","answer":"الجواب: النبي ﷺ لما جاءه أبو هريرة وحذيفة وانْخَنَسا منه قال ﷺ: إن المسلم لا يَنْجُس فالجنابة معنى من المعاني ما هي بنجاسة، معنى من المعاني تُوجِب الغُسل، وهكذا الحيض يوجب الغُسل، والمرأة طاهرة عرقها طاهر وريقها طاهر وما مسته طاهر وشعرها طاهر، وهكذا الجُنُب عرقه طاهر وبدنه طاهر، لكن عليه أن يغتسل كما أمره الله.","link":"https://binbaz.org.sa/fatwas/22814/ما-صحة-ان-المحتلم-لا-تقربه-الملاىكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل المحتلم لا تقربه الملائكة.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":2748,"question":"قول أن نية المؤمن أبْلَغُ من عمله؟","title":"ما صحة القول: نية المؤمن أبْلَغُ من عمله؟","answer":"الجواب: من كلام بعض السلف، مأخوذة من بعض الأحاديث، مستنبطة من حديث الأعمال بالنيات وأن العبد له ما نوى، وأنه إذا نوى العمل الطيب ثم حبسه عذر صار له أجر العاملين، كما في الحديث الصحيح: إذا مرض العبد أو سافر كتب الله له ما كان يعمل وهو صحيح مقيم، وفي الحديث: إن في المدينة أقوامًا ما سلكتم طريقًا ولا قطعتم شِعْبًا إلا وهو معكم حَبَسَهُمُ العُذْرُ يعني مع النية الصالحة.","link":"https://binbaz.org.sa/fatwas/22896/ما-صحة-القول-نية-المومن-ابلغ-من-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نية المؤمن أبلغ من عمله.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2762,"question":"يكون يأخذ أجر النية وإلا أجر العمل كاملًا؟","title":"هل أجر النية الصادقة مثل أجر العمل كاملًا؟","answer":"الجواب: أجرهم على نيتهم، نية الجهاد، يعطون مثل المجاهدين.\nس: هناك بعض العلماء فرق قال: إن كان يعمل هذا العمل قبل العذر أو قبل المرض ونوى؛ فيكتب له كامل الأجر، وإن كان لم يكن يعمله سابقًا ونوى يُكتب له أجر النية؟\nالشيخ: ظاهر الحديث الصحيح أنه يكتب له أجر المجاهدين، قال: شركوكم في الأجر، كانوا معكم حبسهم العذر.\nس: وذكروا مثال الصلاة إن كان يتنفل؟\nالشيخ: له أجرها، إذا تركها من أجل السفر والمرض له أجرها، إذا مرض العبد أو سافر كتب الله ما كان يعمل وهو صحيح مقيم، رواه البخاري في الصحيح؛ من فضل الله ورحمته.\nس: وإذا كان لا يعمل هذا الشيء ولكنه نوى أنه لو كان صحيحًا لذهب للصلاة أو تنفل أو كذا؟\nالشيخ: النبي ﷺ قال: ما كان يعمل، ما كان قد استقر له، أما الجديد فله مستقبله، لكن يُرجى له إذا كان عازمًا على عمل وحبسه العذر يُرجى له الأجر.","link":"https://binbaz.org.sa/fatwas/22910/هل-اجر-النية-الصادقة-مثل-اجر-العمل-كاملا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أجر النية في العمل الصالح.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2826,"question":"إذا كان إنسان على ضلالة ثم تاب: هل عليه وِزْرُ مَن تَبِعه حتى بعد التوبة؟","title":"هل يلحق المُفْسِد بعد توبته وِزْرُ مَن تَبِعه؟","answer":"الجواب: يُرجى له العافية إن شاء الله، إذا تاب يُرجى له إن شاء الله السلامة؛ لأن التوبة تجب ما قبلها، والحمد لله، وعليه يُبَيِّن رجوعَه.\nس: العلمية هل تدخل من ضمنها؟\nالشيخ: إن شاء الله تدخل.\nس: من قال إن عليه الوِزْر حتى بعد التوبة، وِزْرُ مَن تَبِعه؛ لحديث ابن آدم أنه تاب وعليه وزر مَن قتل بعده؟\nالشيخ: ما يظهر لي، الرسول ﷺ قال: التائب من الذنب كمن لا ذنب له، والتوبة تَجُبُّ ما قبلها، وابن آدم ما ندري تاب وإلا ما تاب، عندك خبر أنه تاب؟!","link":"https://binbaz.org.sa/fatwas/22975/هل-يلحق-المفسد-بعد-توبته-وزر-من-تبعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كان على ضلالة ثم تاب فهل عليه وزر من تبعه بعد التوبة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2864,"question":"في حديث عائشة في غسل الجنابة في آخر الحديث: ثم يغسل رجليه بعد أن يتوضأ يؤخر غَسل الرجلين؟","title":"حكم تأخير غَسل الرِّجلين في غُسل الجنابة","answer":"الجواب: هذا أفضل، وضوء كامل أولًا، ثم يغتسل، ثم يغسل رجليه من باب الكمال بعدما ينالها من أوساخ الجسد ونحوه، وإن توضأ وخلى الرجلين حتى يُكمّل الغسل ثم غسلها؛ كلها جاء، في حديث ميمونة وفي حديث عائشة، كله طيب. لكن الأكمل: يتوضأ وضوء كاملًا ثم يغسلهما غسلة أخرى، هذا الأفضل.\nس: بعض العلماء يقول أنه شاذ؛ لأنه لا معنى لغَسل الرجلين؟\nالشيخ: لا، ما هو شاذ، هو ثابت في الصحيحين.","link":"https://binbaz.org.sa/fatwas/23017/حكم-تاخير-غسل-الرجلين-في-غسل-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تأخير غسل الرجلين في غسل الجنابة.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":2892,"question":"متى يُؤجَر الرجل على نيته فيُعْطَى فضلَ ما لم يُدْرِك؟","title":"متى يُؤجَر المرءُ على نيته بما لم يعمل؟","answer":"الجواب: دائمًا يؤجر على نيته الصالحة، ما هو بس متى، دائمًا يُؤجَر على نيته الصالحة.\nس: في بعض الأحاديث أنه يدرك مثل ما يدرك مَنْ له أعمال؟\nالشيخ: الأعمال بالنيات، وإنما لكل امرئ ما نوى، فإذا كان مِن نيته أن يعمل لو قَدِر؛ كُتِب الله له أجر ذلك، يقول ﷺ: إذا مرض العبد أو سافر كتب الله له ما كان يعمل وهو صحيح مقيم، وقال: إن في المدينة أقوامًا ما سرتم مسيرًا ولا قطعتم واديًا إلا وهم معكم حبسهم العذر وهو المرض، إذا كان له نية صالحة لولا العذر.\nس: أليس في الحديث دليل على أن بعض الأعمال لا تدخل في هذا؟\nالشيخ: ظاهر الأحاديث العموم، لكن إذا فعله يكون أفضل، إذا استطاع وفعله يكون أفضل؛ لأن الفقراء يستطيعون أن يعملوا؛ فلا يُعطون الأجر وهم يستطيعون أن يعملوا، لكن العاجز الذي ما يستطيع، مثل أخرس ما يستطيع يتكلم؛ يُعطى أجره ولو ما فعل.","link":"https://binbaz.org.sa/fatwas/23047/متى-يوجر-المرء-على-نيته-بما-لم-يعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يؤجر الرجل على نيته.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":2954,"question":"أرجو من سماحتكم أن تخبرونا عن كيفية الغسل من الجنابة؛ لأن بعض النساء تقوم بغسل مؤخرة الرأس أي الشعر وتقول إنه يجوز ويكفي لغسل الشعر كله، أو تقوم بغسل بعض الشعر بأن يتخلل الماء مؤخرة الشعر أي بعضه، فهل هذا يجوز؟ أما أنها تغسل الشعر كله سواء كان الشعر مربوطًا أم مفكوكًا، أرجو أن تخبرونا عن كيفية الغسل؟","title":"ما كيفية الغُسل من الجنابة للنساء؟","answer":"الجواب: السُّنَّة أن يستنجي الإنسان، يستنجي أولًا بعد الجماع، ثم يتوضأ وضوء الصلاة، ثم يفرغ على رأسه الماء ثلاث مرات، ثم يغسل بقية جسده، يبدأ بالشق الأيمن قبل الأيسر حتى يكمل الغسل.  والمرأة يكفيها إذا أمرّت الماء على رأسها ثلاث مرات يكفي، قالت أم سلمة: يا رسول الله إني امرأة أشد شعر رأسي أفأنقضه لغسل الجنابة؟ وفي رواية الحيضة؟ قال: يكفيك أن تحثي على رأسك ثلاث حثيات ثم تفيضي عليك الماء فإذا أفاضت عليه ثلاث حثيات مر على جميعه فلا يلزم النقض، وهكذا الرجل لو كان له رأس يُفيض عليه الماء ولا يحتاج للنقض.","link":"https://binbaz.org.sa/fatwas/23110/ما-كيفية-الغسل-من-الجنابة-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيفية الغسل من الجنابة للنساء.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":3029,"question":"علامة قسوة القلوب؟","title":"ما علامات قسوة القلوب وأسباب لِينِها؟","answer":"الجواب: المعاصي من أعظم أسباب قسوة القلوب؛ كلما زادت المعاصي سبّبت القسوة للقلوب، وكلما جاءت الطاعات صارت من أسباب لين القلوب. ومن أسباب لِين القلوب: كثرة ذكر الله جل وعلا، الإكثار من ذكر الله من أسباب لِين القلوب، كذلك قراءة القرآن والإكثار من قراءة القرآن الكريم، والكَفّ: كَفُ اللسان عما لا ينبغي، كل هذا من أسباب صلاح القلوب.","link":"https://binbaz.org.sa/fatwas/23189/ما-علامات-قسوة-القلوب-واسباب-لينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/علامة قسوة القلوب.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":3061,"question":"كلام السلف في ذم الدخول على السلاطين على ماذا يُحْمَل؟","title":"على ماذا يُحْمَل ذمُّ الدخول على السلاطين؟","answer":"الجواب: على الذي يمدحهم ويوافقهم على باطلهم، مثل ما قال ﷺ: سيكون بعدي عليكم أمراء ظلمة فمن صدّقهم بكذبهم وأعانهم على ظلمهم فليس مني ولست منه، ومن لم يصدّقهم بكذبهم ولم يُعنهم على ظلمهم فهو مني وأنا منه. فإذا دخل عليهم بالتوجيه والإرشاد وتخفيف الشر؛ هذا هو المطلوب، أما إذا دخل عليهم ليعينهم على الظلم ويصدقهم بالكذب فهذا هو المذموم، نسأل الله العافية.\nكذلك في حديث \"لا يُبلغني أحد عن أحد شيئًا\" فهذا الحديث ضعيف فيه جهالة، وهو لو صح محمول على الشيء الذي ما يضر المسلمين، أما شيء يضر المسلمين فالواجب تبليغ ولي الأمر حتى يحتاط المسلمين، والحديث وإن كان ضعيفًا لما فيه من الجهالة، لكن يلاحظ معناه، المعنى الصحيح؛ فالمسلمون يبلّغون ولي الأمر الشيء الذي فيه مصلحة ولا يبلغونه الشيء الذي يضر ولا ينفع. ولهذا لما سمع زيد بن أرقم عبدالله بن أُبي يتكلم في بعض الأسفار: ليخرجن الأعز منها الأذل؛ بَلّغ النبي ﷺ ولم يُنكر عليه النبي ﷺ، بل أنزل الله تصديقه في القرآن.","link":"https://binbaz.org.sa/fatwas/23221/على-ماذا-يحمل-ذم-الدخول-على-السلاطين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/على ماذا يحمل كلام السلف في ذم الدخول على السلاطين.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":3106,"question":"إذا شخص نائم سمع الأذان ولكن عقله ما كان معه، يعني كاملًا، ما هو الحكم في هذا؟","title":"حكم مَنْ سمع الأذان نائمًا ثم غلبه النوم","answer":"الجواب: ما قام يصلي؟\nس: لا، ولكن عقله ما كان كاملًا.\nالشيخ: عليه التوبة إلى الله والحذر، يحط ساعة وإلا غيرها، وإلا يعلّم أهله يقوّمونه، أو يحط ساعة تساعده حتى يستعين بها على أداء ما فرض الله.","link":"https://binbaz.org.sa/fatwas/23266/حكم-من-سمع-الاذان-ناىما-ثم-غلبه-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحذر من سماع الأذان وعدم القيام للصلاة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":3172,"question":"الشخص إذا جمع بين الوضوء والغسل كما ذكرتم آنفا فإنه لا محالة أنه يمس بعد أن يتوضأ، ربما يمس فرجيه؟","title":"ما كيفية الجمع بين الوضوء والغسل؟","answer":"الجواب: لا يمسهما، يستنجي قبل، ويكفي، يستنجي يغسل فرجيه قبل، ثم الأفضل يتوضأ وضوء الصلاة، فإن كان ما توضأ ونوى الغسل والوضوء جميعًا؛ أجزأ عند جمع من أهل العلم، يدخل الأصغر في الأكبر.","link":"https://binbaz.org.sa/fatwas/23335/ما-كيفية-الجمع-بين-الوضوء-والغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين الوضوء والغسل.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":3177,"question":"شخص صلى صلاة في صحراء بتيمم ثم لما سلم جاءه واحد وأتى بماء: هل يعيد الصلاة؟","title":"حكم مَن صلى بتيمم ثم لما سلّم وجد الماء","answer":"الجواب: ما عنده ماء أول؟ عادم؟\nالطالب: أبدا.\nالشيخ: لا ما يعيد.\nس: وإذا أعاد الصلاة؟\nالشيخ: لا ما عليه إعادة.\nس: هل في حديث أن الشخص إذا أراد الصلاة...؟\nالشيخ: جاء في حديث أن رجلين صليا وليس عندهم ماء ثم وجدا ماءً بعد ذلك فأعاد أحدهما الوضوء والصلاة ولم يُعد الآخر، فقال النبي ﷺ للذي لم يُعد: أصبت السنة، وأجزأتك صلاتك وقال للأخر: لك الأجر مرتين.\nس: وهذا حديث صحيح؟\nالشيخ: نعم، لا بأس به.","link":"https://binbaz.org.sa/fatwas/23340/حكم-من-صلى-بتيمم-ثم-لما-سلم-وجد-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلى صلاة بتيمم ثم لما سلم وجد الماء.mp3","categories":["التيمم"]},{"id":3190,"question":"يشترط عدم ارتكاب الكبائر (لتكفير السيئات)؟","title":"هل اجتناب الكبائر شرطٌ لتكفير السيئات؟","answer":"الجواب: نعم إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31] لابدّ، وفي الحديث الصحيح عن النبي ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان كفارات لما بينهن إذا اجتنبت الكبائر وفق الله الجميع.","link":"https://binbaz.org.sa/fatwas/23353/هل-اجتناب-الكباىر-شرط-لتكفير-السيىات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اجتناب الكبائر شرط لتكفير السيئات.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":3372,"question":"ما ورد الوعيد في تأخير الغُسْل من الجنابة؟","title":"ما حكم تأخير الغُسْل من الجنابة؟","answer":"الجواب: ما أتذكر شيئًا، التأخير إذا كان ما فيه مانع، لو جامع في أول الليل جاز التأخير إلى آخر الليل، النبي ﷺ كان يؤخر عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23539/ما-حكم-تاخير-الغسل-من-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تأخير الغسل من الجنابة.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":3395,"question":"إذا كان في وقت الظهر فظنّ أنه يخرج من السجن في وقت العصر: فهل يجمع إليها الصلاة حتى يكون على طهارة؟","title":"حكم التيمم وجمع الصلاة لمن تعرّض للسجن","answer":"الجواب: لا، يصلي كل صلاة في وقتها، ولو بالتيمم.\nس: ما يستطيع التيمم أحسن الله إليك؟\nالشيخ: ولو ما معه التيمم، الحمد لله يصلي كل صلاة في وقتها، ولو ما معه تيمم ولا ماء فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن: 16].","link":"https://binbaz.org.sa/fatwas/23565/حكم-التيمم-وجمع-الصلاة-لمن-تعرض-للسجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل متفرقة في التيمم للصلاة.mp3","categories":["التيمم"]},{"id":3396,"question":"هل هذا الحديث (حتى أقبل على الجدار، فمسح...) يدل على جواز التيمم من أجزاء الأرض المتولدة كالطين، والرخام، وغيره؟","title":"هل يجوز التيمم بالطين والرخام ونحوهما؟","answer":"الجواب: جنس التراب، سواء في الجدار، أو في الأرض، وإذا دعت الحاجة إلى غيره كالذي في الأرض سبخة، أو في أرض رمل؛ تيمم منها، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]؛ لعموم الحديث، وعموم الآية: فَلَمْ تَجِدُوا [النساء:43].","link":"https://binbaz.org.sa/fatwas/23567/هل-يجوز-التيمم-بالطين-والرخام-ونحوهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث .. حتى أقبل على الجدار، فمسح بوجهه.. هل يدل على جواز التيمم من أجزاء.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":3397,"question":"العيني قال في حديث مسح وجهه وذراعيه أن الإمام البغوي حَسّن هذا الحديث؟","title":"هل صح حديثُ مسحِ الذراعين في التيمم؟","answer":"الجواب: لا، غلط، الصواب: وجهه وكفيه فقط، كما جاء في حديث عمّار وغيره، التيمم يكون بالكفين فقط.","link":"https://binbaz.org.sa/fatwas/23568/هل-صح-حديث مسح-الذراعين-في-التيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصحيح في التيمم المسح على الوجه والكفين.mp3","categories":["التيمم"]},{"id":3398,"question":"غلب على ظنه وجود الماء لكن يخاف من فوات الوقت؟","title":"هل يجوز التيمم لمن خاف فوات الوقت؟","answer":"الجواب: يصلي بالتيمم إذا كان ما عنده ماء: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا [النساء:43] إلا إذا كان قريبًا يذهب إلى الماء، ولا يجوز التيمم ما دام في الوقت.\nس: إذا حضر الماء أثناء الصلاة هل يقطعها؟\nالشيخ: الأقرب أنه يقطع الصلاة، ويتوضأ؛ لعموم قوله: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا [النساء:43] إذا وجد الماء في الصلاة وحضر عنده يقطعها، ويتوضأ ثم يستأنف الصلاة.","link":"https://binbaz.org.sa/fatwas/23569/هل-يجوز-التيمم-لمن-خاف-فوات-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لا يعلم بوجود الماء فهل له أن يتيمم.mp3","categories":["التيمم"]},{"id":3399,"question":"كيفية مسح الكفين؟","title":"ما كيفية مسح الكفين في التيمم؟","answer":"الجواب: هكذا يمسح ظاهرهما وباطنهما، هذه بهذه.\nس: ما يذكر بعض الفقهاء مِن الضرب على الفُرُش إذا كان لها غبار؟\nالشيخ: إذا كان فيها غبار حقيقة فلا بأس، لكن كونه يقصد التراب إذا كان موجودًا قريبًا أوْلى وأحوط.\nس: مسح الكفين ألا يكون على ظاهر الكف فقط؟\nالشيخ: ظاهره وباطنه؛ لأن اليد تشمل الظاهر والباطن: فَامْسَحُوا بِوُجُوهِكُمْ وأَيْدِيكُمْ [النساء:43].\nس: ونفخ فيهما؟\nالشيخ: إذا كان فيها تراب كثير ينفخ فيهما حتى يخفّف.","link":"https://binbaz.org.sa/fatwas/23570/ما-كيفية-مسح-الكفين-في-التيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيفية مسح الكفين في التيمم.mp3","categories":["التيمم"]},{"id":3401,"question":"من خشي فَوْت الجنازة يتيمم لئلا تفوت، صحيح؟","title":"هل يتيمم من يخشي فَوْت صلاة الجنازة؟","answer":"الجواب: لا، ما له أصل: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا [النساء:43].","link":"https://binbaz.org.sa/fatwas/23573/هل-يتيمم-من-يخشي-فوت-صلاة-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/خشي فوت الجنازة فهل يتيمم لئلا تفوت.mp3","categories":["التيمم"]},{"id":3402,"question":"إذا لم يجد الماء فهل له أنْ يطأ زوجته؟","title":"هل يُجامع أهله مَنْ لا يجد الماء ويكفيه التيمم؟","answer":"الجواب: في البر يعني؟\nالطالب: يعني الماء لم يكن موجودًا، فهل له أن يجامع زوجته.\nالشيخ: يعني في البر ما عنده ماء؟\nالطالب: في البر، في أي مكان.\nالشيخ: يجامع زوجته، ويتيمم، ما عنده ماء الحمد لله، مثل البادية في البر ما عندهم ماء.\nس: وهل يجزئ التيمم عن الغسل.....؟\nالشيخ: يكفي التيمم.","link":"https://binbaz.org.sa/fatwas/23574/هل-يجامع-اهله-من-لا-يجد-الماء-ويكفيه-التيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجزئ التيمم عن الغسل لرفع الحدث الأكبر.mp3","categories":["التيمم"]},{"id":3403,"question":"(التيمم) هل يكفيه ضربة واحدة فقط؟","title":"هل السُّنَّة في التيمم ضربة واحدة للتراب؟","answer":"الجواب: نعم، هذا السُّنَّة.","link":"https://binbaz.org.sa/fatwas/23575/هل-السنة-في-التيمم-ضربة-واحدة-للتراب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صفة التيمم ومتى يجوز.mp3","categories":["التيمم"]},{"id":3404,"question":"تقديم الوجه في التيمم: وجوبًا أو استحبابًا؟","title":"هل تقديم الوجه في التيمم واجب أم مستحب؟","answer":"الجواب: وجوبا فَامْسَحُوا بِوُجُوهِكُمْ وأَيْدِيكُمْ [النساء: 43] ابدؤوا بما بدأ الله به كما قال النبي ﷺ، وكان النبي يبدأ بوجهه عليه الصلاة والسلام.\nس: مَنْ فَرّق بين التيمم من الحدث الأصغر فيجب تقديم الوجه، ومن تيمّم عن الحدث الأكبر فيجوز له؟\nالشيخ: لا، الوجه يُقَدّم في الجميع، كما يفعل في الماء.","link":"https://binbaz.org.sa/fatwas/23576/هل-تقديم-الوجه-في-التيمم-واجب-ام-مستحب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تقديم الوجه في التيمم.mp3","categories":["التيمم"]},{"id":3759,"question":"أمة محمد ﷺ فتنتها في المال؟","title":"هل فتنة أمة محمد ﷺ في المال؟","answer":"الجواب: في المال نعم، يقول النبي ﷺ: اتقوا الدنيا، واتقوا النساء؛ فإن أول فتنة بني إسرائيل كانت في النساء اللهم صل عليه وسلم، وهذه الأمة فتنتها في المال وفي النساء أيضًا، على خطر الذي يقع لهم في النساء شر كثير، نسأل الله العافية، ولهذا في الحديث الصحيح: ما تركت بعدي فتنة أضر على الرجال من النساء في الصحيحين.\nولهذا قال في حديث أبي سعيد: فاتقوا الدنيا واتقوا النساء.","link":"https://binbaz.org.sa/fatwas/23951/هل-فتنة-امة-محمد-ﷺ-في-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فتنة أمة محمد في المال.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":3767,"question":"يكون موتهم (الأطفال) من الأسباب المكفّرة للذنوب؟","title":"هل موت الأطفال من أسباب دخول الجنة؟","answer":"الجواب: هذه كلها معلّقة، منها من أسباب دخولهم الجنة، تحريمهم على النار، من باب توفيقهم للأعمال الصالحة، ومن باب تكفير السيئات، ومن باب الجمع بينهما.\nس: تجري بهم أعمالهم على الصراط؟\nالشيخ: نعم هي مصيبة، والمصيبة يترتب عليها أشياء كثيرة، قد يترتب عليها توفيق الله العبد لعمل صالح عظيم بسبب صبره واحتسابه وإخلاصه وغير ذلك، وقد يترتب عليها مع ذلك أيضًا تكفير السيئات؛ لأنها من أسباب تكفير السيئات وحط الخطايا، وقد يترتب عليها الأمران جميعًا: توفيق الله له لعمل صالح، وما يحصل له من التكفير.","link":"https://binbaz.org.sa/fatwas/23960/هل-موت-الاطفال-من-اسباب-دخول-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا مات طفل على شخص، من أسباب دخول الجنة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":3773,"question":"ما يدل على الوجوب قوله: أحوط (أي: الغُسل بعد الجِماع وإن لم يُنْزِل)؟","title":"هل يجب الغُسل بعد الجِماع وإن لم يُنْزِل؟","answer":"الجواب: محتمل، لكن السنة ثابتة، الواجب هو الغُسل، وإن لم ينزل، وإذا أنزل وجب عليه الغُسل. لكن إذا لم ينزل فالواجب الغُسل؛ لأن الرسول ﷺ أوضح لهم آخرًا، وأبو هريرة ممن أسلم آخرًا، وحديث عائشة صريح في أنه إذا مس الختان الختان فقد وجب الغسل، وقال: كنت أفعله مع هذه فأغتسل لما سئل عليه الصلاة والسلام، كلها رواها مسلم، وغيره، والرواية في الصحيحين.\nس: ابن حجر ذكر في الشرح قال: قول النبي الماء من الماء قال المراد بالماء الأول ماء الغسل، والثاني المني هذا صحيح؟\nالشيخ: نعم هذا المراد.","link":"https://binbaz.org.sa/fatwas/23969/هل-يجب-الغسل-بعد-الجماع-وان-لم-ينزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجوب الغسل بعد الجماع وإن لم ينزل.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":3839,"question":"هل لا بدّ من النية؟","title":"هل تُشترط النية للكفارات عند المصائب؟","answer":"الجواب: الظاهر لا، الكفارات ليس من شرطها النية، المصائب ولو من غير نية، لكن إذا كان عن نية واحتساب وصبر يعني قارن ذلك؛ يحصل له مزيد ثواب.","link":"https://binbaz.org.sa/fatwas/24041/هل-تشترط-النية-للكفارات-عند-المصاىب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يشترط النية للكفارات عند المصائب.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":3917,"question":"إذا يمَّمَ الصحيحُ المريض؟","title":"وجوب النية إذا يمَّمَ الصحيحُ المريض","answer":"الجواب: لا بد من نية، لا بد المريض ينوي مثل ما يوضيه بالماء.. المريض ينوي التيمم، وهذا يمسح وجهه ويديه بالتراب..\nس: بعضهم يمم المريض وهو ما أخبره؟\nالشيخ: ما يصح، لا بدّ أن يكون بنية.","link":"https://binbaz.org.sa/fatwas/24135/وجوب-النية-اذا-يمم-الصحيح-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجوب النية إذا يمم الصحيح المريض.mp3","categories":["التيمم"]},{"id":3974,"question":"الغدرات التي غدر بها الإنسان ثم تاب منها ورجع؟","title":"ما حكم غدرات الإنسان قبل التوبة؟","answer":"الجواب: هذا في غير التائب، التائب يُعفى عنه، التائب انتهى أمره، هذه أشياء للذين أصروا ولم يتوبوا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24202/ما-حكم-غدرات-الانسان-قبل-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الغدرات التي غدر بها الإنسان ثم تاب منها ورجع.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4079,"question":"التكفير هنا للصغائر، إذا كان مصرًّا على الكبائر؟","title":"هل تكفَّر الصغائر للُمِصّر على الكبائر؟","answer":"الجواب: نعم، تُمنع؛ إصراره على الكبائر يمنع غفران الصَّغائر.\nس: ماذا يُغفر له؟\nج: لا يغفر له، يكون موقوفًا، ولهذا قال سبحانه: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31]، فعلَّق التَّكفير باجتناب الكبائر، وقال في حديث عثمان هذا، وفي الرواية الأخرى: ما لم تُصب في المقتلة يعني إن أصيب في المقتلة، هي الكبيرة؛ لم يُغفر له بوضوئه هذا وصلاته ركعتين... الصَّغائر والكبائر على الصحيح.  وقال بعضُ أهل العلم: تُمحى الصَّغائر، ولكن الشيء المعلّق بالشرط ما يقع؛ لأنَّ غفران الصغائر مشروط باجتناب الكبائر، فإذا وُجد الشرط انتفى المشروط، وهكذا قوله ﷺ: الصَّلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان؛ كفَّارات لما بينهن ما لم تُغش الكبائر، إذا اجتنب الكبائر معناه: أن الكبائر إذا غُشيت ولم تُجتنب؛ لم تكن هذه الصَّلوات كفَّارة، ولا الجمعة، ولا رمضان. س: ...... ماذا يبقى؟ ج: تكون حسنات، يُعطى حسنات، الأعمال الصَّالحات فيها حسنات، فيها خير، ومَن هو الذي يسلم منها؟! لأنَّ الكبائر كثيرة، ثم اختلفوا في حدِّها أيضًا، ويقول بعضُ الناس: أطلق الكبائر على كل ذنبٍ، لكنه ليس بصحيحٍ، الصواب أنَّ فيها كبائر وصغائر، لكن اختلفوا في حدِّ الكبيرة.","link":"https://binbaz.org.sa/fatwas/24318/هل-تكفر-الصغاىر-للمصر-على-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تكفير الصغائر لمن كان مصراً على الكبائر.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4080,"question":"الذي يأتي الكبائر ويُصلي النوافل ويُسبّح ويُهلل، هل له أجر في هذا؟","title":"هل يُؤجر على النوافل مَنْ يأتي الكبائر؟","answer":"الجواب: نعم، له الأجر الذي وعد الله به المؤمنين، لكن لا تُمحى عنه الصَّغائر إلا باجتناب الكبائر.","link":"https://binbaz.org.sa/fatwas/24319/هل-يوجر-على-النوافل-من-ياتي-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يؤجر الذي يأتي الكبائر ويُصلي النوافل ويُسبّح ويُهلل.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4081,"question":"التوبة من الصَّغائر لازمة؟","title":"هل التوبة من الصَّغائر واجبة؟","answer":"الجواب: نعم، التوبة من كل ذنبٍ: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8]، ويقول : وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ [النور:31]، خاطب المؤمنين وهو ما يكون مؤمنًا مع اقتراف الكبائر، يكون ناقص الإيمان.\nس: إذا اجتنب الكبائر، الصغائر يجب منها التوبة؟\nج: إذا اجتنب الكبائر ذهبت الصَّغائر، لكن إذا تاب منها كان ذلك من باب العناية والحذر؛ لأنه ما يدري هل سلم له إيمانه من الكبائر، أو عنده شيء، فالإنسان دائمًا على خطرٍ، فإن الغيبة والنميمة والربا وقطيعة الرحم والعقوق والسبّ والشتم وأشياء أخرى كلها داخلة في الكبائر، نسأل الله السلامة، ومَن يسلم من الغيبة؟!","link":"https://binbaz.org.sa/fatwas/24320/هل-التوبة-من-الصغاىر-واجبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل التوبة من الصَّغائر لازمة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4088,"question":"ما حصل من الدنيا ينقص الأجر يوم القيامة؟","title":"هل ينقص التمتع بملذات الدنيا من أجر الآخرة؟","answer":"الجواب: مثلما جاء في هذا الحديث: التمتع بملذَّاتها ونعيمها، والله المستعان، والله أعلم، هذه رواية ابن أبي الدنيا، يقول المنذري: بسندٍ حسنٍ والله أعلم، قد يحتجّ له بقوله جلَّ وعلا: وَيَوْمَ يُعْرَضُ الَّذِينَ كَفَرُوا عَلَى النَّارِ أَذْهَبْتُمْ طَيِّبَاتِكُمْ فِي حَيَاتِكُمُ الدُّنْيَا وَاسْتَمْتَعْتُمْ بِهَا [الأحقاف:20].\nويُروى عن عمر: أنه رأى جابرًا معه شيء من لحمٍ اشتراه للأهل، فقال: أوكلّما اشتهيتُم اشتريتُم؟! أما سمعتَ الله يقول لقومٍ: أَذْهَبْتُمْ طَيِّبَاتِكُمْ فِي حَيَاتِكُمُ الدُّنْيَا؟\nالمقصود أنه ينبغي للإنسان أن يفعل بعض الشيء من جهة التَّقلل، ومن جهة الزهد في بعض الشيء؛ حتى يُعوّد نفسه القناعة، لا يكون دائمًا دائمًا على شراء الملذات والطيبات، بل بعض الأحيان يتقشَّف بعض الشيء، ويتخفف بعض الشيء؛ حتى لا تعتاد النفسُ الرغبة في هذه الأشياء التي تُعتبر من ملذَّاتها العاجلة، ومن مشاغلها العاجلة، ومن التَّكلف حتى يحتاج إلى أموالٍ كثيرةٍ ربما سببت له الوقوع في أكسابٍ ما هي طيبة، أو اقتراض قد يشقّ عليه دفعه، وأما إذا يسَّر الله فالأمر واسعٌ بحمد الله، مثلما قال جلَّ وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ [البقرة:172]، الأمر واسع، وقال تعالى: يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا [المؤمنون:51]، فإذا كان عن يسرٍ، وعن عدم تكلُّفٍ؛ فالحمد لله.","link":"https://binbaz.org.sa/fatwas/24328/هل-ينقص-التمتع-بملذات-الدنيا-من-اجر-الاخرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث لا يصيب عبد من الدنيا شيئا إلّا نقص من درجاته..mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4122,"question":"اليوم هذا يوم الجزاء: هل المؤمنين يكونوا مكسيين، أو عراة في الوقوف هذا؟","title":"متى يُكسى المؤمنون يوم القيامة؟","answer":"الجواب: يكونون عُراة، أولًا يُكسى إبراهيم عليه الصلاة والسلام.\nس: لا يأكلون ولا يشربون حتى المؤمنين في هذا اليوم العظيم؟\nج: الناس مشغولون بالهمِّ العظيم والله المستعان، أما وقت الكسوة الله أعلم، أولًا يُكسى إبراهيم، ثم يُكسى المؤمنون والأنبياء، لكن متى يكون هذا؟ الله أعلم: في أثناء اليوم، أو بعد دخولهم الجنة، الله أعلم.","link":"https://binbaz.org.sa/fatwas/24365/متى-يكسى المومنون-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بعض أهوال القيامة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4123,"question":"يُرفع القرآن.. أحسن الله إليك؟","title":"هل من علامات الساعة رفع القرآن والدين؟","answer":"الجواب: يُرفع القرآن، ويُرفع الدين كله، ما يبقى شيء، ما يبقى إلا الكفر -نسأل الله العافية- ولهذا قال: إذا طلعت الشمسُ من مغربها آمن الناسُ كلهم لكن لا ينفعهم ذلك؛ لأنَّ طلوعها من مغربها علامة ظاهرة، فلهذا إذا رآها الناسُ آمنوا كلهم، لكن لا ينفعهم، لا ينفع الذين كانوا كفَّارًا إيمانهم بعدما رأوا طلوع الشمس من مغربها، نسأل الله السلامة: يَوْمَ يَأْتِي بَعْضُ آيَاتِ رَبِّكَ لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا [الأنعام:158]، فالأمر محدد بطلوع الشمس من مغربها، متى طلعت من مغربها خُتم على الأعمال، فالمؤمن على إيمانه، والكافر على كفره -نسأل الله العافية- ثم يبعث الله ريحًا طيبةً مسّها مسّ الحرير، فتقبض أرواح المؤمنين والمؤمنات، فلا يبقَ إلا الأشرار، فعليهم تقوم الساعة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24368/هل-من-علامات-الساعة-رفع-القران-والدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من علامات الساعة رفع القرآن والدين كله.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4138,"question":"معرفة الرسول ﷺ لهم فيقول أصيحابي، يقصد معرفتهم بآثار الوضوء محجلين غرلًا؟","title":"كيف يعرف النبي ﷺ أصحابه في القيامة؟","answer":"الجواب: غُرْلًا مُحجَّلين، نعم، هذه علامة الأمة.","link":"https://binbaz.org.sa/fatwas/24385/كيف-يعرف-النبي-ﷺ-اصحابه-في-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف يعرف النبي أصحابه في القيامة.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4150,"question":"إقامة الحد مكفِّر أم لا بد من التوبة؟","title":"هل إقامة الحد مكفِّر أم لا بد من التوبة؟","answer":"الجواب: الحدود مُكفِّرات، التوبة مُكفِّرة، والحدود مُكفِّرات إذا لم يرجع إلى العمل، مُكفِّرة لما مضى، يعني: قبل الحدِّ.","link":"https://binbaz.org.sa/fatwas/24400/هل-اقامة-الحد-مكفر-ام-لا-بد-من-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحدود والتوبة مكفرات للذنوب.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4209,"question":"الذنوب التي مات ولم يتب منها؟","title":"حكم ذنوب المسلم التي مات ولم يتب منها","answer":"الجواب: كذلك مثل ما في الحديث، لما سترها عليه في الدنيا بينه وبين ربه  غفرها له  وقد تكون من الصغائر التي تغفر باجتناب الكبائر: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31] فالعبد يجتنب الكبائر وتكفر عنه الصغائر، قد تكون سيئة بين العبد وبين ربه لم يطلع عليها سواه  ولم يقدر للعبد أن يتوب منها فغفرها الله له بجنب حسناته وأعماله الصالحة الكثيرة ورضا الله عنه لما فعل من الخير وصار قطرة في البحر، قطرة من نجاسة في بحر من الخيرات فعفا  عنه .","link":"https://binbaz.org.sa/fatwas/24472/حكم-ذنوب-المسلم-التي-مات-ولم-يتب-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الذنوب التي مات ولم يتب منها.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4215,"question":"في بعض الحالات يمر على العبد يطير شوقًا للموت ولقاء ربه جل وعلا، والحالة الثانية يكره الموت، ويكره كذلك...؟","title":"حكم كراهية المؤمن للموت","answer":"الجواب: هذا من طبيعة الناس كراهة الموت، من طبيعة الناس، مثلما قالت عائشة رضي الله عنها لما قال النبي ﷺ: من أحب لقاء الله أحب الله لقاءه ومن كره لقاء الله كره الله لقاءه فقالت عائشة: يا رسول الله أهو الموت فكلنا يكره الموت؟  فمن طبيعة الإنسان الغالبة عليه أنه يكره الموت ويحب الحياة، فالمؤمن يحب أن يزداد عملًا صالحًا، وغير المؤمن يحب أن يرتع في شهواته، قال: لا ولكنه المؤمن إذا حضره أجله وبشر بالجنة أحب لقاء الله فأحب الله لقاءه والكافر إذا حضر أجله وبشر بالنار كره لقاء الله وكره الله لقاءه أو كما قال عليه الصلاة والسلام.  فإذا وقع في قلب الإنسان بعض الأحيان اشتياق إلى الموت ليلقى ربه؛ لما وقع في قلبه من حسن الظن بالله والشوق إلى لقائه والرغبة فيما عنده ولما يشاهده في الدنيا من الشر والبلاء والفساد والخطر، هذا قد يقع للمؤمن، ولكن مع هذا كله لا يجوز له أن يطلب الموت ولا أن يتمناه كما في الأحاديث الصحيحة النهي عن ذلك، ولكن هذا من رحمة الله له، ومما يعجّله الله له من اللذة والسرور والنعيم.","link":"https://binbaz.org.sa/fatwas/24479/حكم-كراهية-المومن-للموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أهو الموت فكلنا يكره الموت.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4410,"question":"غسل الرجل مع امرأته يكون سُنةً؟","title":"حكم غسل الرجل مع امرأته","answer":"الجواب: جائز، جائز، حكمه الجواز.\nس: ما يكون سنةً؟\nج: محل نظرٍ، النبي فعله يدل على جوازه، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24687/حكم-غسل-الرجل-مع-امراته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم غسل الرجل مع امرأته.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":4422,"question":"المني إذا خرج من غير شهوةٍ؟","title":"ما حكم المني إذا خرج من غير شهوةٍ؟","answer":"الجواب: إذا خرج لأجل المرض يكون الحكم حكم الأبوال، ..... الحكم حكم سائر الفضلات التي تخرج من الإنسان؛ توجب الوضوء.","link":"https://binbaz.org.sa/fatwas/24700/ما-حكم-المني-اذا-خرج-من-غير-شهوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المني إذا خرج من غير شهوةٍ.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":4469,"question":"هل يُشرع التيمم لردِّ السلام ولو كان عنده الماء؟","title":"هل يُشرع التيمم لردِّ السلام؟","answer":"الجواب: هذا محل نظر، قد يكون هذا التيمم ليس عنده ماء؛ لأنَّ الأصل: فَلَمْ تَجِدُوا مَاءً [النساء:43]، هذا هو الأصل، فيُحمل هذا على أنه تيمم؛ لأنه في مكانٍ ليس عنده ماء، والمصلحة تفوت.","link":"https://binbaz.org.sa/fatwas/24747/هل-يشرع-التيمم-لرد-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُشرع التيمم لردِّ السلام.mp3","categories":["التيمم"]},{"id":4474,"question":"هل يُباشر الوضوء قبل مُباشرة الغسل، وقد يمسّ فرجه للتنظيف؟","title":"حكم مس الفرج بعد الوضوء وقبل الغسل","answer":"الجواب: ما يمس، إذا استنجى لا يمس فرجه، انتهى، إذا استنجى وغسله بنية الطهارة انتهى، لكن لو غسل ما حوله، ومسح يده على ما حوله... ما يضره.\nس: يعني: يُباشر الوضوء، يعني: قبل مُباشرة الغسل يبدأ بالوضوء؟\nج: ... نعم: ثم يتوضأ وضوء الصَّلاة.","link":"https://binbaz.org.sa/fatwas/24753/حكم-مس-الفرج-بعد-الوضوء-وقبل-الغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الوضوء قبل مُباشرة الغسل، ومس الفرج.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":4483,"question":"إذا كان على وجه الأرض حجارة أو أرض صلبة هل يتيمم؟","title":"حكم التيمم على الأرض الصلبة","answer":"الجواب: يتيمم، يعمّه الصعيد، حسبما يتيسر له إذا ما وجد شيئًا.\nس: ما فيها رمل ولا شيء؟\nج: ما على وجه الأرض هو الصعيد، إذا تيسر الترابُ فالحمد لله، وإلا ولو في جبلٍ.\nس: ما يكون فاقد الطَّهورين، يُصلي بدون ..؟\nج: ممكن أن يُقال، لكن العموم يقتضي أنه يفعل: فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا [النساء:43]، يمسح بما عنده من جبلٍ أو جصٍّ أو رملٍ أو غير ذلك، والمعنى واحد .....، لكن هذا أحوط خروجًا من الخلاف؛ لأن جمعًا من أهل العلم قالوا: يضرب الأرض مطلقًا ولو كانت جبليَّةً، المهم يكون ضربه لها ما يُنافي قول مَن قال: إنه فقد الطَّهورين؛ لأنَّ فاقد الطَّهورين معذورٌ، وهذا معذورٌ إذا ضربها؛ لأنه اتَّقى الله ما استطاع.","link":"https://binbaz.org.sa/fatwas/24763/حكم-التيمم-على-الارض-الصلبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يتيمم على الأرض الصلبة.mp3","categories":["التيمم"]},{"id":4484,"question":"إذا ذهب البردُ في الصباح يجب عليه الغسل؟","title":"هل يلزم من تيمم لشدة البرد الغسل لاحقًا؟","answer":"الجواب: لا، ما يُعيد، يغتسل فقط، في الحديث: الصعيد وضوء المسلم وإن لم يجد الماء عشر سنين، فإذا وجد الماء فليتَّقِ الله وليمسّه بشرته.\nس: لكن ما يجب عليه الغُسل؟\nج: يجب عليه الغسل عن الجنابة، أما الوضوء لا، انتهى الوضوء، إذا صلَّى صحَّت الصلاةُ ولا يُعيد شيئًا، ولكن من الجنابة فقط.","link":"https://binbaz.org.sa/fatwas/24764/هل-يلزم-من-تيمم-لشدة-البرد-الغسل-لاحقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من تيمم لرفع الحدث لعلة البرد وذهب البرد.mp3","categories":["التيمم"]},{"id":4485,"question":"يجب الترتيب في التيمم؟","title":"حكم الترتيب في التيمم","answer":"الجواب: هذا هو الأصل في الوضوء خاصةً، لكن ينبغي له أن يفعل كما فعل في الوضوء؛ لأنه جعل التيمم واحدًا، الرسول جعله واحدًا في هذا، والمؤمن ينبغي له أن يفعل كما أمره الله، أما إذا راعى الأصلَ في الغسل ولم يُرتب فالظاهر أنه يُجزئه ذلك في غسل الجنابة، ولكن يكون خالف الأوْلى، والذي ينبغي له في التيمم أن يفعل كما جاء في الآية: بِوُجُوهِكُمْ وَأَيْدِيكُمْ [النساء:43]، وكما في حديث عمار، سواء كان عن جنابةٍ، أو عن حدث أصغر؛ لأنَّ الله خفَّف ويسَّر وجعلهما واحدًا في هذا.","link":"https://binbaz.org.sa/fatwas/24765/حكم-الترتيب-في-التيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الترتيب في التيمم.mp3","categories":["التيمم"]},{"id":4529,"question":"مَن جرَّ ثوبه دائر أمره بين كبيرةٍ صغرى وكبيرةٍ كبرى أكبر منها، يعني... إن جرَّ ثوبه خُيلاء: كبيرة؟","title":"هل تتفاوت كبائر الذنوب وصغائرها؟","answer":"الجواب: الكبائر تختلف، حتى الكبائر نفسها تختلف، تتفاوت، أقول: الكبائر تختلف.\nس: يعني على كلتا الحالتين تكون كبيرةً؟\nج: نعم، هذا ظاهر النصوص: \"النائحة\" النياحة كبيرة، والزنا أكبر منها، والعقوق كبيرة، وقطيعة الرحم الأخرى - العقوق لغير الوالدين- أسهل من الوالدين، وهكذا؛ فالكبائر متفاوتة، والصَّغائر متفاوتة.","link":"https://binbaz.org.sa/fatwas/24809/هل-تتفاوت-كباىر-الذنوب-وصغاىرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كبائر الذنوب وصغائرها تتفاوت.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4749,"question":"بالنسبة للشرط الأخير من شروط التوبة الذي هو: ردّ المظالم، يقول: أنا فقير لا أستطيع أن أردَّ المظالم مثلًا من سرقةٍ؟","title":"حكم من لا يستطيع رد المظالم","answer":"يستحلّه منها، فإذا عجز عن ذلك فالله يعلم تمام عزمه، إذا عزم على ذلك عفا الله عنه، إذا عجز عنها ولم يسمحوا عنك فالله يُسامحك، إذا صدق في التوبة؛ لأنَّ العاجز الصَّادق كالمؤدي.","link":"https://binbaz.org.sa/fatwas/25089/حكم-من-لا-يستطيع-رد-المظالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من شروط التوبة ردّ المظالم، فما حكم من أراد التوبة وهو فقير لا يستطع رد ما أخذه.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4778,"question":"يقول إذا كنت في مكان وكانت الماء مقطوعة هل يجوز لي التيمم، أم لا بدّ من الذهاب بالسيارة إلى مكان الماء، مع العلم بأن الماء متوفر على بعد عشرة كيلو مترات تقريبًا أو أقل؟","title":"هل يجب البحث على من فقد الماء قبل التيمم؟","answer":"ما دام أن الماء موجود فعليه أن يسعى للماء؛ لأن هذا يعد قريبًا عرفًا، فعليه أن يتوضأ ولا يتمم، أما إذا كان بعيدًا بحيث يفوت غالب الوقت أو يفوت الوقت؛ فلا حرج في التيمم.","link":"https://binbaz.org.sa/fatwas/25142/هل-يجب-البحث-على-من-فقد-الماء-قبل-التيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجوب البحث عن الماء قبل التيمم.mp3","categories":["التيمم"]},{"id":4806,"question":"إذا اغتسل ناويًا التَّبرد، ونوى الوضوء هل يُجزئ؟","title":"هل يُجزئ غسل التَّبرد عن الوضوء؟","answer":"ما يُجزئ، لا بدّ من الوضوء الشرعي.","link":"https://binbaz.org.sa/fatwas/25201/هل-يجزى-غسل-التبرد-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من اغتسل ناويًا التَّبرد ونوى الوضوء فهل يُجزئ.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":4950,"question":"ما هو ضابط البَرْد الذي يجوز من أجله التيمم؟","title":"ما ضابط البَرْد الذي يجوز من أجله التيمم؟","answer":"الجواب: إذا كان يضره البرد، وما عنده ما يدفئ الماء في البرد، في البريّة مثلًا ما عنده ما يدفئ به الماء؛ جاز له التيمم.","link":"https://binbaz.org.sa/fatwas/27488/ما-ضابط-البرد-الذي-يجوز-من-اجله-التيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما ضابط البَرْد الذي يجوز من أجله التيمم؟.mp3","categories":["التيمم"]},{"id":4951,"question":"التيمم بالرمل؟","title":"هل يجوز التيمم بالرمل؟","answer":"الجواب: بالرمل، وغيره، حسب ما يجد: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن: 16].","link":"https://binbaz.org.sa/fatwas/27524/هل-يجوز-التيمم-بالرمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز التيمم بالرمل؟.mp3","categories":["التيمم"]},{"id":4953,"question":"اشتراط الغبار للتراب عند الفقهاء لا بدّ منه؟","title":"هل يشترط وجود الغبار في تراب التيمم؟","answer":"الجواب: مثل ما قال الله جل وعلا: فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ [المائدة: 6]، منه: ما يكون منه إلا بوجود التراب، أو بوجود الغبار، إما تراب وإلا غبار.","link":"https://binbaz.org.sa/fatwas/27522/هل-يشترط-وجود-الغبار-في-تراب-التيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يشترط وجود الغبار في تراب التيمم؟.mp3","categories":["التيمم"]},{"id":4966,"question":"هل يكون فيه غفران بلا توبة؟","title":"هل يمكن حصول الغفران لأحد دون توبته؟","answer":"الجواب: قد يغفر الله بلا توبة، قال تعالى: وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] قد يغفر الله له فضلًا منه أو لأعمال صالحة فعلها أو لمعروف بذله أو لتفريج كربة لمسلم أو لصدقة فعلها أو لأسباب أخرى.\nس: قول بعض السلف: ما أظن اللهَ أن يغفر للمأمون إدخاله كتب اليونان؟\nالشيخ: كل هذا ما يجوز.","link":"https://binbaz.org.sa/fatwas/27666/هل-يمكن-حصول-الغفران-لاحد-دون-توبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يمكن الغفران لأحد دون توبته.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":4973,"question":"أعمال القلب \"الخَطَرات\" تسجلها الملائكة؟","title":"هل تسجّل الملائكة خطرات القلب؟","answer":"الجواب: الخَطَرات التي ما تستقر الظاهر ما تُسجل، ما يٌسجل إلا العمل الذي يستقر، إما فعل وإلا قول.","link":"https://binbaz.org.sa/fatwas/27969/هل-تسجل-الملاىكة-خطرات-القلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تسجّل الملائكة خطرات القلب؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":5048,"question":"العبد إذا كان مُعافًى من الذنب أفضل أم إذا كان يُذنب ويتوب وهو يُعاني من نفسه ويُجاهدها مجاهدةً عظيمةً في الله؟","title":"هل العافية من الذنب أفضل أم جهاد النفس؟","answer":"الجواب: المحتوى: مَن رزقه الله العافيةَ والسلامة؛ فهو أفضل بلا شكٍّ.","link":"https://binbaz.org.sa/fatwas/29287/هل-العافية-من-الذنب-افضل-ام-جهاد-النفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل العافية من الذنب أفضل أم جهاد النفس؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":5063,"question":"ضابط الصغائر ومثالها؟","title":"ما ضابط الصغائر والكبائر من الذنوب؟","answer":"الجواب: فيها اختلاف، في ضبط الصغائر، ينبغي للمؤمن أن يحذر السيئات كلها بالكلية؛ فالواجب على المؤمن أن يحذر السيئات كلها بالكلية صغيرها وكبيرها؛ حتى لا يقع في شيء من الكبائر، نسأل الله العافية.\nوالأكثر في تعريف الكبيرة أنها: ما فيه حد في الدنيا أو وعيد في الآخرة؛ كالسرقة والزنا والخمر، ما فيه حد في الدنيا أو وعيد في الآخرة؛ والغيبة والنميمة، كلها فيها وعيد.\nس: ما ترون التنفير من الصغائر حتى لا يتساهل الناس؟\nج: الواجب الحذر من جميع الذنوب، ويعتبرها كبائر حتى يحذرها؛ لأن كل سيئة قد يظنها صغيرة وهي كبيرة؛ فيجب الحذر.","link":"https://binbaz.org.sa/fatwas/29351/ما-ضابط-الصغاىر-والكباىر-من-الذنوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما ضابط الصغائر والكبائر من الذنوب؟.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":5082,"question":"هذا سائل يقول: وبعد إلى فضيلة الشيخ عبد العزيز أطال الله في عمره رب العالمين، وجعله سبحانه ذخرًا لهذه الأمة آمين لدي يا فضيلة الشيخ ثلاث مسائل أود الإجابة عليها.الأولى: أنني يا فضيلة الشيخ إنسان مؤمن بالرب، والحمد على ذلك، والصلاة أقوم بها، والصوم كذلك، والعمرة فقد اعتمرت حتى الآن ثلاثة عشر مرة، وعمري تسعة عشر سنة، ومنذ حوالي ست سنوات مضت أقوم بشيء لا يرضاه الرب، ولا رسوله، وهو - والعياذ بالله - اللواط، والعادة السرية، ففي عامنا الفائت، وفي إجازة الربيع (1404هـ) ذهبنا إلى مكة لأخذ عمرة فصممتُ التوبة لله عن هاتين العادتين السيئتين، فتبتُ، ولله الحمد على ذلك، فلما أتى رمضان في نفس العام، أخذتُ عمرةً أيضًا، والمشكلة حينما انتهى رمضان عدتُ للعادة السرية فقط، ولم أرجع للواط، وحينما دخل عامنا (1405هـ)، وبدأت اختبارات نصف السنة التي قد مضت منذ ما يقرب الشهرين عُدت - والعياذ بالله - إلى عادة اللواط، وتركتُها، وأود من فضيلتكم الإفتاء في ذلك، وإفادتي أفادكم الله، حتى أتوب إلى الله توبة نصوحًا، وكيف الطريق إلى ذلك؟","title":"حكم من تاب من الفواحش والمنكرات ثم رجع إليها","answer":"الجواب: الله جلَّ وعَلا حرَّم علينا الفواحش ما ظهر منها وما بطن، وأوجب علينا التوبة النصوح من جميع الذنوب، فقال : وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، وقال سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8]، وقال سبحانه: أَفَلا يَتُوبُونَ إِلَى اللَّهِ ويَسْتَغْفِرُونَهُ واللَّهُ غَفُورٌ رَحِيمٌ [المائدة:74] هذه الآيات وما جاء في معناها كلها تدل على وجوب التوبة، وأنه  قد فتح أبوابها، ويسّرها لعباده. فعليك أيها السائل أن تتقي الله، وأن تجزم بالتوبة، وتصدق بالتوبة، وأن تبتعد عن نقضها، وأن تحذر مكائد الشيطان، فإن الشيطان عدو مبين، وله نواب من الإنس يدعون إلى الفواحش والمنكرات ويحبّبونها، ويحبّبون نقض التوبة، ويقولون: إن الله غفور رحيم، إن الله تواب حكيم، إن الله كذا، إن الله كذا؛ حتى يوقعوك فيما حرم الله، وقد ينزل بك الأجل، وأنت على معاصي الله ، فيحال بينك وبين التوبة، ولا حول ولا قوة إلا بالله. فالواجب عليك أن تجزم على التوبة، وتصدق في التوبة من اللواط، ومن العادة السرية، هذان محرمان، واللواط أعظم وأشنع؛ لأن اللواط من كبائر الذنوب، ومن أعظم الجرائم، جاء في الحديث: لعن الله من عمل عمل قوم لوط، لعن الله من عمل عمل قوم لوط، لعن الله من عمل عمل قوم لوط، وقال الله في كتابه العظيم عن اللوطية: إِنَّكُمْ لَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُمْ بِهَا مِنْ أَحَدٍ مِنَ الْعَالَمِينَ [العنكبوت:28] فأخبر أن اللوطية ما سبقهم أحد، قوم لوط، ما سبقهم أحد إلى هذه الفاحشة ممن قبلهم، نسأل الله العافية، وفي الحديث: من وجدتموه يعمل عمل قوم لوط، فاقتلوا الفاعل والمفعول به، وقد أجمع علماء الصحابة رضي الله عنهم على أن اللائط والملوط به يُقتلان إذا كانا مكلَّفَين؛ لأنها جريمة أشنع من جريمة الزنا، والعياذ بالله. فيجب الحذر، والتوبة الصادقة، والبُعد عن أسباب ذلك، وعن مخالطة من يدعو إلى ذلك، أو يجر إلى ذلك، أو تتوق النفس إلى فعل ذلك معه، يجب الحذر من أولئك؛ فإن صحبة الأشرار من أعظم أسباب الشر، ومن أعظم دواعي الشر، فيجب البُعد عن صحبة الأشرار، ويجب الحرص على صحبة الأخيار، مع سؤال الله الثبات، والتوفيق للاستقامة على التوبة، وعدم نقضها. وهكذا العادة السرية عادة قبيحة ومنكَرة، قال الله فيها وما في معناها: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ  ۝  إِلَّا عَلَى أَزْوَاجِهِمْ أو مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ  ۝  فَمَنِ ابْتَغَى ورَاءَ ذَلِكَ فَأُولَئِكَ هُمُ الْعَادُونَ [المؤمنون:5-7] أي: الظالمون، والعادة السرية غير الزوجة، وغير ملك اليمين، فتكون من العدوان والظلم، وفيها مضار كثيرة كما بيَّن أهل العلم، وبيَّن أهل الطب. فيجب عليك الحذر منها؛ لأنها عادة سيئة منكَرة، فإياك وإياها، واحذرها، واحذر من يشير بها، أو يدعو إليها. نسأل الله لنا ولك الهداية والثبات على الحق والصدق في التوبة.","link":"https://binbaz.org.sa/fatwas/29984/حكم-من-تاب-من-الفواحش-والمنكرات-ثم-رجع-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 01.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":5083,"question":"ذهبنا مع بعض الأصدقاء إلى رحلة خارج الرياض، وبالضبط في الثمامة، فخرجنا يوم الأربعاء في الليل، فحينما جاء وقت النوم نمنا، فلما أصبحنا على يوم الخميس، وجدتُ نفسي قد احتلمتُ، وأصبحت عليَّ جنابة، ونحن عددنا أربعة، ولا يوجد معنا غير جالون ماء للشرب والأكل، فأخبرتُ أحد الأصدقاء بما حدث لي، فقال لي: تعفَّر، وصلِّ معنا الفجر، يجوز لك ذلك، فعملتُ ما أمرني به، ولما جاء، وقت صلاة الظهر شككتُ في الأمر، ولم أصلِّ معهم جميع الأوقات من فجر يوم الخميس إلى عشاء ليلة السبت في نهار الجمعة، فلما ذهبنا إلى الرياض صليتها بعد أن اغتسلتُ، وبدون أن أقصر في جميع الأوقات فيما فاتني، فماذا عليَّ في ذلك؟","title":"ما كيفية الطهارة من الجنابة عند عدم الماء؟","answer":"الجواب: الواجب عليك إذا وقع مثل هذا أن تنظر، إن وجدتَ ماءً قريبًا منك تستطيع الغسل به فعلتَ، ووجب عليك ذلك، فإن لم تجد تيممت كما قال لك صاحبك، تعفَّرت بالتراب وكفى؛ لأن الله  يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [النساء:43]، ويقول النبي ﷺ: وجُعِلَت الأرض مسجدًا وطهورًا، فأيما رجل من أمتي أدركته الصلاة فعنده مسجده وطهوره، ويقول ﷺ: وجُعِلَ التراب لي طهورًا إذا لم نجد الماء، فمن لم يجد الماء فالصعيد، وضوءه. فعليك إذا فقدتَ الماء في أي مكان أن تتيمم، وتضرب التراب بيديك، وتمسح به وجهك، وكفيك كما أمر الله  وتصلي، وليس عليك إعادة، تجزئ، وإذا كنتَ في محل فيه ماء وجب عليك الغسل، وإذا كان الوقت باردًا سخَّنته بالنار، وإذا لم تجد نارًا، وخشيت على نفسك شدة البرد؛ تيممتَ وصليت، وأجزأك، والحمد لله. وأما تركك للصلاة معهم المدة الطويلة يوم الخميس والجمعة، فهذا غلط وخطأ منك، فعليك التوبة إلى الله من ذلك، والندم على ما مضى منك، وعدم العودة إلى ذلك، وقد أحسنتَ في قضاء الصلاة لَمَّا تمكنت من الماء؛ ولكنك أخطأت في تركها، وفي التأخير. فالواجب التوبة من ذلك، وألا تؤخّرها عن وقتها، إن وجدتَ ماءً فاغتسل، وإلا فتيمم وصلِّ، ولا تؤخرها عن وقتها أبدًا.","link":"https://binbaz.org.sa/fatwas/29985/ما-كيفية-الطهارة-من-الجنابة-عند-عدم-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 02.mp3","categories":["التيمم"]},{"id":5233,"question":"أخ يسأل ويقول: ما علاج قسوة القلب؟","title":"ما علاج قسوة القلب؟","answer":"الجواب: قسوة القلب له علاجٌ كثير، أعظم ذلك: الإقبال على الله بقراءة كتابه العظيم، وتدبر معانيه، والإكثار من ذكره ، والعناية بما أوجب الله من الصلاة وغيرها، والحذر مما حرَّم الله.......، وتأثر العبد بذكر الله وقراءة كتابه، واعتنى بما أوجب الله عليه من الصلاة وغيرها، وابتعد عن محارم الله...... كما قال : أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا أَنْ تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ اللَّهِ وَمَا نَزَلَ مِنَ الْحَقِّ وَلَا يَكُونُوا كَالَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلُ فَطَالَ عَلَيْهِمُ الْأَمَدُ فَقَسَتْ قُلُوبُهُمْ وَكَثِيرٌ مِنْهُمْ فَاسِقُونَ [الحديد:16]، فطول الأمد على مَن قبلنا حتى ضيَّعوا وتكاسلوا هو الذي قسَّى قلوبهم، ومَن قصَّر الأمل، واتَّبع شرع الله، وابتعد عن محارم الله؛ ليَّن اللهُ قلبَه، وشرح صدره، واستقام على الطريق. وفي الحديث: لا تُكثروا الكلام بغير ذكر الله، فإنَّ كثرة الكلام بغير ذكر الله قسوةٌ للقلوب، وإن أبعد القلوب من الله القلب القاسي، فالإكثار من الكلام، والقيل والقال والخوض بغير حقٍّ من أسباب قسوة القلوب، والإكثار من ذكر الله وقراءة كتابه والاستغفار والاستكثار من الأعمال الصَّالحات بعد أداء الفرائض وترك المحارم؛ كل هذا من أعظم الأسباب، بل هو السبب الوحيد في لين القلب والسلامة من قسوته. ومما يدل على هذا المعنى: قوله ﷺ: إذا أذنب العبدُ نكت في قلبه نكتة سوداء، فإن هو تاب مُحيت وصُقِلَ قلبُه، وإن عاد في الذنوب نكت نكتة أخرى سوداء، وهكذا حتى يسود القلبُ، وحتى يُظلم القلبُ، قال: وذلك الران وتلا قوله تعالى: كَلَّا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ [المطففين:14]، هذا معنى الحديث. المقصود أن الذنوب من أسباب سواد القلب وظلمته وقسوته، والتوبة إلى الله وتعاطي الأعمال الصَّالحة من أسباب صفائه ولينه وقوته وغيرته وسلامته.","link":"https://binbaz.org.sa/fatwas/30177/ما-علاج-قسوة-القلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 301.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":5252,"question":"يقول هذا السائل: أرجو من سماحتكم أن تُبيِّنوا لنا طريقة التَّيمم الصَّحيحة؟","title":"ما طريقة التَّيمم الصَّحيحة؟","answer":"الجواب: التَّيمم بالصعيد مثلما قال الله : فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ [النساء:43]، مسحة واحدة لليد والوجه، يضرب التراب، يعني: يضع يديه في التراب ضربًا، التراب الطيب الطاهر في الأرض، أو في الإناء الذي فيه التراب، أو الخرقة التي فيها التراب، أو الفراش الذي فيه التراب، ثم يمسح وجهه وكفّيه، يمسح وجهه هكذا، وكفَّيه هكذا...، ثم كفّيه... التراب يمسح به وجهه، ثم يمسح بالبقية كفّيه ظاهرهما وباطنهما، هذا هو التيمم، وليس هناك حاجة إلى مسح الذراعين أو الرأس، لا، من فضل الله وتيسيره أنه سبحانه جعل الوجه واليدين كافيين، في الوضوء يغسل وجهه ويديه، ويمسح رأسه وأذنيه، ويغسل رجليه، لكن في التيمم ربنا جلَّ وعلا يسَّر وسهَّل، وجعل الوجه والكفَّين كافيين، يمسح المريضُ وجهَه وكفَّيه ويكفي، والحمد لله. ويقوم التيمم مقام الماء على الصحيح، إذا تيمم صلَّى بالتيمم النافلة والفريضة، والحاضرة والمستقبلة، ما دام على طهارةٍ، حتى يُحدِث أو يجد الماء إن كان عادمًا له، أو حتى يستطيع استعماله إذا كان عاجزًا عن استعماله؛ لأن التيمم طهورٌ يقوم مقام الماء، كما سمَّاه النبيُّ: طهورًا.","link":"https://binbaz.org.sa/fatwas/30713/ما-طريقة-التيمم-الصحيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 893.mp3","categories":["التيمم"]},{"id":5308,"question":"بعض النساء يُشكل عليها الغسل من الجنابة والحيض، نرجو من سماحتكم تفصيل كيفية الغسل، وهل تطهر المرأة من الجنابة إذا حثت على رأسها ثلاث حثيات، وهل يلزمها غسل جميع الرأس بالماء؟","title":"ما صفة الغسل من الجنابة والحيض والنفاس؟","answer":"الجواب: الجنب والحائض والنفساء كلهم غسلهم متقارب، تعم بدنها بالماء وتفيض على رأسها الماء، لكن السُّنة أن يبدأ بالوضوء، يستنجي أولًا، الحائض تستنجي والنفساء والجنب، تستنجي أولًا، ثم يتوضأ وضوء الصلاة ثم يفيض الماء على رأسه ثلاث غرفات، ثم على جنبه الأيمن ثم جنبه الأيسر ثم يُكمل، هذا السُّنة ولا حاجة إلى نقض الرأس، لكن الحائض يستحب لها النقض؛ لأن مدتها تطول، والنفساء، فإذا نقضت كان أفضل في الغسل فتغسله بالماء، فإن أمرّت عليه الماء من غير نقض فكفى. فالحاصل أن المقصود هو إفاضة الماء على البدن، فإذا أفاض الماء على بدنه بنية غسل الحيض أو غسل الجنابة أو غسل النفاس؛ كفى، لكن الأفضل أنه بعد الاستنجاء يتوضأ وضوء الصلاة، ثم يفيض الماء على رأسه ثلاث غرفات يعمها على الرأس، ثم جنبه الأيمن ثم جنبه الأيسر، ثم بقية بدنه حتى يكمل، الجنب والحائض والنفساء، لكن النفساء والحائض يستحب لهما النقض، في بعض الأحاديث النقض (انقضي رأسك) فإذا نقضت كان أفضل مع الماء والسدر، والجُنب لا يحتاج إلى سدر، الماء يكفي.[1]","link":"https://binbaz.org.sa/fatwas/30962/ما-صفة-الغسل-من-الجنابة-والحيض-والنفاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 028.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":5390,"question":"الرجل يُسَرُّ من ثناء الناس؟","title":"هل يتنافى الإخلاص مع السرور بثناء الناس؟","answer":"الجواب: لا يضرُّه إذا كان لم يعمل من أجلهم، مثلما قال النبي: تلك عاجل بشرى المؤمن، إذا سُرَّ به ولم يعمل لأجلهم، ولكن سمعوا أنه يدعو إلى الله فدعوا له وأثنوا عليه، سمعوا أنه يتصدق فدعوا له وأثنوا عليه، ولكنه ما قصدهم؛ ما يضره، هذه عاجل بُشرى المؤمن. س: قول مَن قال: إن علامة الإخلاص أن يستوي عندك الذم والمدح؟ ج: لا، ما هو شرط، إذا استبشر بدعاء الناس ما يضرّ، تلك عاجل بُشرى المؤمن.[1]","link":"https://binbaz.org.sa/fatwas/31131/هل-يتنافى-الاخلاص-مع-السرور-بثناء-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 006.mp3","categories":["الغسل","التيمم","الرقائق"]},{"id":5564,"question":"إذا اغتسل من الجنابة قبل أذان الفجر ونوى يوم الجمعة؟","title":"هل يجزئ الغسل قبل الفجر للجنابة والجمعة؟","answer":"الجواب: لا، إذا كان قبل الفجر لا، يغتسل يوم الجمعة، إذا اغتسل من الجنابة في الليل قبل الفجر ما يكفي، يُستحب له غسل الجمعة بعد الأذان عند ذهابه إلى الجمعة. س: ولو كان بعد الفجر؟ ج: بعد الفجر يكفي، وإذا اغتسل عند ذهابه إلى الجمعة طيب؛ لأن بينهما مسافة.[1]","link":"https://binbaz.org.sa/fatwas/31516/هل-يجزى-الغسل-قبل-الفجر-للجنابة-والجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 004.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":5574,"question":"المُكره على الجماع؟","title":"هل يجب الغسل على مَن أُكره على الجماع؟","answer":"الجواب: محل نظرٍ والله أعلم، إن خرج المني يغتسل، لكن إذا أُكره ولا خرج مني هذا محل نظرٍ، ولعلَّ الغسل أقرب؛ لأنه شمله: إذا مسَّ الختانُ الختانَ، لعله أقرب.\nوكذلك النائم إذا علم أنه أدخل فرجه، قد يقال أنه يغتسل احتياطًا وإن كان ما قصد، أما الوجوب فمحل نظرٍ؛ لأنه ما عنده قصد ولا فعل شيئًا.[1]","link":"https://binbaz.org.sa/fatwas/31526/هل-يجب-الغسل-على-من-اكره-على-الجماع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 014.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":5830,"question":"التيمم هل الترتيب بالتيمم بين الوجه، والكفين واجب؟","title":"حكم الترتيب في أعضاء التيمم","answer":"الجواب:  على ظاهر الكتاب العزيز فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ [النساء:43] وفي حديث عمار مسح بوجهه، وكفيه، فالواجب أن يبدأ بالوجه، ثم الكفين.  أما في الجنابة فالأمر واسع، التيمم عن الجنابة أمره واسع، لكن الأفضل يبدأ بالوجه، ثم الكفين حتى في الجنابة، أما في الوضوء فالواجب أن يبدأ بالوجه؛ لأن هذا هو المنصوص عليه في كتاب الله، وهو الذي جاء في بعض الروايات، فتفسر الروايات بعضها بعضًا، وتحمل الروايات على ما دل عليه كتاب الله، وقد قال رسول الله: نبدأ بما بدأ الله به في الصفا، والمروة، فهكذا يبدأ بما بدأ الله به في الوضوء، وفي التيمم، هذا الذي ينبغي للمؤمن.","link":"https://binbaz.org.sa/fatwas/1179/حكم-الترتيب-في-اعضاء-التيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_175.mp3","categories":["التيمم","الدعوة والدعاة"]},{"id":6455,"question":"بعض من الناس في البادية يتيممون للصلاة مع وجود الماء الزائد عن شربهم، هل يجوز ذلك؟ وهل لكم توجيه، ونصيحة إلى هؤلاء العامة؟","title":"هل يجوز التيمم مع وجود الماء الزائد عن الشرب؟","answer":"الجواب: هذا لا يجوز، وكل من سأل عن هذا نخبره، وسنكتب في هذا -إن شاء الله- هذا لا يجوز؛ لأن عنده الماء الفاضل، فيجب الوضوء، سواء في البرية في الأسفار، والتنزهات، وعنده ماء، تأتي بالسيارات، يلعبون بالماء في تغسيل الأواني، وفي كذا، وفي كذا، ولا يتوضؤون، هذا لا يجوز. النبي -عليه الصلاة والسلام- كان يتوضأ في الأسفار هو وأصحابه، وقد يكون في السفر ألوف كثيرة، ويتوضؤون، وفي بعض الأحيان قد يقل الماء، فيؤتى له بالإناء -عليه الصلاة والسلام- الصغير فيضع يده فيه؛ حتى ينبع الماء من بين أصابعه، ويتوضأ الناس إلى عند آخرهم، هذا من آيات الله، وقدرته العظيمة -جل وعلا- وكان يلتمس الماء إذا حضرت الصلاة، فإن وجد الماء؛ توضؤوا، وإلا تيمموا. أما أن يكون عنده ماء موجود، وعنده فضل، هذا يلزمه الوضوء، ولا يجوز له التيمم، نعم لو كان الماء قليلًا، والماء بعيدًا عنهم، والباقي لقدر شربهم فقط، أو شرب بهائمهم؛ جاز لهم في تلك الحالة الحاضرة أن يتيمموا؛ لبعد الماء عنهم، وقلة الماء الموجود، هذه حالة خاصة فيها التيمم، أما وجود الماء الكافي، أو الماء قريب؛ فهذا لا يجوز لهم. السؤال: هناك عندهم مرصد ماء مليان، ولما حضرت الصلاة صلوا بدون وضوء؟ الجواب: يلزمهم القضاء. السؤال: قال لهم الشخص: هذا ابن باز يقول ما يتم الصلاة إلا بوضوء، ما دام الوايت موجود عندكم، وصلوا، توضؤوا وصلوا؟  الجواب: الحمد لله، جزاه الله خيرًا، جاء ونبههم، جزاه الله خيرًا.  المقصود هذا يلزمهم لزومًا، يجب على من رأى هذا؛ ينبه عليه، ويقول لهم، هكذا ينبغي للمؤمن، النبي  كان إذا خطب الناس يقول: فليبلغ الشاهد الغائب، فرب مبلغ أوعى من سامع أنتم مثلًا في هذه الندوات تسمعون الفوائد، تبلغون من تظنون أنه يجهل شيئًا مما سمعتم، تقولون: والله سمعنا كذا، لكن بالتثبت.  ترى بعض الناس ما يحسن النقل، قد ينقل الحرام حلالًا، والحلال حرامًا، لا بدّ من التثبت، يتثبت في النقل، ويضبط النقل، ثم ينقل، يبلغ إخوانه في البادية، وفي الحاضرة، في الأشياء التي قد تجهلهم، يقول: والله سمعت كذا من الشيخ فلان، كذا من الشيخ فلان، كذا قال، كذا قال، كذا في الصلاة، في الطهارة، في النفقات، في الصيام، في الحج، في الأمر بالمعروف والنهي عن المنكر، في غير هذا من أمور المسلمين، لا يبخل، يبلغ الفائدة، الرسول ﷺ يقول: بلغوا عني ولو آية، ويقول: فليبلغ الشاهد الغائب، فرب مبلغ أوعى من سامع.","link":"https://binbaz.org.sa/fatwas/2178/هل-يجوز-التيمم-مع-وجود-الماء-الزاىد-عن-الشرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_804.mp3","categories":["التيمم"]},{"id":7022,"question":"بعض المسلمين يخرجون أيام العطل خارج مدينة الرياض للنزهة، غير ناويين السفر، ويأخذون معهم قليلًا من الماء، وعند الصلاة يتيممون بدلًا من الماء؛ بحجة قلة الماء، علمًا أنه باستطاعتهم البحث عن الماء، أو حمله معهم أثناء الرحلة، فهل يجوز التيمم في هذه الحالة، وإذا كان لا يجوز، فما حكم هذه الصلاة بدون وضوء؟","title":"حكم التيمم للصلاة لبعد الماء أو قلته","answer":"الجواب:\n\nإذا خرجوا للنزهة، وحضرت الصلاة، وليست عندهم إلا ماء قليل بقدر حاجتهم -والماء بعيد عنهم- صلوا بالتيمم، ولو أنهم ما حملوه معهم، لكن إذا حملوه معهم يكون أفضل إذا تيسر، لكن ما كل أحد يتيسر له حمل الماء معه.\n\nفإذا تيسر الماء منهم قريب؛ وجب عليهم أن يتوضؤوا، وإذا كان بعيدًا معروفًا يشق عليهم الذهاب إليه، أو يضيعوا أوقاتهم لبعده عنهم؛ فلا حرج أن يتيمموا، وكان الصحابة يتيممون إذا كان الماء بعيدًا عنهم، يشق عليهم.","link":"https://binbaz.org.sa/fatwas/2958/حكم-التيمم-للصلاة-لبعد-الماء-او-قلته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1408.mp3","categories":["الغسل","التيمم"]},{"id":7484,"question":"أيضاً يقول: إذا كنت في عمل أو سفر ثم حان وقت الصلاة ولكن بيني وبين الماء مسافة عشر دقائق أو ربع ساعة، فهل يجوز أن أتيمم مكان طاهر، أو أنتظر حتى أصل الماء؟ أفيدونا عن ذلك جزاكم الله خيراً؟","title":"حكم التيمم مع وجود الماء بعد مسافة قريبة","answer":"الجواب:  هذه المسافة تعتبر قريبة عرفاً، فالواجب الذهاب إلى الماء والوضوء من الماء والغسل إن كان هناك غسل، ولا يجوز التيمم في هذه الحالة؛ لأن المسافة عشر دقائق ربع ساعة يعتبر شيئاً قريباً، وهو يعتبر في العرف ليس ببعيد ولا عذر في ترك الوضوء، بل يلزمه، سواء كنت في عمل أو في سفر يلزمك أن تذهب وأن تتوضأ الوضوء الشرعي، وإن كان عليك جنابة تغتسل وتصلي، وليس هذا البعد عذراً في التيمم؛ لأنه في العرف قريب. نعم.","link":"https://binbaz.org.sa/fatwas/4329/حكم-التيمم-مع-وجود-الماء-بعد-مسافة-قريبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_005/00503.mp3","categories":["التيمم"]},{"id":7691,"question":"هذه الرسالة وردتنا من الرياض أيضاً من مرسلها سليمان محمد التميمي يقول: أصابتني جنابة في البرية، وليس عندي ماء للغسل فتيممت وصليت الفجر أنا وجماعة معي، فلما رجعت إلى الخيمة سألتني زوجتي: كم مرة تيممت؟ فقلت: تيممت مرة واحدة، فقالت: إنه يلزمك تيممان، أحدهما عن الجنابة، والثاني للصلاة، فهل ذلك صحيح أم لا؟","title":"حكم تعدد التيمم بتعدد موجبه","answer":"الجواب: لا ليس بصحيح، الذي عليه الجنابة يكفيه تيمم واحد، النبي ﷺ أمر عماراً أن يتيمم تيمماً واحداً للصلاة وهو عليه جنابة، فإذا ضرب التراب بيديه ومسح بهما وجهه وكفيه كفى ذلك عن الجنابة وعن الحدث الأصغر؛ لأن الله قال: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ [المائدة:6] فالتيمم للحدث الأصغر والأكبر تيمم واحد، وكذلك المرأة التي أصابها الحيض أو النفاس ثم طهرت من حيضها ونفاسها، فإنه يكفيها تيمم واحد عن الحيض وعن الحدث الأصغر، وبعدها تصلي، هذا الواجب، ولا يلزم تيممان: واحد عن الحدث الأصغر، والثاني عن الأكبر، لا، لا يلزم هذا، النية تكفي عن الجميع، إذا نوى الجميع كفى بالتيمم الواحد، مثل الغسل.. مثل الماء، إذا نوى الغسل للطهارتين كفى، وإن كان الأفضل في الغسل أنه يتوضأ وضوء الصلاة ثم يغتسل، أما التيمم فيكفي تيمم واحد، يضرب التراب بيديه ضربة واحدة ثم يمسح بهما وجهه وكفيه بنية الحدث الأكبر والأصغر جميعاً، ويكفيه ذلك والحمد لله.\nالمقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/4890/حكم-تعدد-التيمم-بتعدد-موجبه ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_028/02802.mp3","categories":["التيمم"]},{"id":7874,"question":"سؤاله التالي يقول: في التيمم على المذهب سمعنا أنه لا يجوز بتراب قد استعمل فما الحكم للمرضى الذين يتيممون بتراب من إناء عدة مرات، وهل النهي للكراهة أم لا؟","title":"حكم التيمم بالتراب المستعمل","answer":"الجواب: مراد من قال: لا تيمم بتراب مستعمل أو بماء مستعمل لا يتوضأ به، مرادهم التراب الذي يتساقط من يد الإنسان، التراب الذي تساقط من اليد، أما التراب الذي في الإناء هذا لا يسمى مستعمل؛ لأن المستعمل التراب الذي أخذته اليدان، أما الباقي في الإناء من الماء فهو ما هو مستعمل والباقي من التراب ما هو مستعمل، فلا ينبغي إشكال هذا، نعم. التراب الذي في الصحن أو في ...... نعم ما يكون مستعملاً، المستعمل التراب الذي أخذه في يديه ثم تساقط، هذا هو المستعمل.\nالمقدم: يعني: الذي علق في يديه؟\nالشيخ: علق في يديه، نعم، هذا المستعمل.\nالمقدم: مثل الماء..\nالشيخ: وهكذا الماء الذي علق في اليدين وتقاطر في إناء آخر، هذا مستعمل، والمشهور عند العلماء أنه لا يستعمل، وقال بعضهم: يجوز أن يستعمل أيضاً حتى ولو أنه سقط من اليدين إذا كان نظيفاً ما أصابته النجاسة فهو طهور، وقال قوم: إنه طاهر وليس بطهور فلا يستعمل، وليس هناك حجة واضحة على منع استعماله، ولكن تركه من باب الحيطة حسن.\nأما التراب الذي يبقى في الإناء هذا ما هو مستعمل، وهكذا الماء الذي في الإناء بعدما توضأ منه الإنسان ما هو بمستعمل. نعم.","link":"https://binbaz.org.sa/fatwas/5329/حكم-التيمم-بالتراب-المستعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_056/05608.mp3","categories":["التيمم"]},{"id":8254,"question":"هنا سؤال بعث به أحد الإخوة من العراق وهو الأخ غازي عبد خليفة يقول: سؤالي يتعلق بالصلاة، أنا طالب في الإعدادية ساكن في القسم الداخلي، نهضت في الصباح لكي أؤدي فرض صلاة الصبح، وكان الجو بارداً جداً، وليس لدي أي وسيلة لتسخين الماء، وتمسحت دون أن أغسل رجلي بالماء، فهل هذه الصلاة مقبولة أم تنصحونني بقضائها؟","title":"مشروعية التيمم عند العجز في استعمال الماء للوضوء","answer":"الجواب: هذا فيه تفصيل: إن كنت تستطيع أن تجد ماءً دافياً أو ماءً لا خطر فيه، أو تسخينه من جيرانك أو بالشراء من جيرانك أو من غير جيرانك بالشراء فالواجب عليك أن تعمل ذلك؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] فعليك أن تعمل ما تستطيع من الشراء أو التسخين أو غير هذا من طرق التمكن من الوضوء الشرعي بالماء، فإن عجزت أو كان البرد شديداً عليك فيه خطر، ولا حيلة لك في تسخينه ولا في شراء شيء من الماء الساخن مما حولك فأنت معذور بهذا إذا كان عليك خطر، تعتقد أن عليك خطراً من ذلك في صحتك بالموت أو المرض، فأنت معذور وليس عليك قضاء وعليك التيمم ما تمسح بالماء عليك التيمم، عليك أن تتيمم بالتراب، تضرب يدك في التراب وتمسح وجهك وكفيك، ويكفيك عن الماء عند العجز عن استعماله بسبب برودته وشدة البرد، وعدم وجود ما يدفيك أو يدفي الماء.\nوعليك في هذا العناية والحرص وخوف الله ومراقبته. نعم.","link":"https://binbaz.org.sa/fatwas/6062/مشروعية-التيمم-عند-العجز-في-استعمال-الماء-للوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/09803.mp3","categories":["التيمم"]},{"id":8861,"question":"من احتاج إلى الغسل ولكنه لم يستطع لشدة البرد ولعدم وجود وسيلة لتسخين الماء، فهل يتيمم لصلاة الفجر، ومن فعل ذلك فما الحكم؟","title":"حكم التيمم بدلاً عن الغسل لشدة البرد","answer":"الجواب: إذا كان في محل لا يستطيع فيه تدفئة الماء وليس هناك كن يستكن به للغسل بالماء الدافي وخاف على نفسه فإنه يصلي بالتيمم، ولا حرج عليه لقول الله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ولقول النبي ﷺ: إذا أمرتكم بأمر فأتوا منه ما استطعتم، وقد ثبت أن عمرو بن العاص  كان في غزوة السلاسل أصابته جنابة وكان في ليلة باردة شديدة البرد فلم يغتسل بل توضأ وتيمم وصلى بالناس وسأله النبي ﷺ بعدما قدم من الغزوة فقال: يا رسول الله! فإني خفت على نفسي وتأولت قوله سبحانه: وَلا تَقْتُلُوا أَنفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا [النساء:29] فتبسم النبي ﷺ ولم يقل له شيء ولم يأمره بالإعادة عليه الصلاة والسلام. فدل ذلك على أنه عذر شرعي. نعم.","link":"https://binbaz.org.sa/fatwas/7016/حكم-التيمم-بدلا-عن-الغسل-لشدة-البرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_137/13704.mp3","categories":["التيمم"]},{"id":9841,"question":"تقول السائلة: إن والدها يبلغ من العمر أكثر من خمس وثمانين سنة، وهو مريض لا يستطيع الوضوء بالماء، فتقول: هيأنا له تراباً في إناء ليتيمم منه، فهل يجوز أن يتيمم من هذا التراب شهراً أو أكثر؟","title":"حكم تكرار التيمم بتراب واحد","answer":"الجواب: نعم، لا بأس، يتيمم من التراب المعد له، بلا مدة محدودة، ما دام موجود فيه التراب الحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/8017/حكم-تكرار-التيمم-بتراب-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26207.mp3","categories":["التيمم"]},{"id":10270,"question":"تصاب أصابع قدمي بفطور وذلك من أثر الماء، وقد منعني الطبيب من استعمال الماء، ومن استعمال الجوارب أيضًا، كيف تنصحونني وحالتي والصلاة؟","title":"كيفية وضوء الممنوع من استعمال الماء وصاحب الجبيرة","answer":"الجواب: إذا كان يضرك الماء فلا بأس مثل ما قيل لك، إذا كان يضر قدميك فلا بأس، وإذا كانت الجوارب تضرك فلا بأس بتركها، وإن كانت لا تضر تلبسينها وتمسحين على الجوارب، تلبسينها على طهارة و تمسحين على الجوارب، أما إن كانت الجوارب تضر كما قيل لك، وهكذا الماء فيكفيك التيمم، تغسلين وجهك ويديك وتمسحين رأسك ثم تستعملين التراب بعد التنشيف تضربين التراب مرة واحدة وتمسحين بذلك وجهك وكفيك بالنية عن القدمين، هذا هو المشروع، وهذا هو الواجب إذا كان هناك ضرر بين في غسل القدمين ولبس الجوربين عليهما فإنك توضئين الوضوء الشرعي، يعني: تمضمضين وتستنشقين تغسلين وجهك ويديك وتمسحين رأسك وأذنيك ثم بعد ذلك إذا حصل التنشف بعد ذلك تضربين التراب ضربة واحدة بيديك وتمسحين بهما وجهك وكفيك بالنية عن القدمين؛ لأن العاجز عن استعمال الماء حكمه حكم الذي لم يجده، والله يقول سبحانه: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [النساء:43] فالذي يعجز عن استعمال الماء لمرض أو جراحات حكمه حكم فاقد الماء، يتيمم والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا، هكذا الجريح وصاحب الجبيرة سماحة الشيخ؟\nالشيخ: نعم الجريح وصاحب الجبيرة الجريح إن تيسر المسح على الجرح مسح على الجرح وكفى، وإن كان يضره المسح تيمم إذا كان ما فيه جبيرة، تيمم بعد غسله الأعضاء السليمة ثم إذا يبست يداه يضرب التراب ضربة واحدة يمسح بهما وجهه وكفيه عن الجريح، بالنية عن الجريح.\nأما إذا كان عليه جبيرة فإنه يمسح الجبيرة ويكفي.\nالمقدم: وتكفيه عن التيمم؟\nالشيخ: تكفيه عن التيمم إذا مسح على الجبيرة عند غسل العضو الذي فيه الجبيرة كفى، فإذا كانت الجبيرة في الذراع مسح عليها مع غسل بقية الذراع، وإذا كانت الجبيرة في القدم غسل القدم السليمة وبعض القدم التي عليها الجبيرة ومسح على الجبيرة والحمد الله، ويكفيه عن التيمم، هذا هو الصواب.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8441/كيفية-وضوء-الممنوع-من-استعمال-الماء-وصاحب-الجبيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_337/33710.mp3","categories":["التيمم"]},{"id":10788,"question":"يسأل سؤالًا آخر ويقول: عندما دخلت المسجد رأيت رجلًا يضرب بيديه على الأرض المفروشة حتى أخرجت الغبار، ثم مسح يديه ووجهه ودخل في الصلاة،  هل تجوز وتصح صلاة هذا على هذه الطريقة، مع أن المياه قريبة من المسجد، ولم أر عليه أي أثر يمنعه من الوضوء؟ وهل إذا كانت صلاته غير صحيحة يجب علي أن أخبره كي يعيدها؟","title":"حكم التيمم من غبار الفرش","answer":"الجواب:  نعم، نعم، ليس له التيمم إذا كان يستطيع الوضوء بالماء، والماء موجود، فالصلاة باطلة والتيمم باطل؛ لأن الله يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [النساء:43] فالواجد للماء لا يجوز له التيمم، إلا إذا كان عاجزًا مريضًا يضره الماء، فهذا الذي رأيته تنصحه، وتقول له: لا يجزئك التيمم إذا كنت صحيحًا سليمًا لا يضرك الماء.  أما لو كان يضره الماء أجزأه التيمم من الفرش التي فيها غبار، ولكن كونه يتيمم من التراب من رحبة المسجد، أو غيرها من المواضع التي فيها التراب الطاهر يكون أولى من غبار الفراش، لقوله ﷺ وجعلت تربتها لنا طهورًا إذا لم نجد الماء فكونه يتيمم من التربة نفسها أولى من الغبار الذي في الفراش، والغبار يجزئ كما نص عليه أهل العلم، لكن كونه يتيمم من التراب الموجود الطاهر يكون أكمل وأوفق للسنة. أما إذا كان الرجل عنده مانع من الوضوء؛ لأن به مرضًا يمنعه من استعمال الماء، ويضره استعمال الماء؛ فإن التيمم يجزئه والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8968/حكم-التيمم-من-غبار-الفرش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_351/35105.mp3","categories":["التيمم"]},{"id":10789,"question":"يسأل سؤالًا آخر ويقول: عندما دخلت المسجد رأيت رجلًا يضرب بيديه على الأرض المفروشة حتى أخرجت الغبار، ثم مسح يديه ووجهه ودخل في الصلاة،  هل تجوز وتصح صلاة هذا على هذه الطريقة، مع أن المياه قريبة من المسجد، ولم أر عليه أي أثر يمنعه من الوضوء؟ وهل إذا كانت صلاته غير صحيحة يجب علي أن أخبره كي يعيدها؟","title":"حكم التيمم من غبار الفرش","answer":"الجواب:  نعم، نعم، ليس له التيمم إذا كان يستطيع الوضوء بالماء، والماء موجود، فالصلاة باطلة والتيمم باطل؛ لأن الله يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [النساء:43] فالواجد للماء لا يجوز له التيمم، إلا إذا كان عاجزًا مريضًا يضره الماء، فهذا الذي رأيته تنصحه، وتقول له: لا يجزئك التيمم إذا كنت صحيحًا سليمًا لا يضرك الماء.  أما لو كان يضره الماء أجزأه التيمم من الفرش التي فيها غبار، ولكن كونه يتيمم من التراب من رحبة المسجد، أو غيرها من المواضع التي فيها التراب الطاهر يكون أولى من غبار الفراش، لقوله ﷺ وجعلت تربتها لنا طهورًا إذا لم نجد الماء فكونه يتيمم من التربة نفسها أولى من الغبار الذي في الفراش، والغبار يجزئ كما نص عليه أهل العلم، لكن كونه يتيمم من التراب الموجود الطاهر يكون أكمل وأوفق للسنة. أما إذا كان الرجل عنده مانع من الوضوء؛ لأن به مرضًا يمنعه من استعمال الماء، ويضره استعمال الماء؛ فإن التيمم يجزئه والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8968/حكم-التيمم-من-غبار-الفرش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_351/35105.mp3","categories":["التيمم"]},{"id":10990,"question":"يقول في أحد أسئلته أيضًا: أنا راعي غنم، ومعظم وقتي أقضيه في الصحراء، حيث يندر المطر صيفًا، ويشتد البرد شتاءً، وقد أحتاج إلى الغسل، فهل يصح لي التيمم مع وجود الماء الذي هو للشرب فقط؟","title":"حكم التيمم لمن معه ماء لا يكفي إلا للشرب","answer":"الجواب:  الله سبحانه يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا.. الآية [المائدة:6]، فإذا كان الماء الذي لديك قليلًا لا يكفي إلا للشرب، وليس بقربك ماء تستطيع الذهاب إليه، وتتوضأ منه فلا حرج في التيمم؛ لأن الماء القليل وجوده كالعدم؛ لأنك في حاجة إليه، أما إذا كان في الإمكان الذهاب إلى الماء لقربه منك فإنك تذهب إليه وتتوضأ ولا تتيمم؛ لأن الله يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ [المائدة:6]، وإذا كنت تجد الماء حولك، أو أنت حول قرية تستطيع الذهاب إليها، أو إلى ماء من ماء المطر، أو غير هذا من المياه التي تستطيع الحصول عليها قريبًا منك فعليك أن تتوضأ. وأما إذا لم تستطع: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، لا حرج عليك في التيمم، بل يجب عليك التيمم والصلاة أن تصلي؛ لأنك فاقد للماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9168/حكم-التيمم-لمن-معه-ماء-لا-يكفي-الا-للشرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36502.mp3","categories":["التيمم"]},{"id":11001,"question":"يقول في أحد أسئلته أيضًا: أنا راعي غنم، ومعظم وقتي أقضيه في الصحراء، حيث يندر المطر صيفًا، ويشتد البرد شتاءً، وقد أحتاج إلى الغسل، فهل يصح لي التيمم مع وجود الماء الذي هو للشرب فقط؟","title":"حكم التيمم لمن معه ماء لا يكفي إلا للشرب","answer":"الجواب:  الله سبحانه يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا.. الآية [المائدة:6]، فإذا كان الماء الذي لديك قليلًا لا يكفي إلا للشرب، وليس بقربك ماء تستطيع الذهاب إليه، وتتوضأ منه فلا حرج في التيمم؛ لأن الماء القليل وجوده كالعدم؛ لأنك في حاجة إليه، أما إذا كان في الإمكان الذهاب إلى الماء لقربه منك فإنك تذهب إليه وتتوضأ ولا تتيمم؛ لأن الله يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ [المائدة:6]، وإذا كنت تجد الماء حولك، أو أنت حول قرية تستطيع الذهاب إليها، أو إلى ماء من ماء المطر، أو غير هذا من المياه التي تستطيع الحصول عليها قريبًا منك فعليك أن تتوضأ. وأما إذا لم تستطع: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، لا حرج عليك في التيمم، بل يجب عليك التيمم والصلاة أن تصلي؛ لأنك فاقد للماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9168/حكم-التيمم-لمن-معه-ماء-لا-يكفي-الا-للشرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36502.mp3","categories":["التيمم"]},{"id":11057,"question":"يقول: أحيانًا أتيمم في مكان، وأصلي في مكان آخر قريبًا منه، هل تصح هذه الصلاة؟","title":"حكم التيمم في مكان والصلاة في مكان آخر","answer":"الجواب:  لا حرج، لا حرج أن تتيمم في مكان، وتصلي في مكان آخر، لا بأس بذلك والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9235/حكم-التيمم-في-مكان-والصلاة-في-مكان-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36708.mp3","categories":["التيمم"]},{"id":11914,"question":"هل يجوز لنا التيمم إذا كان البحر قريبًا منا، علمًا بأن الماء الذي معنا مخصص للشرب والأكل؟","title":"حكم التيمم مع قرب ماء البحر","answer":"الجواب:  نعم ليس لكم التيمم، ما دام البحر قريبًا؛ توضؤوا من البحر، يقول فيه النبي ﷺ: هو الطهور ماؤه، الحل ميتته، فالبحر ماؤه طهور والحمد لله، ولو كان مالحًا؛ يلزمكم الوضوء والغسل للجنابة من ماء البحر. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10098/حكم-التيمم-مع-قرب-ماء-البحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42615.mp3","categories":["صلاة المريض","فروض الوضوء وصفته","التيمم"]},{"id":12253,"question":"تقول: امرأة أجريت لها عملية جراحية، فلا تستطيع الوضوء، ولا التيمم، وكذلك لا تستطيع الصلاة وهي قائمة، أو جالسة، فكيف تكون الصلاة حينئذٍ؟","title":"حكم من لا يستطيع الوضوء والتيمم بسبب المرض","answer":"الجواب:  تصلي بالتيمم إذا لم تستطع الماء، تصلي بالتيمم، ييممها أخوها، أو أمها، أو زوجها، أو بعض محارمها .. بالتراب، تأمره تكون ناوية، وهو يمسح وجهها وكفيها بالتراب، التراب الخفيف، ليس من الشرط أن تفعله بيديها هي، إذا كانت عاجزة، ييممها أمها، أو أخوها، أو أبوها، أو زوجها، أو غيرهم من محارمها، يضرب التراب، ثم يمسح وجهها، وكفيها بيديه، بنية الوضوء، وهي تأمره بذلك، وتنوي ذلك، ويكفيها ذلك والحمد لله، ولا تصلي إلا بالتيمم، إذا كانت عاجزة عن الماء. نعم. أما ما يتعلق بالخارج الدبر والقبل، هذا يكفي فيه الاستنجاء، الاستجمار باللبن، أو بالحجارة، أو بالمناديل، الخارج من الدبر والقبل، من البول والغائط، المريض يتمسح بالمناديل، حتى يزيل الأذى من دبره ومن قبله، ذكرًا كان أو أنثى، بشرط أن يكون ثلاث فأكثر، ثلاث مسحات فأكثر، حتى يزيل الأذى، وإذا كان عاجزًا، فالذي يمرضه يقوم بذلك، الممرضة للمرأة، والممرض للرجل، أو أمه، أو أخته، أو زوجته، يقوم بذلك، يزيل الأذى بالمناديل، وهذه حالته ضرورة، حالة ضرورة ... للممرض أن يقوم به مع المريض، والممرضة مع المريضة، الرجل يتولاه الرجل، والمرأة يتولاها المرأة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10453/حكم-من-لا-يستطيع-الوضوء-والتيمم-بسبب-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44904.mp3","categories":["التيمم"]},{"id":12255,"question":"السؤال الأخير الذي نعرضه لأختنا في هذه الحلقة، يقول: ما حكم من كان عنده ماء وهو في الخلاء، ولكنه يتيمم، هل صلاته باطلة؟ وهل عليه كفارة؟","title":"حكم التيمم في الخلاء مع وجود الماء","answer":"الجواب:  إذا كان عنده ماء، يستطيع أن يتوضأ منه، يزيد عن حاجة الشراب والأكل، فإنه يلزمه الوضوء ولا تصح صلاته، يلزمه القضاء، ولا كفارة عليه، بس عليه التوبة، عليه التوبة والاستغفار والندم، وعدم العودة إلى مثل هذا. أما إذا كان الماء الذي عنده قليلًا، بقدر حاجة الشراب، أو الطعام؛ فإنه لا يلزمه الوضوء: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10455/حكم-التيمم-في-الخلاء-مع-وجود-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44906.mp3","categories":["التيمم"]},{"id":12466,"question":"رسالة بعث بها مستمع يقول: المرسل هندي من دير الزور في سوريا يقول: أنا مصاب في يدي اليمنى، وعند الوضوء لصلاة الفجر أشعر بألم من الماء البارد، فهل يجوز لي التيمم، أو كيف توجهونني؟ جزاكم الله خيرًا.","title":"حكم التيمم لمن يتألم من الماء البارد","answer":"الجواب:  عليك أن تسخن الماء حتى يكون دافيًا، سخنه، والحمد لله، أو تأمر من يسخنه لك حتى تستعمل ماء دافيًا لا يؤذيك، ولا يجوز لك التيمم بارك الله فيك، الذي عليك أن تدفئ الماء، وتستعمل الماء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10678/حكم-التيمم-لمن-يتالم-من-الماء-البارد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40419.mp3","categories":["التيمم"]},{"id":12575,"question":"ما هي أسباب التيمم؟ وهل هناك مسافة محدودة إلى الماء؟","title":"أسباب التيمم ومدة الصلاة به","answer":"الجواب:  أسباب التيمم هي أسباب الوضوء، فإذا وجب الوضوء على الشخص، ولم يجد الماء؛ وجب عليه التيمم، وهكذا إذا عجز عن الماء لمرض؛ وجب عليه التيمم للصلاة، لمس المصحف للطواف، فالمقصود أن التيمم يقوم مقام الوضوء، فإذا وجدت أسباب الوضوء، ولم يوجد الماء؛ فإنه يتيمم بالصعيد، يضرب التراب بيديه ضربة واحدة، فيمسح بهما وجهه وكفيه، وهكذا المريض الذي لا يستطيع.. يضره الماء؛ يفعل التيمم.  والصحيح أنه يقوم مقام الطهارة، يرفع الحدث إلى وجود الماء، فإذا تيمم للظهر؛ صلى به العصر إذا كان على طهارة، وهكذا لو تيمم للمغرب؛ صلى به العشاء إذا كان على طهارة، أو تيمم لصلاة الضحى، وبقي على طهارة حتى جاء الظهر؛ صلى بذلك، كما في الحديث: الصعيد وضوء المسلم ، وإن لم يجد الماء عشر سنين والله -جل وعلا- سمى التيمم: طهارة، قال -جل وعلا-: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ مَا يُرِيدُ اللَّهُ لِيَجْعَلَ عَلَيْكُمْ مِنْ حَرَجٍ وَلَكِنْ يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ [المائدة:6] ويقول ﷺ: جعلت لي الأرض مسجدًا وطهورًا وجعل التيمم طهورًا كما أن الماء طهور، هذا هو الصواب في هذه المسألة عند المحققين من أهل العلم، أن التيمم يقوم مقام الماء في رفع الحدث إلى وجود الماء، وأنه لا يبطل بدخول الوقت، ولا بخروجه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10794/اسباب-التيمم-ومدة-الصلاة-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_412/41209.mp3","categories":["التيمم"]},{"id":12593,"question":"المستمع (ع. م. ي. م) من السودان بعث برسالة مطولة، ضمنها عددًا من الأسئلة، يقول في أحد أسئلته: إذا حضرت تشييع جنازة في منطقة يتعذر فيها وجود الماء، فهل يجوز لي التيمم؟","title":"حكم التيمم على الجنازة لعدم وجود الماء","answer":"الجواب:  هذا فيه إجمال: إذا كنت في البرية، ولا عندك ماء؛ فلا بأس أن تصلي بالتيمم، أما إذا كنت في البلد، ولكن المنطقة، ليس فيها ماء؛ فليس لك أن تيمم، بل تذهب إلى المكان الآخر، وتتوضأ، فإن أمكن أن تصلي على الجنازة؛ فالحمد لله، وإلا فلا حرج عليك. وليس لك أن تتيمم من أجل عدم قرب الماء منك، بل لابد من الماء؛ لأن الله يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا [المائدة:6] وأنت واجد ماء في القرية في البلد، لكنك في محل ليس فيه ماء مثلًا قرب البلد في محل، قريب من البلد، أو في بيت ليس فيه ماء، ولكن لو ذهبت إلى الآبار القريبة؛ وجدت الماء، أو إلى البيوت القريبة، وجدت الماء، فليس لك أن تصلي بالتيمم إلا عند عدم الماء، كالذين في البرية، أو في مكان بعيد عن البلد يشق عليه الذهاب إلى محل الماء؛ فيتيمم ويصلي، مثل: المسافر الذي قدم من سفره، وصلى قرب البلد بالتيمم؛ لأن ما عنده ماء، وأحب أن يصلي الصلاة في وقتها، أو في أول وقتها؛ لا بأس، أما أنت تصلي في البلد بالتيمم، لا لمجرد عدم قربه منك في وقت تشييع الجنازة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ! كم هي المسافة التي تقدرونها لكي يباح للإنسان التيمم؟  الجواب: ما ....... مساحة معينة إنما هو المشقة، وعدم يعني تيسر ذلك في وقت قريب، مثل: فوات أول الوقت للفريضة؛ فلا حرج في ذلك، وإن صلاها في آخر الوقت بالماء؛ فلا حرج أيضًا.  المقصود: إذا كان يفوت أول الوقت مثل: بينه وبين البلد كيلوين ثلاثة، وهو ما هو السيارة، يمشي، يعني قد يفوته غالب الوقت، أو معظم ..... يعني نصف الوقت، وكونه يصلي في أول الوقت بالتيمم أفضل مبادرة إلى الصلاة، أما في السيارات فالأمر فيها واسع؛ لأنه يعني ما يشق ..... الأربعة الكيلو والخمسة الكيلو والعشرة الكيلو في إمكانه إنهاؤها، والوصول إلى الماء بسهولة. الحاصل إذا كان التأخير يفوت عليه أول الوقت، وله حكم السفر في حكم السفر؛ فلا بأس أن يصلي بالتيمم، أو خرج في نزهة، وبعد عن البلد، ولو رجع البلد؛ لفاته مثلًا أول الوقت؛ فيصلي بالتيمم كذلك؛ استدراكًا، واغتنامًا للوقت الذي هو وقت الفضيلة. نعم. المقدم: المهم أن يدرك أول الوقت؟ الشيخ: نعم، وإن أخر ولو فاته أول الوقت من أجل الماء؛ فلا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10798/حكم-التيمم-على-الجنازة-لعدم-وجود-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_413/41301.mp3","categories":["التيمم"]},{"id":12767,"question":"من تيمم ليصلي نافلة هل له أن يصلي بذلكم التيمم فريضة، أو لا؟","title":"حكم صلاة الفريضة بتيمم النافلة","answer":"الجواب:  نعم له أن يصلي فريضة إذا كان ما وجد ماءً، واستمر عدم الماء إلى أن جاءت.. مثلًا تيمم لصلاة الضحى؛ لأن ما هناك ماء، أو لأنه مريض لا يستطيع استعمال الماء، ثم جاء الظهر فلا بأس أن يصلي الظهر بالتيمم، إلا إذا برئ من المرض، أو وجد الماء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10981/حكم-صلاة-الفريضة-بتيمم-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41916.mp3","categories":["التيمم"]},{"id":12837,"question":"من السودان المستمع جعفر سليمان محمد بعث برسالة ضمنها جمعًا من الأسئلة في أحدها يقول: هل يجوز التيمم في وقت البرد؟","title":"حكم التيمم للصلاة بسبب البرد","answer":"الجواب:  إذا وقع البرد وأنت في مكان لا حيلة لك بماء دافئ، كالذي في الصحراء، وليس عنده ما يسخن به الماء، ويخشى المضرة عليه من استعمال الماء؛ فإنه يتيمم، والحمد لله، مثلما تيمم عمرو بن العاص في عهد النبي ﷺ لما اشتد البرد وخاف... على نفسه تيمم وأقره النبي، عليه الصلاة والسلام. فإذا تيسر للإنسان ما يسخن به الماء، ومحل به كَنٌ يستطيع أن يغتسل فيه، فإنه يتوضأ بالماء المسخن، ويغتسل به، أما إذا كان في مكان يخشى على نفسه من الخطر، لكونه في مكان بارد، مكان ظاهر للبرد، لا حيلة له في الكن، ولا في الماء المسخن؛ فالله -جل وعلا- يقول: وَلا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ [البقرة:195] ويقول سبحانه: وَلا تَقْتُلُوا أَنفُسَكُمْ [النساء:29] ويقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11051/حكم-التيمم-للصلاة-بسبب-البرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46403.mp3","categories":["التيمم"]},{"id":13340,"question":"إحدى الأخوات المستمعات تقول: السائلة التي لقبت نفسها بالصابرة صبر أيوب من الضفة الغربية قضاء الخليل، تقول: منذ أن كان عمري اثني عشر عامًا، وأنا أصوم وأصلي الفروض الواجبة علي، وبعد خمس وعشرين سنة وقعت في المرض، والآن أشعركم أنني أتألم كثيرًا من الماء، وأقوم بالتيمم، وحينما يأتي إلي المرض؛ أنقطع عن الصلاة، وجهوني تجاه هذه القضية، جزاكم الله خيرًا.","title":"حكم التيمم للمريض وترك الصلاة من أجل المرض","answer":"الجواب: شفاك الله وعافاك، نسأل الله لك الشفاء والعافية من كل سوء، وأن يصلح قلبك ودينك، وأن يعيذنا وإياك من كل سوء، وسائر المسلمين، وإذا كنت يضرك الماء؛ فلا مانع من التيمم، والله يقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] والذي يضره الماء حكمه حكم من لم يجد الماء، يتيمم والحمد لله، يضرب التراب بيديه، ويمسح وجهه وكفيه بذلك، ويكتفي بهذا عن الماء. أما الصلاة فعليك أن تصلي على حسب طاقتك، إن استطعت قائمة؛ صليت قائمة، وإن استطعت قاعدة؛ صليت قاعدة، بدلًا من القيام، إذا عجزت عن القيام، فإن لم تستطيعي القيام، ولا القعود؛ فعليك أن تصلي على الجنب، والأفضل على الجنب الأيمن إذا تيسر ذلك، فإن عجزت؛ فصلي مستلقية، ورجلاك إلى القبلة. ولا يجوز ترك الصلاة أبدًا، بل عليك أن تصلي على إحدى هذه الصفات حسب الطاقة، ما دام العقل موجودًا. إن قدرت قائمة؛ صليت قائمة، وإن عجزت عن القيام؛ صليت قاعدة، وإن عجزت عن القعود؛ صليت على جنب، وإن عجزت؛ صليت مستلقية، هكذا أجاب النبي ﷺ لما سأله بعض المرضى، قال له ﷺ: صل قائمًا، فإن لم تستطع؛ فقاعدًا، فإن لم تستطع؛ فعلى جنب، فإن لم تستطع؛ فمستلقيًا هكذا رواه البخاري في الصحيح بدون ذكر الاستلقاء، وزاد النسائي بإسناد جيد ذكر الاستلقاء على الظهر. فالحاصل: أن هذا هو الواجب على كل مريض أن يصلي على حسب طاقته، ما دام العقل موجودًا، أما إذا زال العقل؛ سقط التكليف كالمجانين، وأشباههم.  نسأل الله لك الشفاء والعافية، وأن يمن عليك بالصحة التي تعينك على طاعة الله كما شرع  نعم.","link":"https://binbaz.org.sa/fatwas/11626/حكم-التيمم-للمريض-وترك-الصلاة-من-اجل-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47615.mp3","categories":["قضايا المرأة","النجاسات وإزالتها","التيمم"]},{"id":13882,"question":"يقول السائل: غالبًا ما أسمع أن من تيمم فلا يجوز له أن يتحدث مع أحد حتى يدخل إلى الصلاة، فإن تحدث فسد تيممه، هل هذا صحيح؟","title":"هل الكلام مع الناس يبطل التيميم؟","answer":"الجواب: هذا لا أصل له، هذا باطل، كلام باطل، له يتحدث ولو بعد التيمم، مثله مثل الوضوء، له أن يتحدث مع الناس، وله أن يقرأ القرآن، له أن يصلي النافلة قبل الفريضة، لا بأس في هذا مثل الوضوء، نعم.","link":"https://binbaz.org.sa/fatwas/12269/هل-الكلام-مع-الناس-يبطل-التيميم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50606.mp3","categories":["التيمم"]},{"id":13946,"question":"يسأل أخونا محسن مرفوء أحمد من العراق عن الطريقة الصحيحة للتيمم؟ جزاكم الله خيرًا، ونفع بعلمكم.","title":"الصفة الصحيحة للتيمم","answer":"الجواب: الطريقة الصحيحة بينها النبي ﷺ في حديث عمار بن ياسر في الصحيحين، قال له: إنما يكفيك أن تقول بيديك هكذا؛ ثم ضرب بهما الأرض ضرب بيديه الأرض.. بكفيه ثم مسح بهما وجهه وكفيه، وهذا مطابق لقوله سبحانه: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ [المائدة:6].  فإذا كان في السفر وليس عنده ماء أو مريض لا يستطيع استعمال الماء ضرب بكفيه الأرض ضربة واحدة ضربة خفيفة ثم مسح بهما وجهه وكفيه، وإذا علق بهما تراب كثير نفخ، نفخ فيهما ثم مسح بهما وجهه وكفيه، هكذا المشروع، ويكفي ضربة واحدة، ضربة واحدة تكفي، هذا هو السنة.  ولو ضرب ضربتين إحداهما لوجهه والثانية لليدين لا بأس، لكن الأفضل والسنة واحدة كما في حديث عمار يضرب بهما الأرض أو إذا كان عنده إناء فيه تراب أو كيس أو ما أشبه ذلك يضرب بيديه التراب ثم يمسح بهما وجهه وكفيه، هذا هو التيمم الشرعي، بالنية؛ بنية الطهارة ويسمي الله يقول: باسم الله، كما يسمي في الماء في الوضوء، وإذا ضرب بيديه التراب مسح بهما وجهه وكفيه، ثم قال: أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمدًا عبده ورسوله، اللهم اجعلني من التوابين واجعلني من المتطهرين، كما يفعل في الماء؛ لأن هذا يقوم مقام الماء، وفق الله الجميع. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12357/الصفة-الصحيحة-للتيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60406.mp3","categories":["التيمم"]},{"id":14008,"question":"أيضًا يقول: إذا كان رجل عليه جنابة ويحب أن يغتسل والطبيب مانعه من الماء أن يصيب رأسه لحسب أنه مريض، ماذا يفعل؟","title":"كيفية غسل الجنب الذي به مرض في رأسه","answer":"الجواب: إذا كان مريضًا يضر الماء رأسه يغتسل في جميع بدنه، وإذا فرغ من ذلك يتيمم بالنية عن رأسه ويضرب التراب بيديه ويمسح وجهه وكفيه بالنية عن رأسه، وهكذا لو كان الطبيب منعه من غسل يده إحدى يديه أو إحدى رجليه يغسل السليم ويتيمم بالنية عن الجزء الذي لم يغسل؛ لأن التيمم يقوم مقام الماء عند العجز عن الماء، الله جعل الأرض طهورًا ومسجدًا ، فالذي لا يستطيع غسل رأسه أو عضو من أعضائه يغسل الباقي ثم يتيمم، يضرب التراب بيديه مرة واحدة ويمسح بهما وجهه وكفيه بالنية عن العضو الذي لم يغسل، سواء رأسه أو غيره. نعم.","link":"https://binbaz.org.sa/fatwas/12424/كيفية-غسل-الجنب-الذي-به-مرض-في-راسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_540/54006.mp3","categories":["التيمم"]},{"id":14266,"question":"يسأل أخونا أيضًا ويقول: بعض الأماكن تكون نادرة المياه إلا ما يكفي للشرب خاصة في المواقع العسكرية النائية، وقد يحتاج الأمر إلى الاغتسال أحيانًا، فهل يكفي التيمم في هذه الحالة؟","title":"حكم التيمم عند وجود ماء لا يكفي إلا للشرب","answer":"الجواب: إذا كان في مكان ليس فيه ماء كالمسافر والسجين اللي ما يعطى ماء فإنه يكفيه التيمم فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، يضرب التراب بيديه ويمسح بهما وجهه وكفيه عن الجنابة وعن الحدث الأصغر، أما إذا كان يستطيع الماء بالطلب أو بالشراء المعتاد أو بالذهاب إليه في الوقت فإنه يتوضأ ولا يتيمم؛ لأن الله يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا [النساء:43]، والرسول ﷺ قال في التيمم: إذا لم يجد الماء. فالمقصود: إنه إذا وجد الماء في السفر أو في الحضر وجب عليه الغسل والوضوء ولو بالشراء الذي ليس فيه إجحاف، وأما إذا عجز عن ذلك فإنه يتيمم؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، ويقول جل وعلا: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا [النساء:43]. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12744/حكم-التيمم-عند-وجود-ماء-لا-يكفي-الا-للشرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62105.mp3","categories":["التيمم"]},{"id":14360,"question":"المستمع سلمان سالم سلامة الرشيدي، بعث يسأل ويقول: نحن عرب بادية، وفي بعض الأحيان نفقد الماء، ولا نجد ما نغتسل به، فكيف نصلي؟جزاكم الله خيرًا.","title":"كيف يصلي فاقد الماء؟","answer":"الجواب: الله يقول سبحانه: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [النساء:43] فإذا كنتم في البادية، أو في الأسفار، ولم تحصلوا على الماء تصلوا بالتيمم؛ لأن الله  قال: وَإِنْ كُنْتُمْ مَرْضَى أَوْ عَلَى سَفَرٍ أَوْ جَاءَ أَحَدٌ مِنْكُمْ مِنَ الْغَائِطِ أَوْ لامَسْتُمُ النِّسَاءَ فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ مَا يُرِيدُ اللَّهُ لِيَجْعَلَ عَلَيْكُمْ مِنْ حَرَجٍ وَلَكِنْ يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ [المائدة:6].\nوقال -عليه الصلاة والسلام-: جعلت لي الأرض مسجدًا وطهورًا فالمسلم متى جاء وقت الصلاة، وليس عنده ماء إلا ماء يسيرًا لشرابه أو لطعامه أو لشرابه وشراب بهائمه، فإنه يصلي بالتيمم، والتيمم ضربة واحدة، يضرب بها الأرض، يضرب بيديه الأرض، ثم يمسح بيديه وجهه وكفيه، هذا هو التيمم، ضربة واحدة يضرب بها الأرض، ثم يمسح بهما وجهه وكفيه، تقوم مقام الماء، هذه الضربة تقوم مقام الماء حتى يجد الماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12840/كيف-يصلي-فاقد-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_487/48707.mp3","categories":["التيمم"]},{"id":14430,"question":"من قرى المدينة المنورة المستمع (ع. ب. س) بعث برسالة يقول فيها: عرفنا أن فريضة الصلاة قد فرضت قبل الهجرة، أي: في ليلة الإسراء والمعراج، هل فريضة الوضوء ومشروعية التيمم أيضًا قبل الهجرة أم بعدها؟ وإذا كانت بعد الهجرة ففي أي السنين جاءت فريضة الوضوء ومشروعية التيمم؟وجهونا حول هذا الموضوع، جزاكم الله خيرًا.","title":"متى شرع الوضوء والتيمم؟","answer":"الجواب: أما الوضوء فالأصل في ذلك أنه شرع مع الصلاة؛ لأن النبي  قال: لا تقبل صلاة بغير طهور فالأصل في هذا أن الله شرع الوضوء مع الصلاة.  أما التيمم فلم يشرع إلا في المدينة بعد مدة طويلة شرع التيمم بعد ذلك في المدينة، وأما الوضوء فهو مشروع مع الصلاة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12929/متى-شرع-الوضوء-والتيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62407.mp3","categories":["التيمم","فروض الوضوء وصفته"]},{"id":14544,"question":"يقول في سؤاله الثاني سماحة الشيخ: نرى البعض من الناس يصلون بدون وضوء نهائيًا، وأحيانًا لا يتمون التيمم مع توفر الماء، وعند مناقشتهم يحتج هؤلاء بأنهم يعيشون في الصحراء والماء قليل، مع أن مصادر جلب الماء موجود والماء متوفر، و هل الصلاة في مثل هذه الحالة صحيحة؟","title":"حكم الصلاة بالتيمم مع وجود الماء","answer":"الجواب: الواجب على كل مسلم أن يتوضأ للصلاة عند وجود الماء والقدرة على استعماله، فإن عجز لبعد الماء، أو عدم وجوده، أو لمرض يمنعه من ذلك، وجب عليه التيمم بالتراب، يضرب الأرض بيديه، ويمسح وجهه وكفيه، هذا هو الواجب، فمن صلى بدون وضوء، ولا تيمم صلاته باطلة، لا بد من أحد الأمرين: الوضوء عند القدرة، وعند وجود الماء، والقدرة على استعماله، وإذا كان قريبًا أمكن نقله يذهب ويتوضأ، أو ينقل الماء في سيارته، أو في دابته ليشرب ويتوضأ. أما من عجز عن الماء لمرض يضره الماء، أو لعدم وجود الماء ليس معه إلا ماء قليل لحاجته لأكله وشربه فإنه يتيمم، والحمد لله؛ لأن الله يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [المائدة:6] ويقول النبي ﷺ: الصعيد وضوء المسلم، وإن لم يجد الماء عشر سنين يتيمم في الأرض التي هو فيها، يضرب التراب بيديه ويمسح وجهه وكفيه، هذا هو الواجب على كل مسلم. ومن عجز عن التيمم وعن الماء فهو معذور، لو كان إنسان مربوطًا في سارية أو عمود، ولا يستطيع لا يتيمم، ولا يتوضأ صلى على حسب حاله، أو مريض لا يستطيع التحرك، وليس عنده من يوضئه، ولا من ييممه صلى على حسب حاله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13040/حكم-الصلاة-بالتيمم-مع-وجود-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55506.mp3","categories":["التيمم"]},{"id":14695,"question":"السائل من الرياض الذي رمز لاسمه بـ(أ. ع. ب) له ثلاثة أسئلة، في السؤال الأول يقول سماحة الشيخ: كنت أريد أن أصلي الظهر في مسجد على الطريق، من مقر عملي، فلم أجد ماء في دورة مياه المسجد، وكان البيت بعيدًا عن المسجد، فخشيت أن تفوتني صلاة الجماعة، فخرجت إلى جوار المسجد، ووجدت ترابًا نظيفًا، فتيممت، وصليت جماعة مع المسلمين، فهل ما فعلته صحيح أم علي أن أعيد الصلاة؟","title":"حكم من تيمم ليدرك صلاة الجماعة","answer":"الجواب: ليس بصحيح، وعليك أن تعيد الصلاة؛ لأن الله يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا [النساء:43] وأنت واجد للماء والحمد لله، بدل المسجد مسجد آخر، تروح مسجد آخر، أو إلى بيتك تتوضأ، ثم تذهب إلى المسجد، وإن فاتت الصلاة صليتها في بيتك، والحمد لله: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. أما أن تيمم لا والماء موجود هذا لا يجوز هذا باطل، نسأل الله العافية، نعم.","link":"https://binbaz.org.sa/fatwas/13191/حكم-من-تيمم-ليدرك-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56019.mp3","categories":["التيمم"]},{"id":14817,"question":"يقول: أخي يصلي، ولكنه يتيمم بحجر، ولا يتوضأ بالماء، مع أنه يستعمل الماء في الاغتسال، وعندما أقول له: لم تفعل ذلك؟ يقول: إن الطبيب منع علي استعمال الماء، فهل صلاته صحيحة بهذا التيمم؟","title":"حكم التيمم مع القدرة على استعمال الماء","answer":"الجواب: إذا كان يستعمل الماء في الغسل ولا يضره الماء في الغسل فمن باب أولى ألا يضره في الوضوء؛ لأن الوضوء أقل ماءً، وأقل كلفة.  فالواجب عليه أن يصلي بالماء، وأن يتوضأ، فإذا كان لا يضره الغسل فإنه لا يضره الوضوء، فالواجب عليه أن يتوضأ، وأن يعصي هذا الطبيب الذي قال له؛ إذا كان جرب الماء، ولم يضره، وليس له التيمم، ثم التيمم بالحجر لا ينفع، الواجب التيمم بالتراب، بصعيد الأرض لا بالحجر، ما دام يريد التراب، فإنه يضرب التراب، يضرب وجه الأرض، ويتيمم منها إذا عجز عن الماء لمرض يضره معه الماء، أو لأنه في سفر لا يجد الماء. والواجب على المؤمن أن يترك الشبهات والوساوس التي لا وجه لها، وليس كل طبيب يطاع قوله، إنما يطاع قول الطبيب الأمين العارف الذي أرشدك إلى ما ينفعك، وحذرك مما يضرك، فلا بأس، وما دمت -أيها المريض- استعملت الماء في الغسل، وهو لا يضرك فمن باب أولى ألا يضرك الوضوء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13334/حكم-التيمم-مع-القدرة-على-استعمال-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64314.mp3","categories":["التيمم"]},{"id":15134,"question":"هذا الأخ السائل من السودان يقول: يذكر بأنه يعمل في البرية، راعي للأغنام، والبرد في الشتاء وخاصة في الصحراء قارس، يقول: هل يجوز لي أن أصلي النافلة وأقرأ من المصحف بالتيمم رغم وجود الماء معي؟","title":"حكم التيمم إذا كان الجو باردًا","answer":"الجواب: يلزمك أن تتوضأ بالماء، وإذا دعت الحاجة إلى تسخينه تسخنه بالنار، فإذا لم يوجد نار والماء شديد يضرك استعماله، ولا تستطيع تيمم، تصلي بالتيمم الفرض والنفل ، واقرأ من المصحف. أما إذا كنت تستطيع تسخينه، أو تستطيع استعماله؛ لأن برودته لا تضرك، فلا بد من استعمال الماء، إما بالتسخين وإما بنفسه إذا كانت برودته لا تضر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13633/حكم-التيمم-اذا-كان-الجو-باردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56408.mp3","categories":["التيمم"]},{"id":15414,"question":"سؤاله الثاني يقول: التيمم هل يسقط عن الجنب الاغتسال بتاتًا؟ وكم صلاةً يمكن أن أصلي به؟ وما هي نواقضه؟","title":"هل يسقط التيمم الاغتسال عن الجنب؟","answer":"الجواب: التيمم يقوم مقام الماء، الله جعل الأرض مسجدًا وطهورًا للمسلمين، فإذا فقد الماء، أو عجز عن المرض قام التيمم مقامه، فلا يزال كافيًا حتى يجد الماء، فإذا وجد الماء وجب عليه الغسل عن جنابته السابقة، وهكذا المريض إذا برئ، وعافاه الله يغتسل عن جنابته السابقة التي طهرها بالتيمم؛ لقول النبي ﷺ: الصعيد وضوء المسلم، وإن لم يجد الماء عشر سنين ثم قال: فإذا وجدت الماء فأمسه بشرتك. فإذا وجد الماء الجنب أمسه بشرته، يعني: اغتسل بعد ذلك عما مضى، وأما صلواته كلها صحيحة بالتيمم عند عجزه عن الماء؛ لعدم وجود الماء، أو عند عجزه عن الماء؛ لأجل المرض الذي يمنعه من الماء حتى ينتهي المرض ويشفى منه، وحتى يجد الماء ولو طالت المدة، نعم. المقدم: إنما بقاؤه بالتيمم لا يجوز بعد أن يجد الماء؟ الشيخ: أو بعد أن يشفى. المقدم: أو بعد أن يشفى؟ الشيخ: نعم.  المقدم: نعم جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13923/هل-يسقط-التيمم-الاغتسال-عن-الجنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68414.mp3","categories":["التيمم"]},{"id":15767,"question":"هل التيمم يكفي لصلاة واحدة فقط، أم أكثر من ذلك؟جزاكم الله خيرًا.","title":"جواز صلاة أكثر من فرض بتيمم واحد","answer":"الجواب: التيمم كالوضوء، هذا هو الأصح من أقوال أهل العلم، التيمم كالوضوء؛ يقول النبي ﷺ: الصعيد وضوء المسلم، وإن لم يجد الماء عشر سنين ويقول -عليه الصلاة والسلام- في الحديث الصحيح: جعلت لي الأرض مسجدًا وطهورًا فسمى ترابها طهورًا، فإذا تيمم للظهر وجاء العصر وهو على طهارة؛ صلى بالتيمم العصر إذا كان معذورًا لمرض يضره الماء، أو لعدم وجود الماء.  فالمقصود: أن التيمم يقوم مقام الماء، فإذا تيمم لصلاة الضحى، وجاء الظهر صلى به، أو تيمم للظهر وجاء العصر وهو على طهارة صلى به، وهكذا كالماء، إلا إذا وجد ما يبطل التيمم كوجود الماء، أو كونه مريض يضره الماء، ثم شفي يستعمل الماء. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14355/جواز-صلاة-اكثر-من-فرض-بتيمم-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_707/nour_70714.mp3","categories":["التيمم"]},{"id":15880,"question":"يسأل سماحتكم عن حكم من لم يتوضأ لبعض الصلوات خوفًا من البرد؟","title":"حكم ترك الوضوء خوفًا من البرد","answer":"الجواب: لا حرج، الحمد لله، إذا كان على وضوء، فالحمد لله يكفيكم الوضوء، أما إذا كان ما هو على وضوء يلزمه الوضوء، ولو كان برد، يسخن الماء، الحمد لله، يسخن الماء، ويتوضأ، نعم.\nالمقدم: جزاكم الله خيرًا، إذا كان بعيدًا عن وسائل التسخين سماحة الشيخ؟\nالشيخ: إذا كان عليه خطر ويضره الماء يتيمم، إذا كان برد ولا عنده شيء مما يسخن به الماء، ويضره الماء يتيمم والحمد لله؛ عذر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14472/حكم-ترك-الوضوء-خوفا-من-البرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74417.mp3","categories":["صلاة المريض","فروض الوضوء وصفته","التيمم"]},{"id":15990,"question":"يقول: سافر مجموعة من الناس ومعهم ماء كثير محمول فوق السيارات، وهو زائد عن حاجتهم تقريبًا إلا أنهم تيمموا، فاختلفوا حينئذٍ، البعض قال بالجواز، والبعض الآخر يقول: لا يجوز، بل يجب أن نتوضأ من هذا الماء ما هو رأي سماحتكم؟","title":"حكم من تيمم مع وجود ماء زائد عن حاجته","answer":"الجواب: الصواب أن عليهم الوضوء، إذا كان الماء فيه فضل الصواب عليهم الوضوء إذا صلوا بالتيمم لا يصح، أما إذا كان الماء قليلًا حق شرابهم وحاجاتهم، فلا بأس أن يصلوا بالتيمم، أما إذا كان الماء كما قال السائل كثيرًا، وفيه فضل عن حاجتهم، فإن الواجب أن يصلوا بالوضوء لا بالتيمم، ومن صلى بالتيمم يعيد. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14609/حكم-من-تيمم-مع-وجود-ماء-زاىد-عن-حاجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74705.mp3","categories":["التيمم"]},{"id":16734,"question":"من ليبيا بني غازي رسالة بعث بها أحد الإخوة المستمعين من هناك، يسأل في أحد أسئلته ويقول: أنا (س. ج. ع) من بلغازي، أسأل عن كيفية التيمم من الجنابة إذا عدم الماء، أو كان موجودًا، ولكن البرد شديد؟","title":"كيفية التيمم عن الجنابة","answer":"الجواب: مثل التيمم عند عدم الماء، ومثل التيمم عن الوضوء، من فقد الماء يتيمم عن الجنابة والوضوء، ضرب بالتراب بيديه، فيمسح بهما وجهه وكفيه ضربة واحدة، عن الوضوء وعن الغسل، وعن الحيض أيضًا؛ عند عدم الماء، يضرب التراب بيديه ضربة واحدة، يمسح بهما وجهه، وكفيه ناويًا الوضوء، أو ناويًا غسل الجنابة، أو ناوية المرأة غسل الحيض، أو النفاس عند عدم الماء، وهكذا عند عدم وجود الماء، لكن مع المرض الذي يمنع من استعمال الماء، أو مع البرد الشديد، وليس عنده ما يسخن به الماء، هذا معذور. فالتيمم عن الجنابة، والحيض، والحدث الأصغر كله واحد، ضربة واحدة، هذا هو الأفضل، يمسح بها وجهه وكفيه، يمسح بأطراف أصابعه وجهه، وبيديه كفيه ظاهرهما وباطنهما، هذا هو التيمم الشرعي، كما قال الله -جل وعلا-: لَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ [المائدة:6]. فالذي لم يجد الماء؛ يمسح، يضرب التراب بيديه، ثم يمسح بهما وجهه، وكفيه، ظاهرهما، وباطنهما بنية الوضوء، أو بنية الجنابة، أو بنية الحيض، والنفاس من المرأة، وإن ضرب ضربتين: إحداهما لوجهه، والثانية لكفيه؛ فلا بأس، لكن الأفضل ضربة واحدة، كما صح عن النبي ﷺ من حديث عمار في الصحيحين، أنه علم عمار قال: إنما يكفيك أن تضرب بيديك الأرض ضربة واحدة، ثم تمسح بهما وجهك وكفيك لما سأله عن التيمم للجنابة، الضربة الواحدة كافية، وهي السنة، يمسح بأطراف أصابعه وجهه، ويعمه، ثم يمسح بكلتا يديه، كل واحدة على الأخرى، ظاهرهما وباطنهما، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15509/كيفية-التيمم-عن-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_821/nour_82113.mp3","categories":["التيمم"]},{"id":16778,"question":"هذا سائل للبرنامج السائل محمد عبدالله من السودان يقول: سماحة الشيخ! إذا كان الماء موجودًا هل يجوز أن يتيمم الإنسان لذلك؛ خوفًا من البرد؟","title":"حكم التيمم لشدة البرد مع وجود الماء","answer":"الجواب: إذا كان الماء موجودًا فليس للمسلم أن يتيمم، بل عليه أن يستعمل الماء، لقول الله : فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا [النساء:43] وفي الحديث الصحيح: جعلت لي الأرض مسجدًا وطهورًا إذا لم نجد الماء لكن إذا كان البرد شديدًا، يخشى على نفسه منه، وليس هناك ما يسخنه به؛ فله عذر؛ لأن الله يقول: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119] ويقول : وَلا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ [البقرة:195]. فإذا كان الماء باردًا، وليس هناك ما يدفئه به؛ فإنه لا يلزمه الغسل بالماء؛ لما فيه من الخطر، وله التيمم حينئذ، وقد وقع هذا لعمرو بن العاص  في بعض أسفاره، أصابته جنابة، والبرد شديد، فلم يستطع أن يغتسل؛ فتيمم، فأقره النبي ﷺ على ذلك، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15521/حكم-التيمم-لشدة-البرد-مع-وجود-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_585/58504.mp3","categories":["التيمم"]},{"id":17140,"question":"المستمع (م. س. خ) من حائل بعث برسالة ضمنها سؤالين؛ في سؤاله الأول يقول: التيمم للحاجة هل هو ضربة في الأرض واحدة، أو أكثر، ذلك أن بعض الأشخاص قال: لا بد من ضربات ثلاث، وجهونا إلى الصواب؟ جزاكم الله خيرًا.","title":"كيفية التيمم","answer":"الجواب: الصواب أن يكون التيمم ضربة واحدة، هذا هو الأفضل، وإن ضرب ضربتين فلا بأس، لكن الصواب، والأفضل ضربة واحدة، لما في الصحيحين من حديث عمار بن ياسر -رضي الله تعالى عنه- أنه سأل النبي عن ذلك -عليه الصلاة والسلام-فبين له النبي ﷺ قال: أن تقول هكذا..  ثم ضرب النبي ﷺ بيديه الأرض ضربة واحدة، ثم مسح بهما وجهه وكفيه. فدل ذلك على أن هذا هو السنة: ضربة واحدة، ثم تمسح بالكفين وجهك، وكفيك إلى الرسغ، الذراع ما يمسح، ولكن الكف فقط، من أطراف الأصابع إلى الرسغ، هذا هو السنة، ولو ضرب ضربتين، واحدة للوجه، وواحدة ليديه؛ فلا حرج في ذلك، لكن الأفضل ضربة واحدة، هكذا جاءت السنة الصحيحة عن رسول الله ﷺ. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15967/كيفية-التيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_832/nour_83203.mp3","categories":["التيمم"]},{"id":17443,"question":"رسالة مؤثرة للغاية سماحة الشيخ، باعثتها إحدى الأخوات المستمعات تقول: أختكم في الله (ح. ع. ع) تقول عن نفسها: السلام عليكم ورحمة الله وبركاته، وبعد. أنا فتاة أصبت بحادث سيارة منذ أربع سنوات، تسبب لي هذا الحادث في شلل كامل، ما عدا الذراعين فهما سليمتان، والحمد لله، بعد إصابتي بهذا الحادث كنت أصلي بدون تيمم، أو وضوء، وسمعت من بعض الأخوات أنه يجب علي أن أتيمم، وأستعين في ذلك بخادمة، أو أي أحد يقوم بالضرب على التراب مرة واحدة، ثم أمسح على وجهي، وكفي، مع العلم أنه بعد التيمم لا أدري هل ظهر أثر التراب على مناطق التيمم، أو لا؟ ثم إنه عندما أشرع في الصلاة في بعض الأوقات لا أضبط نفسي بحكم الشلل، وقد ينتقض وضوئي، أرجو من سماحتكم توجيهي -جزاكم الله خيرًا- كما أرجو من سماحتكم الدعوات الطيبة؛ لعل الله أن ينفع بها.","title":"كيفية التيمم والصلاة لمن أصيب بالشلل","answer":"الجواب: وعليكم السلام ورحمة الله وبركاته، نسأل الله لك الشفاء والعافية، نسأل الله أن يمنحك الشفاء والعافية ويجمع لك بين الأجر والعافية، متى فعلت التيمم؛ كفى، ولو ما ظهرت آثار التراب عليه، متى ضربت التراب بيديك، أو من ينوب عنك، ضرب التراب بأمرك، ونيتك، ومسح على وجهك، وعلى كفيك؛ كفى ذلك، والحمد لله، وإن لم تعلمي ظهور آثار التراب، المهم أن يضرب التراب النائب عنك، أو أنت بنفسك، ثم تمسحين أنت، أو النائب وجهك والكفين بنية الطهارة، والحمد لله. وأما ما يتعلق بخروج الحدث في الصلاة فهذا فيه تفصيل: إن كان الحدث دائمًا معك في كل وقت؛ فلا يضرك خروجه في الوقت ما بعد الطهارة، أما إن كان لا، ليس بدائم، فإنه متى خرج تبطل الصلاة، وعليك أن تعيدي التيمم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16305/كيفية-التيمم-والصلاة-لمن-اصيب-بالشلل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83608.mp3","categories":["صلاة المريض","فروض الوضوء وصفته","التيمم"]},{"id":17737,"question":"يقول: أرجو من سماحة الشيخ بيان كيفية التيمم الصحيح؟ وهل يشترط في الصعيد الطاهر أن يكون ترابًا، أم يكفي التيمم على الحجارة؟","title":"كيفية التيمم الصحيح","answer":"الجواب: الواجب التراب إذا وجد؛ لقوله ﷺ: جعل التراب لي طهورًا ولقول الرب جل وعلا: فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ [المائدة:6]، والصعيد هو وجه الأرض، قوله: منه يدل على أن له غبار يلتصق باليد والوجه قوله: منه، فإذا لم يتيسر ذلك تيمم من الأرض التي عنده، سواء كانت الأرض صفا أو رمل أو سبخة فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ؛ لعموم قوله ﷺ: جعلت لي الأرض مسجدًا وطهورًا.\nفالأرض تعم الأرض السبخة والرمل وذات الحصى كله، إذا ما تيسر تراب لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] ، لكن إذا وجد التراب فإنه يتيمم بالتراب. نعم.\nالمقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/16693/كيفية-التيمم-الصحيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59603.mp3","categories":["التيمم"]},{"id":17885,"question":"هذا السائل سوداني ومقيم بالمنطقة الشمالية يقول سماحة الشيخ: نحن في المنطقة الشمالية عندنا برد قارس أيام الشتاء لدرجة أن الماء وصل إلى التجمد في بعض الأحيان، هل يجوز أن أتيمم مع أنني فعلت ذلك لمدة ثلاث شهور؟ هل علي ذنب في ذلك؟","title":"حكم التيمم خوفًا من الماء البارد","answer":"الجواب: ليس لك التيمم وأنت تقدر على الماء الساخن، التيمم لمن عجز عن الماء الساخن في وقت البرد كما فعل عمرو بن العاص في بعض الغزوات لما اشتد البرد وخاف على نفسه تيمم، أما الذي يستطيع الماء الساخن فليس له التيمم، يسخن الماء ويتوضأ ويتروش إذا كان في مكان يتقي فيه البرد في خيمة أو بيت ونحو ذلك، أما العاجز الذي ما عنده ما يسخن به فلا بأس أن يتيمم إذا خشي على نفسه، الله يقول جل وعلا: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]، ويقول سبحانه: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا[البقرة:286]، ويقول سبحانه: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ[الأنعام:119]. نعم.\nوعليك القضاء، على هذا قضاء هذه الصلوات التي تركها. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16893/حكم-التيمم-خوفا-من-الماء-البارد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78007.mp3","categories":["التيمم"]},{"id":18615,"question":"السائلة ندواي تقول في هذا  سماحة الشيخ، تذكر بأن والدتها مريضة ولا تستطيع الذهاب إلى دورات المياه -أكرمكم الله- وتقوم بالتيمم في كل الأوقات للصلاة، ولكن عندما تجد نفسها نشيطة تتوضأ بالماء؛ لأنها معاقة، فما توجيهكم لها؟","title":"حكم تيمم المريض لأغلب الصلوات","answer":"الجواب: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] عليها أن تتقي الله إن استطاعت تذهب لدورة المياه فلا بأس، وإلا تستجمر بمناديل ثلاث مرات أو أكثر حتى تنقي محل البول والغائط وتتيمم، فإن استطاعت أن تذهب إلى دورة المياه، أو كان عندها أحد يوضيها توضأت بالماء بعد الاستنجاء بالمناديل واللبن ونحوه، تستجمر باللبن ثلاث مرات أو أكثر أو بالمناديل الخشنة ثلاث مرات، أو أكثر عن البول والغائط، ثم تتوضأ وضوء الصلاة بنفسها، أو بمن يساعدها كبنتها وأختها، ونحو ذلك، أو تيمم إن عجزت بضرب التراب مرة واحدة، ثم تمسح وجهها وكفيها.","link":"https://binbaz.org.sa/fatwas/17722/حكم-تيمم-المريض-لاغلب-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91821.mp3","categories":["التيمم"]},{"id":18707,"question":"يقول هذا السائل الذي رمز لاسمه بـ (أ. ح. ع) يقول في سؤاله: أفيدكم سماحة الشيخ بأنني رجل كبير في السن أبلغ من العمر السبعين عامًا، وأنا أصلي الفروض الأربعة ما عدا صلاة الفجر، لا أستطيع أن أصليها حيث أنني لا أستطيع الوضوء، ونصحوني بعض الناس بعدم تشغيل المكيف؛ لأنه يؤثر على ركبتي، ولكنني لا أستغني عن هذا المكيف لشدة الحر، بعض الناس أفادوني قالوا لي: تيمم، والبعض قالوا: لا يجوز لك أن تتيمم حيث أن الماء موجود، فإذا حضر الماء بطل التيمم، فهل علي ذنب إذا تركت صلاة الفجر؟الشيخ: أعد أعد.المقدم: يقول هذا السائل: أفيدكم بأنني رجل كبير في السن أبلغ من العمر السبعين عامًا، وأنا أصلي الفروض الأربعة ما عدا صلاة الفجر لم أستطيع أن أصليها حيث أنني لا أستطيع الوضوء، ونصحوني بعض الناس بعدم تشغيل المكيف؛ لأنه يؤثر على ركبتي، ولكنني لا أستغني عن هذا المكيف لشدة الحر، وبعض الناس أفادوني وقالوا لي: تيمم، والبعض الآخر قالوا لي: التيمم غير مجزئ؛ لأن الماء موجود، فهل علي ذنب إذا تركت صلاة الفجر، حيث أني معذور، أو يجوز أن أصليها مع صلاة الظهر، ويجوز لي التيمم؟","title":"كيفية الطهارة للعاجز عن الوضوء","answer":"الجواب: الواجب عليك أن تصلي الفجر في وقتها، وإن كنت تستطيع تصليها في المسجد مع الجماعة وجب عليك أن تصلي مع الجماعة، فإن كان لا تستطيع لمرض في ركبتيك صلها في البيت، وعليك أن تتوضأ، ولو بماء مسخن إذا كان يشق عليك البارد يكون بماء مسخن حتى توضأ: تغسل وجهك، ويديك، وتمسح رأسك، وتغسل رجليك، فإذا كنت معك مرض يمنع من ذلك لا تستطيع الوضوء، وليس هناك زوجة تعينك على هذا الشيء أو ولد أو نحو ذلك؛ تيمم عند العجز؛ لأن الله يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا[النساء:43]. وهكذا العاجز الذي يجد، لكن لا يستطيع العمل لا يستطيع أن يتوضأ حكمه حكم من لم يجد، أما إذا كنت تستطيع تستعمل الماء في غرفتك، يحضر عندك الماء بإناء توضأ فيه؛ تغسل وجهك، ويديك، وتمسح رأسك، وتغسل رجليك بماء دافي؛ يلزمك، وليس لك التيمم. أما القبل والدبر فعليك أن تستعمل الاستجمار بالمناديل ويكفي، إذا مسحت الدبر والقبل بالمناديل ثلاث مرات فأكثر حتى تنقي المحل كفى، ويسمى الاستجمار، ثم توضأ وضوء الصلاة، تمضمض وتستنشق، وتغسل وجهك ويديك مع المرفقين، تمسح رأسك مع الأذنين، وتغسل رجليك بالماء المسخن، وإذا تيسر أن يساعدك أمك، أو أختك، أو زوجتك، أو ولدك؛ فالحمد لله، فإن عجزت عن هذا كله فالتيمم، والحمد لله، بالتراب في وجهك وكفيك، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17815/كيفية-الطهارة-للعاجز-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78812.mp3","categories":["صلاة المريض","التيمم"]},{"id":18730,"question":"من سوريا هذا السائل أحمد الشفري يقول: إذا توفر الماء وهذا الماء يكفي للوضوء ولا يكفي لرفع الجنابة، فهل يجوز التيمم بالتراب لرفع الجنابة، والوضوء بالماء لكل صلاة؟","title":"حكم التيمم لقلة الماء ورفع الحدث الأصغر والأكبر","answer":"الجواب: نعم إذا كان الماء قليلًا لم يستطع أن يكمل به الغسل يتوضأ وضوء الصلاة، ويتيمم للباقي؛ لأن الرسول ﷺ يقول: إذا أمرتكم بأمر فأتوا منه ما استطعتم وهذا معنى قوله تعالى: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16] فإذا كان الماء قليل توضأ به وتيمم، ومن هذا قصة عمرو بن العاص  لما اشتد عليه البرد، وخاف من ذلك؛ توضأ ثم تيمم للجنابة، فهذا إذا كان الماء قليلًا توضأ منه، وتيمم للجنابة، وهكذا لو كان الماء عنده لا يكفيه إلا لشربه وأكله يتيمم للجنابة وغيرها ويكفي. المقصود: أنه يعمل ما يستطيع إذا كان الماء قليلًا لا يتمكن من الاغتسال به توضأ منه، وإن كان الوضوء أيضًا قد يشق عليه؛ لأن الماء قليل لا يتوضأ، يخليه لشربه، ويتيمم، والحمد لله. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17852/حكم-التيمم-لقلة-الماء-ورفع-الحدث-الاصغر-والاكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78908.mp3","categories":["التيمم"]},{"id":19027,"question":"يقول السائل: بعض الناس إذا كان الماء قليلا يستنجي به ثم يتيمم، هل يجوز له ذلك؟","title":"حكم من كان معه ماء قليل فاستنجى به ثم تيمم","answer":"الجواب: نعم، يستنجي بالماء ثم يتيمم؛ لأن الاستنجاء ما فيه تيمم لابد من إزالته لكن لو تيسر أنه يستجمر إذا تيسر له تراب أو لَبِن يستجمر ويترك الماء للوضوء يكون هذا أولى، إذا كان يعرف الاستجمار يستجمر ثلاث مرات فأكثر حتى ينقي المحل باللَّبِن أو بالمناديل أو بالتراب حتى ينقي المحل الدبر والذكر بالتراب أو بالمناديل الخشنة أو باللَّبِن ثلاث مرات أو أكثر، ثم يترك الماء للوضوء لغسل وجهه ويديه ومسح رأسه وغسل رجليه، يكون هذا أولى إذا تيسر ذلك.","link":"https://binbaz.org.sa/fatwas/18194/حكم-من-كان-معه-ماء-قليل-فاستنجى-به-ثم-تيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88302.mp3","categories":["التيمم"]},{"id":19050,"question":"يسأل أخونا ويقول: إذا فقد المؤمن الماء، وذهب إلى المسجد فلم يجد به ماء هل له أن يتيمم؟ أم عليه أن يبحث عن الماء عند جيرانه ويبحث عنه في حوالي كيلو متر مربع كما يقول بعض الخطباء؟","title":"حكم من لم يجد الماء وهو في البلد","answer":"الجواب: ما دام في البلد فعليه أن يبحث عن الماء وليس له التيمم، بل يبحث عن الماء ويشتريه، إن تيسر بغير شراء فالحمد لله وإلا فليبحث عنه ويشتريه ويتوضأ ويشرب. أما في الصحراء في الأسفار فإنه إن كان في مظنة ماء التمس الماء، وإن كان ليس في مظنة ماء ما حوله غدران ولا حوله آبار فإنه يتيمم، والحمد لله. المقدم: جزاكم الله خيرًا، تحديد المساحة بكيلو متر؟ الشيخ: ما في حد محدود عرفًا، إذا كانت المسافة عرفًا، يعني: ما يشق عليه الذهاب إلى الماء ذهب إلى الماء في السفر، أما في البلد فيلزمه الشراء ولا يتحدد بشيء؛ لأن الماء موجود، لكن هذا في السفر إذا كان يعلمه قريبًا، يعني: لو ذهب إليه لا يشق عليه ذهب إليه وتوضأ وإلا صلى بالتيمم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18212/حكم-من-لم-يجد-الماء-وهو-في-البلد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_928/nour_92805.mp3","categories":["التيمم"]},{"id":19107,"question":"رسالة وصلت إلى البرنامج من اليمن باعثها المستمع: صالح سالم يقول في أحد أسئلته: هل التيمم يصلح للصلوات كلها؟ أم يتيمم المرء لكل صلاة؟ جزاكم الله خيرًا.","title":"حكم أداء عدة صلوات بتيمم واحد","answer":"الجواب: الصواب أنه كالماء، يكفي في الصلوات كلها؛ لأن الرسول عليه الصلاة والسلام قال في الحديث الصحيح: وجعلت لي الأرض مسجدًا وطهورًا فسماها طهورًا، وفي اللفظ الآخر: وجعلت تربتها لنا طهورًا، وفي اللفظ الثالث: وجعل التراب لي طهورًا كلها أحاديث صحيحة، وقال عليه الصلاة والسلام: الصعيد وضوء المسلم وإن لم يجد الماء عشر سنين . فإذا تيمم عند عدم الماء للمغرب مثلًا، وبقي على طهارته حتى جاء العشاء؛ يصلي به العشاء والحمد لله، هذا هو الصواب. وهكذا لو تيمم للظهر، وجاء العصر وهو على طهارته، أو جاء العصر والمغرب وهو على طهارته؛ صلى بذلك، والحمد لله، هذا هو الصواب؛ لأنه كالماء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18282/حكم-اداء-عدة-صلوات-بتيمم-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_797/nour_79707.mp3","categories":["التيمم"]},{"id":19705,"question":"يقول: غالبًا ما يكون مني في وقت البرد أنني أتوضأ لصلاة الظهر والعصر، أما بقية الفروض أتيمم تيممًا خوفًا من البرد، هل علي إثم في ذلك أم لا؟","title":"التيمم للصلاة خوفًا من البرد","answer":"الجواب:\nلا يجوز هذا، الواجب أن تصلي بالوضوء، ولا تتيمم لأجل البرد، عليك أن تسخن الماء، تدفئ الماء وتتوضأ بالماء لتصلي، ولا يجوز لك أن تتيمم والماء موجود، والقدرة موجودة على تسخينه، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/25510/التيمم-للصلاة-خوفا-من-البرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37611.mp3","categories":["التيمم"]}]
